INSERT INTO `attempts` (`id`, `paper_id`, `paper_name`, `started_at`, `finished_at`, `total_score`, `max_score`, `answered`, `correct`) VALUES (16, 62, '进阶版第20套', '2026-11-10 11:49:54', '2026-11-10 11:50:39', 24.4, 84.0, 90, 32);
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (1, 1, 1, 1, 'judge', 0.6, '某小学数学老师教学乘法时，先让学生用加法算 3 + 3 + 3 + 3 = 12，再引入乘法 3×4 = 12。这种从加法到乘法的学习属于下位学习。', '[["A","正确"],["B","错误"]]', '["A"]', '乘法是几个相同加数连加的简便运算，是加法概念下的派生类属概念。学生在已掌握加法的基础上学习乘法，新概念从属于原有概念，属于奥苏贝尔所说的下位学习（派生类属学习）。', '["A"]', 1, 0.6, '2026-11-09 17:15:55');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (2, 1, 2, 2, 'judge', 0.6, '高一学生小柯在“学医还是学文”之间犹豫：父母希望他学医，他自己热爱文学，两个目标都想得到却只能选择其一。小柯面临的这种心理冲突属于趋避冲突。', '[["A","正确"],["B","错误"]]', '["B"]', '两个都想要的目标只能择其一，属于双趋冲突（接近—接近型冲突）。趋避冲突是指同一个目标同时具有吸引力和排斥力；双避冲突是两个目标都想回避却必须选择其一。题干把双趋冲突误判为趋避冲突。', '["A"]', 0, 0.0, '2026-11-09 17:15:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (3, 1, 3, 3, 'judge', 0.6, '某中学物理老师在学生回答与预设答案不同时，总是追问“你为什么这样想”，要求学生说明理由和依据。这种做法有利于培养学生的批判性思维。', '[["A","正确"],["B","错误"]]', '["A"]', '批判性思维要求学生对观点进行理性审视、有根据地思考和论证。教师持续追问理由和依据，能促使学生不盲从结论、学会用证据支持观点。', '["A"]', 1, 0.6, '2026-11-09 17:15:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (4, 1, 4, 4, 'judge', 0.6, '小学六年级学生小芳学完百分数后，能用百分数表示折扣、利率等生活中的比例关系。这种把课堂知识用于新情境的表现体现了学习迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '学习迁移是指一种学习对另一种学习的影响。学生把课堂上获得的百分数知识运用到折扣、利率等陌生的生活情境中，属于知识在新情境中的正迁移。', '["A"]', 1, 0.6, '2026-11-09 17:15:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (5, 1, 5, 5, 'judge', 0.6, '某市教育局在评估中发现某校向学生统一推销教辅资料并收取费用，遂责令学校立即整改、退还费用。该教育局的处理于法有据。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国义务教育法》第二十五条，学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益；《中小学教师违反职业道德行为处理办法》也明令禁止教师强制或变相强制学生订购教辅。教育行政部门有权责令改正、退还费用。', '["A"]', 1, 0.6, '2026-11-09 17:15:57');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (6, 1, 6, 6, 'judge', 0.6, '某小学教师为提高成绩，每天布置大量重复性抄写作业，多数学生要写到深夜。该做法违反了“双减”政策关于作业总量和时长调控的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》要求小学三至六年级书面作业平均完成时间不超过60分钟，并鼓励布置分层、弹性和个性化作业，避免机械重复训练。大量重复性抄写加重了学生负担。', '["A"]', 1, 0.6, '2026-11-09 17:15:57');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (7, 1, 7, 7, 'judge', 0.6, '英语考试中，小明做阅读理解时先快速浏览全文把握结构，再带着题目回读相关段落。小明运用的主要是元认知策略。', '[["A","正确"],["B","错误"]]', '["A"]', '先浏览全文以确定阅读目标和重点，属于元认知策略中的计划策略；带着问题有针对性地回读、随时检验自己是否读懂，属于监控策略。二者均属元认知策略。', '["A"]', 1, 0.6, '2026-11-09 17:15:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (8, 1, 8, 8, 'judge', 0.6, '心理辅导老师把辅导中获悉的学生家庭变故等隐私，当作谈资告诉了其他任课教师。该做法侵犯了学生的隐私权。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国未成年人保护法》第四条规定处理未成年人事项应当保护未成年人隐私权和个人信息。心理辅导记录涉及未成年人个人隐私，未经本人及其监护人同意不得向无关人员披露。', '["A"]', 1, 0.6, '2026-11-09 17:15:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (9, 1, 9, 9, 'judge', 0.6, '某初中教师试行翻转课堂：基础知识由学生课前借助微课自学，课堂主要用于答疑、探究和协作练习。这种模式有利于培养学生的自主学习能力。', '[["A","正确"],["B","错误"]]', '["A"]', '翻转课堂把知识传授前移到课前由学生自主完成，课堂则转向深度学习与合作探究，客观上要求并锻炼学生自我规划、自我监控的学习能力。', '["A"]', 1, 0.6, '2026-11-09 17:15:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (10, 1, 10, 10, 'judge', 0.6, '某小学教师以成绩差为由，长期安排一名学生单独坐在教室最后一排。该做法没有侵犯学生的合法权益。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《中华人民共和国义务教育法》和《未成年人保护法》，学生在入学、升学等方面依法享有平等权利，其人格尊严应受尊重。因成绩差而将学生孤立地安排在最后一排，带有歧视和标签意味，侵犯了学生的平等受教育权和人格尊严。', '["A"]', 0, 0.0, '2026-11-09 17:15:59');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (11, 1, 11, 11, 'judge', 0.6, '某中学组织学生停课参加某商家开业庆典以烘托人气，并接受了商家支付的“活动费”。学校认为这属于正常的社会实践活动，于法不悖。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国义务教育法》第二十五条明确禁止学校以向学生推销或者变相推销商品、服务等方式谋取利益。组织学生参加商业庆典并收取费用，既影响正常教学秩序，又属利用学生牟利的违法行为。', '["A"]', 0, 0.0, '2026-11-09 17:15:59');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (12, 1, 12, 12, 'judge', 0.6, '语文老师教一篇新课文时，先让学生默读感知，再指名朗读体会情感，最后组织讨论、归纳主旨。这一安排符合由感知到理解、再到表达的认识规律。', '[["A","正确"],["B","错误"]]', '["A"]', '默读侧重整体感知文本，朗读深化情感体验，讨论与归纳则推动理解走向理性概括和口头表达。整个过程由感性到理性、由输入到输出，符合学生认识发展的一般规律。', '["A"]', 1, 0.6, '2026-11-09 17:16:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (13, 1, 13, 13, 'judge', 0.6, '校运动会上，一名学生在已被检查过的场地内比赛时，因突发阵雨导致场地湿滑而摔伤。学校赛前检查了场地并作了安全提醒，其已尽到教育管理职责，不承担侵权责任。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国民法典》第一千一百九十九条、第一千二百条及《学生伤害事故处理办法》，学校对学生伤害承担过错责任。学校赛前检查场地、进行安全教育，对突发阵雨这一难以预见的情形没有过错，故依法不承担侵权责任。', '["A"]', 1, 0.6, '2026-11-09 17:16:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (14, 1, 14, 14, 'judge', 0.6, '某初中教师利用午休时间为学习困难学生义务辅导，分文未取。该教师的行为违反了严禁有偿补课的规定。', '[["A","正确"],["B","错误"]]', '["B"]', '《严禁中小学校和在职中小学教师有偿补课的规定》所禁止的是组织、参与有偿补课或收受费用的行为。该教师利用休息时间免费辅导学生，不具有有偿性，不属于有偿补课。', '["A"]', 0, 0.0, '2026-11-09 17:16:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (15, 1, 15, 15, 'judge', 0.6, '某县建立义务教育优质均衡发展督导评估机制，把校际差距、随迁子女入学、教师交流等情况纳入对政府履行教育职责的考核。这种做法不利于扩大校际差距，也不是推进义务教育均衡的重要抓手。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《义务教育优质均衡发展县（市、区）评估认定标准》和教育督导条例，对县级政府开展义务教育优质均衡发展督导评估，把资源配置、校际差距、教师交流等纳入考核，正是推动义务教育优质均衡、督促政府履职的重要制度安排。题干否定其作用。', '["A"]', 0, 0.0, '2026-11-09 17:16:01');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (16, 1, 16, 16, 'judge', 0.6, '根据皮亚杰的认知发展阶段理论，能够进行假设—演绎推理、抽象逻辑思维的中学生，其认知发展处于具体运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '皮亚杰认知发展理论中，具体运算阶段（约7—11岁）的儿童虽获得守恒概念，但思维仍需具体事物支持；能够脱离具体情境进行假设—演绎推理和抽象逻辑思维，是形式运算阶段（约11岁以后）的典型特征。题干阶段归属错误。', '["A"]', 0, 0.0, '2026-11-09 17:16:01');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (17, 1, 17, 17, 'judge', 0.6, '班主任只指定几名成绩优秀、能力强的学生长期固定担任班干部，认为这样班级管理更高效，其他学生无需参与。这体现了面向全体学生的教育理念。', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育要求面向全体学生，促进每一名学生主动发展。只让少数优秀学生长期固定担任班干部，剥夺了多数学生参与班级管理、获得锻炼的机会，是面向少数学生的做法，违背了面向全体学生的教育理念。', '["A"]', 0, 0.0, '2026-11-09 17:16:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (18, 1, 18, 18, 'judge', 0.6, '学生设计出有创意的物理实验方案，教师担心“耽误复习、影响考试成绩”，不予表扬也不推荐其参加科技创新比赛。该做法有利于培养学生的创新精神和实践能力。', '[["A","正确"],["B","错误"]]', '["B"]', '培养创新精神和实践能力是素质教育的重点。教师对学生的创新设计持消极态度、不予鼓励和支持，会挫伤学生探究与创造的积极性，与素质教育要求背道而驰。', '["A"]', 0, 0.0, '2026-11-09 17:16:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (19, 1, 19, 19, 'judge', 0.6, '学生在解几何题时能够举一反三，把刚学的一种证明方法灵活用于多道变式题。这说明其产生了正迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '正迁移是指先前学习对后继学习产生积极的促进作用。学生把习得的证明方法成功运用到同类变式题中，促进了新问题的解决，属于正迁移。', '["A"]', 1, 0.6, '2026-11-09 17:16:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (20, 1, 20, 20, 'judge', 0.6, '某市教育局明确要求学校不得把考试成绩排名作为评价学生的唯一依据。这一要求体现了多元化评价的理念。', '[["A","正确"],["B","错误"]]', '["A"]', '《深化新时代教育评价改革总体方案》要求创新过程性评价方法、完善综合素质评价体系，改变以分数给学生贴标签的做法。不以成绩排名为唯一依据，正体现了评价内容、方式和主体的多元化。', '["A"]', 1, 0.6, '2026-11-09 17:16:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (21, 1, 21, 21, 'judge', 0.6, '学生在课堂上提出与教材不同的看法，任课教师为维护教材权威和课堂秩序，当即予以否定并提醒其他学生不要效仿。该做法有利于保护学生的好奇心和求知欲。', '[["A","正确"],["B","错误"]]', '["B"]', '好奇心和求知欲是创造性思维的起点。教师对学生的异见简单否定、当众压制，会造成紧张的心理氛围，使学生不敢质疑，损害其探究兴趣和批判精神；正确做法是肯定独立思考并引导辨析求证。', '["A"]', 0, 0.0, '2026-11-09 17:16:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (22, 1, 22, 22, 'judge', 0.6, '小丽学习时总等老师给出标准答案，不习惯主动质疑和探究。从建构主义学习理论看，她需要转变为知识的主动建构者。', '[["A","正确"],["B","错误"]]', '["A"]', '建构主义认为，学习不是知识由教师向学生的单向传递，而是学生在原有经验基础上主动建构意义的过程。被动等待答案难以实现深层理解，小丽应主动探究、合作建构。', '["A"]', 1, 0.6, '2026-11-09 17:16:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (23, 1, 23, 23, 'judge', 0.6, '学生每次作业没达到教师要求，都要被点名批评并罚重做。学生为了不被批评，不得不认真完成作业。从强化理论看，教师的批评在这里起到了正强化的作用，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["B"]', '正强化是行为发生后呈现愉快刺激以提高行为概率。批评是学生力图回避的厌恶刺激，学生为逃避或避免批评而认真完成作业，属于负强化（撤销厌恶刺激的预期）或惩罚情境，并非正强化。', '["A"]', 0, 0.0, '2026-11-09 17:16:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (24, 1, 24, 24, 'judge', 0.6, '某小学把一名受警告处分学生的姓名、班级和处分决定在全校大会上宣读，并张贴于公告栏。学校认为这是正当的警示教育，不构成侵权。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国未成年人保护法》要求保护未成年人的人格尊严和隐私权、个人信息。对违纪学生的处分应在必要范围内告知本人及其监护人，公开宣读、张贴处分决定带有示众羞辱性质，会使学生的违纪信息被不当扩散，侵犯其人格尊严和隐私权。', '["A"]', 0, 0.0, '2026-11-09 17:16:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (25, 1, 25, 25, 'judge', 0.6, '教师节来临，某班家长委员会凑钱为班主任购买了一条名牌项链，班主任认为家长的好意不便推辞，便收下了。该做法符合教师职业行为准则。', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》和《中小学教师违反职业道德行为处理办法》明确要求教师坚守廉洁自律，不得收受学生及家长赠送的可能影响公正执行公务的礼品礼金。项链价值较高，班主任应当婉言谢绝。', '["A"]', 0, 0.0, '2026-11-09 17:16:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (26, 1, 26, 26, 'judge', 0.6, '某初中教师每节课都以系统讲授为主，把知识完整讲透并要求学生认真听讲记笔记，几乎不安排自主学习和合作探究。与问题导向、自主探究的教学相比，这种全程系统讲授更能突出学生的主体地位。', '[["A","正确"],["B","错误"]]', '["B"]', '系统讲授以教师活动为主，学生主要是被动接受；问题导向教学通过自主学习、合作探究让学生主动建构知识，更能突出学生的主体地位。题中全程讲授、缺少学生主动参与，反而是教师主体而非学生主体。', '["A"]', 0, 0.0, '2026-11-09 17:16:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (27, 1, 27, 27, 'judge', 0.6, '考试失利后，小强认为“题太难、运气差”，自己怎么努力也没用，于是愈发消沉。他的这种反应符合习得性无助的表现。', '[["A","正确"],["B","错误"]]', '["A"]', '习得性无助是指个体反复经历失败后，形成无论怎样努力都无法控制结果的信念，进而产生逃避、放弃等反应。小强把失败外归因并断定努力无用、情绪消沉，正是习得性无助的典型表现。', '["A"]', 1, 0.6, '2026-11-09 17:16:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (28, 1, 28, 28, 'judge', 0.6, '学生把连续几次考试失利都归因于“自己天生脑子笨”，并认为再努力也改变不了。这种归因会增强其后续学习的坚持性。', '[["A","正确"],["B","错误"]]', '["B"]', '“天生脑子笨”属于内部、稳定、不可控的能力归因。依据韦纳归因理论，把失败稳定地归于能力不足，会降低自我效能感和成功预期，导致放弃努力，而非增强坚持性。教师应引导其归因于努力、方法等可控因素。', '["A"]', 0, 0.0, '2026-11-09 17:16:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (29, 1, 29, 29, 'judge', 0.6, '化学实验中学生如实记录了一个与预期不符的现象，教师以“不在考试范围内”为由要求其删除记录。该做法有利于培养学生的科学精神。', '[["A","正确"],["B","错误"]]', '["B"]', '实事求是、尊重证据是科学精神的核心。教师要求学生删除真实的意外记录，违背了严谨求实的治学态度，也错失了引导学生分析异常现象的教育契机。', '["A"]', 0, 0.0, '2026-11-09 17:16:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (30, 1, 30, 30, 'judge', 0.6, '2024年8月26日，中共中央、国务院印发《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。该文件将教育家精神凝练为“心有大我、至诚报国”等十个方面，其中“勤学笃行、求是创新的躬耕态度”要求教师严谨笃学、求真创造。', '[["A","正确"],["B","错误"]]', '["A"]', '该文件确由中共中央、国务院于2024年8月26日印发，全称为《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。教育家精神包括心有大我至诚报国、言为士则行为世范、启智润心因材施教、勤学笃行求是创新、乐教爱生甘于奉献、胸怀天下以文化人等十个方面，题干时间、文件名和对躬耕态度的表述均正确。', '["A"]', 1, 0.6, '2026-11-09 17:16:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (31, 1, 31, 31, 'single', 1.0, '三年级数学老师教学面积时，先让学生用手掌量课桌面，再用方格纸量，最后引出面积公式。这一教学过程体现了（　）', '[["A","从理论到实践的顺序原则"],["B","从一般到个别的演绎过程"],["C","从具体到抽象的认识规律"],["D","从抽象到具体的认识规律"]]', '["C"]', '手掌测量是具体操作，方格纸是半抽象的表象工具，面积公式是抽象概括。教学沿着动作感知—表象—概念的路径推进，体现了从具体到抽象的认识规律。A项“顺序原则”强调由浅入深、由易到难的组织顺序，与题意不完全吻合；B项方向相反（从一般到个别属于演绎，而题干是从个别到一般）；D项方向也相反。', '["A"]', 0, 0.0, '2026-11-09 17:16:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (32, 1, 32, 32, 'single', 1.0, '小明学习英语语法时，常把英语和汉语的句式放在一起比较，找出二者的异同。他运用的学习策略主要是（　）', '[["A","复述策略"],["B","精细加工策略中的比较法"],["C","组织策略中的归类法"],["D","元认知策略中的监控策略"]]', '["B"]', '比较法是精细加工策略的重要方法，通过对易混知识逐项对照异同，加深理解和辨别。将中英语法进行对比正是比较法的运用。复述侧重重复巩固，组织侧重归类建网，元认知侧重对学习过程的计划与监控，均不贴切。', '["A"]', 0, 0.0, '2026-11-09 17:16:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (33, 1, 33, 33, 'single', 1.0, '物理兴趣小组探究单摆周期时，几名中学生先提出“周期可能与摆长、摆锤质量、释放角度都有关”的猜想，再固定其他条件、每次只改变一个变量，分别设计实验加以检验。依据皮亚杰的认知发展阶段理论，这种系统的假设—演绎推理表明他们处于（　）', '[["A","感知运动阶段"],["B","具体运算阶段"],["C","前运算阶段"],["D","形式运算阶段"]]', '["D"]', '皮亚杰通过钟摆实验等研究发现，形式运算阶段（约11岁以后）的个体能够针对问题提出多种假设，并运用控制变量、假设—演绎的方法系统验证。前三个阶段（感知运动、前运算、具体运算）的儿童尚不能脱离具体情境进行严密的假设检验。', '["A"]', 0, 0.0, '2026-11-09 17:16:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (34, 1, 34, 34, 'single', 1.0, '物理教师在讲浮力前先问：“为什么铁块沉入水中，而钢铁造的轮船却能浮在水面？”以激发学生的求知欲。该导入方式属于（　）', '[["A","直接导入"],["B","故事导入"],["C","复习导入"],["D","问题导入"]]', '["D"]', '教师围绕教学内容设置悬念性问题，使学生产生认知冲突和探究愿望，属于问题导入（设疑导入）。复习导入依托旧知，故事导入借助故事情境，直接导入则开门见山点明课题，均与题干不同。', '["A"]', 0, 0.0, '2026-11-09 17:16:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (35, 1, 35, 35, 'single', 1.0, '某生因考试取得进步，被老师在班上当众表扬，此后他学习更加努力。按班杜拉的强化分类，该生受到的强化属于（　）', '[["A","自我强化"],["B","替代强化"],["C","负强化"],["D","直接强化"]]', '["D"]', '直接强化是指学习者本人的行为因直接得到外部强化而增强。该生自己的进步行为直接受到教师表扬，属于直接强化。替代强化是观察他人受奖惩而受影响，自我强化是依据自己的标准自我奖惩，负强化是撤销厌恶刺激以增加行为。', '["A"]', 0, 0.0, '2026-11-09 17:16:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (36, 1, 36, 36, 'single', 1.0, '某市明确要求义务教育阶段学校招生不得采取笔试、面试或任何变相形式的知识性考查。这一要求主要在于维护（　）', '[["A","学校分层教学的自主权"],["B","民办学校优先招生的权利"],["C","适龄儿童免试就近入学的权利"],["D","学校依法自主招生的权利"]]', '["C"]', '《中华人民共和国义务教育法》第十二条规定，适龄儿童、少年免试入学，地方各级人民政府应当保障其在户籍所在地学校就近入学。禁止入学考试和面试，目的在于维护免试就近入学原则和教育公平。B、D项与免试入学要求无关，民办学校招生同样纳入免试入学规范管理。', '["A"]', 0, 0.0, '2026-11-09 17:16:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (37, 1, 37, 37, 'single', 1.0, '学生在化学方程式配平中反复出错。下列做法中，最有利于从根本上解决问题的是（　）', '[["A","先引导学生理解质量守恒定律再学配平"],["B","让学生熟记配平口诀和典型例题"],["C","降低要求，暂不要求掌握配平"],["D","增加抄写和重复练习的数量"]]', '["A"]', '配平的依据是质量守恒定律。学生理解反应前后原子种类、数目不变的本质后，才能在新情境中灵活配平，这属于有意义学习，能从根本上减少错误。机械重复和背诵口诀只形成暂时的技能，回避难点则不能解决问题。', '["A"]', 1, 1.0, '2026-11-09 17:16:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (38, 1, 38, 38, 'single', 1.0, '初二学生小杰总认为同学和老师都在注意自己的发型和穿着，因而在集体活动中格外紧张、不敢表现。这种“感到自己是他人关注中心”的心理属于（　）', '[["A","客体永久性"],["B","假想的观众"],["C","守恒观念"],["D","思维的不可逆性"]]', '["B"]', '青少年自我中心思维的典型表现之一是“假想的观众”，即总觉得自己处在他人关注的焦点，因而过分在意自己的外表和行为。不可逆性、缺乏守恒是前运算阶段儿童的特点，客体永久性形成于感知运动阶段，均与题干不符。', '["A"]', 0, 0.0, '2026-11-09 17:16:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (39, 1, 39, 39, 'single', 1.0, '学生解题时习惯于沿用同一种思路，想不到其他途径，思维明显缺乏变通。教师应着重培养其（　）', '[["A","观察力的敏锐性"],["B","思维的流畅性"],["C","注意力的稳定性"],["D","思维的变通性（灵活性）"]]', '["D"]', '发散思维具有流畅性、变通性和独创性三个特征。只能用一种方法、不能多角度转换思路，反映变通性不足，应通过一题多解、条件变式等训练加以培养。流畅性强调单位时间内观念的数量，注意、观察品质与题干问题不对应。', '["A"]', 0, 0.0, '2026-11-09 17:16:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (40, 1, 40, 40, 'single', 1.0, '学校要求教师每学期至少精读一本教育专著并撰写读书笔记。这一要求直接体现的师德规范是（　）', '[["A","终身学习"],["B","为人师表"],["C","爱岗敬业"],["D","关爱学生"]]', '["A"]', '《中小学教师职业道德规范》中的“终身学习”要求教师崇尚科学精神、树立终身学习理念、拓宽知识视野、更新知识结构。持续研读专业著作、撰写笔记是教师专业自我更新的典型表现。', '["A"]', 1, 1.0, '2026-11-09 17:16:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (41, 1, 41, 41, 'single', 1.0, '数学课上，老师讲“果实”时既举苹果、花生等可食用的例子，也举棉籽、橡子等不可直接食用的例子，并对比“果实与根、茎”。这些变化正例与反例的运用主要是为了促进学生（　）', '[["A","产生学习迁移"],["B","对概念的变式掌握"],["C","形成操作技能"],["D","机械识记定义"]]', '["B"]', '变式是指变换概念的非本质特征、保持本质特征不变的各类正例，配合反例比较，可帮助学生排除无关特征、准确概括概念的本质属性。机械识记不强调例证比较；操作技能、学习迁移与题干例证设计的直接目的不符。', '["A"]', 0, 0.0, '2026-11-09 17:16:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (42, 1, 42, 42, 'single', 1.0, '学生在学习新概念时，总是主动寻找它与已有知识之间的内在联系。按奥苏贝尔的理论，这种学习属于（　）', '[["A","有意义学习"],["B","机械学习"],["C","发现学习"],["D","信号学习"]]', '["A"]', '有意义学习的实质是符号所代表的新知识与学习者认知结构中已有的适当观念建立非人为的、实质性的联系。学生主动把新旧知识联系起来，正是有意义学习的表现。机械学习缺乏这种联系，发现学习强调知识获得的方式，信号学习属于较低级的学习层次。', '["A"]', 1, 1.0, '2026-11-09 17:16:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (43, 1, 43, 43, 'single', 1.0, '学生小雯学习十分刻苦，但总把考试成绩归结为题目难易、临场运气等自己无法左右的因素。依据韦纳的成败归因理论，这些因素主要属于（　）', '[["A","外部、不可控的因素"],["B","内部、可控的因素"],["C","内部、稳定的因素"],["D","内部、不稳定的因素"]]', '["A"]', '韦纳把归因分为内外源、稳定性、可控性三个维度。任务难度属外部、稳定、不可控，运气属外部、不稳定、不可控，二者共同点是外部且不可控。努力才是内部、不稳定、可控因素，能力是内部、稳定、不可控因素。', '["A"]', 1, 1.0, '2026-11-09 17:16:13');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (44, 1, 44, 44, 'single', 1.0, '课间，两名七年级学生聊起为什么而学。泽宇说：“我学几何完全是因为图形证明太有意思了，越想越入迷，搞不懂就睡不着。”他既没想着拿名次，也不为换取表扬。按照奥苏贝尔对学校情境中成就动机成分的划分，泽宇身上占主导的是（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","生理需要驱动"],["D","自我提高内驱力"]]', '["B"]', '认知内驱力是一种指向学习任务本身、以求知和解决问题为满足的内部动机，在有意义学习中是最重要、最稳定的动机。泽宇因几何本身的趣味而主动钻研、不计名次表扬，正属认知内驱力。自我提高内驱力指向由成就带来的地位与自尊，附属内驱力指向获得长者和同伴赞许。', '["A"]', 0, 0.0, '2026-11-09 17:16:13');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (45, 1, 45, 45, 'single', 1.0, '教师先呈现一个真实问题，让学生带着问题研读教材、查找资料，再在讨论中形成认识。这种教学的主要理论基础是（　）', '[["A","认知—接受学习理论"],["B","建构主义学习理论"],["C","行为主义学习理论"],["D","人本主义学习理论"]]', '["B"]', '建构主义强调学习的情境性和主动建构性，主张通过真实问题情境中的探究、协作与会话，由学生自主建构知识意义。基于问题、借助资料和讨论的教学与此高度一致。', '["A"]', 0, 0.0, '2026-11-09 17:16:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (46, 1, 46, 46, 'single', 1.0, '某小学将消防安全、应急疏散演练纳入学校安全管理制度，规定每学期至少组织一次。学校开展安全教育和应急演练的直接部门规章依据是（　）', '[["A","《中华人民共和国民办教育促进法》"],["B","《中华人民共和国高等教育法》"],["C","《中小学幼儿园安全管理办法》"],["D","《中华人民共和国学位条例》"]]', '["C"]', '《中小学幼儿园安全管理办法》（教育部等部门发布）明确规定，学校应当对学生开展消防安全、交通安全等安全教育，制定应急预案并定期组织应急演练，是中小学开展疏散演练最直接的规范依据。A、B、D项均不针对中小学日常安全管理与演练。', '["A"]', 0, 0.0, '2026-11-09 17:16:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (47, 1, 47, 47, 'single', 1.0, '每逢数学考试前，某生就出现头痛、肚子痛、心慌出汗等症状，进入考场后注意力难以集中，考试结束症状随即缓解。该生最可能的问题是（　）', '[["A","躯体器质性疾病"],["B","一般性厌学情绪"],["C","考试焦虑"],["D","注意缺陷多动障碍"]]', '["C"]', '考试焦虑是在一定应试情境下，受个体认知评价、人格倾向等影响而产生的以担忧为特征、伴有生理唤醒的心理状态，躯体化症状随考试情境出现和消退是其典型表现。器质性疾病不会随考试结束而缓解，注意缺陷障碍具有跨情境的持续性。', '["A"]', 0, 0.0, '2026-11-09 17:16:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (48, 1, 48, 48, 'single', 1.0, '学生苦练硬笔书法一段时间后，最初进步明显，但随后连续几周成绩似乎停滞不前，再练也难有提高，甚至出现烦躁情绪。这种练习中期出现的成绩暂时停顿现象，在心理学上称为（　）', '[["A","功能固着现象"],["B","高原现象"],["C","迁移现象"],["D","遗忘现象"]]', '["B"]', '在操作技能形成过程中，练习中期常出现成绩提升暂时停顿、甚至略有下降的现象，称为“高原现象”，其成因包括旧动作结构需要改造、练习方法不当、兴趣和动机下降等。迁移是学习之间的相互影响，遗忘是记忆内容的消退，功能固着属于问题解决中的思维障碍。', '["A"]', 0, 0.0, '2026-11-09 17:16:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (49, 1, 49, 49, 'single', 1.0, '期末复习时，小周把英语单词分散在两周内每天记忆20分钟，而不是考前一天连续背4小时。这种安排主要利用了（　）', '[["A","集中复习优于分散复习的规律"],["B","倒摄抑制的作用"],["C","艾宾浩斯遗忘先快后慢的规律"],["D","高原现象的规律"]]', '["C"]', '艾宾浩斯遗忘曲线表明遗忘进程先快后慢、先多后少，因此应及时复习、合理分散复习时间，在大规模遗忘发生前加以巩固。一般情况下分散复习效果优于集中复习；倒摄抑制指后学材料对先学材料的干扰；高原现象是技能练习中期出现的暂时停顿。', '["A"]', 0, 0.0, '2026-11-09 17:16:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (50, 1, 50, 50, 'single', 1.0, '某中学开设生涯规划课程，引导学生认识自己的兴趣、能力与价值观，了解职业世界并规划发展方向。该课程在德育内容上主要属于（　）', '[["A","人生观与生涯发展指导"],["B","美育中的审美教育"],["C","劳动技术教育中的技能训练"],["D","智育中的思维训练"]]', '["A"]', '德育包括理想信念、社会主义核心价值观、生涯规划等内容。生涯规划教育帮助学生认识自我、明确人生目标，属于德育中的人生观、价值观教育和人生（生涯）发展指导。', '["A"]', 1, 1.0, '2026-11-09 17:16:16');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (51, 1, 51, 51, 'single', 1.0, '校篮球赛中，一名学生在正常对抗中落地受伤。赛前学校进行了专项安全教育、检查了场地并配备了校医。依法学校（　）', '[["A","无论有无过错均应补偿"],["B","已尽到教育管理职责，不承担侵权责任"],["C","应与对方学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["B"]', '依据《民法典》第一千二百条，限制民事行为能力人在学校学习、生活期间受到人身损害，学校未尽到教育、管理职责的才承担责任。学校已开展安全教育、检查场地、配备医护人员，对正常竞技中的意外受伤没有过错，故不承担侵权责任。', '["A"]', 0, 0.0, '2026-11-09 17:16:16');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (52, 1, 52, 52, 'single', 1.0, '某教师因几名学生未完成作业，罚他们到操场上跑十圈，致使一名学生体力不支晕倒。该教师的行为属于（　）', '[["A","体罚，侵犯学生身体权和健康权"],["B","合法的教育惩戒"],["C","一般性的课堂管理措施"],["D","正常的体育锻炼"]]', '["A"]', '《中小学教育惩戒规则（试行）》允许的惩戒不包括超越学生身心承受能力的体力惩罚。罚跑十圈直接造成身体痛苦和伤害，属于体罚而非法惩戒，侵犯了学生的身体权、健康权。', '["A"]', 1, 1.0, '2026-11-09 17:16:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (53, 1, 53, 53, 'single', 1.0, '市场监管和教育行政部门联合检查时，发现某校食堂操作间卫生不达标、留样不规范，遂责令其限期改正。该执法行为（　）', '[["A","只能在发生食物中毒后实施"],["B","于法有据，是履行食品安全监管职责"],["C","应完全交由学校家委会处理"],["D","属于越权干预学校自主经营"]]', '["B"]', '依据《中华人民共和国食品安全法》和《学校食品安全与营养健康管理规定》，学校食堂实行预防为主、风险管理原则，教育、市场监管部门依法负有日常监督检查职责。事前责令限期整改正是依法履职。', '["A"]', 0, 0.0, '2026-11-09 17:16:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (54, 1, 54, 54, 'single', 1.0, '自习课上，教师发现一名学生正用手机玩游戏。最恰当的处理方式是（　）', '[["A","暂时代为保管，课后归还并进行教育引导"],["B","当着全班的面摔毁手机以示警戒"],["C","立即将学生逐出教室反思"],["D","当场将手机没收并永久不予归还"]]', '["A"]', '依据中小学学生手机管理相关规定，学生违规带入或使用手机的，学校可统一保管并及时告知家长。教师暂时代管、课后归还并辅以教育，既维护课堂秩序，又尊重学生财产权和人格尊严。没收不还、逐出教室、损毁财物均缺乏法律依据并可能侵权。', '["A"]', 1, 1.0, '2026-11-09 17:16:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (55, 1, 55, 55, 'single', 1.0, '中共中央、国务院《深化新时代教育评价改革总体方案》要求改革学生评价。下列做法中，不符合该方案方向的是（　）', '[["A","坚决改变以分数给学生贴标签的做法"],["B","健全学生综合素质评价体系"],["C","完善德智体美劳过程性评价"],["D","把升学率作为评价学校办学质量的唯一指标"]]', '["D"]', '《深化新时代教育评价改革总体方案》（2020年印发）提出坚决纠正片面追求升学率倾向，不得把升学率作为评价学校、教师和学生的唯一依据，强调过程性评价和综合素质评价。D项正是方案要破除的做法。', '["A"]', 0, 0.0, '2026-11-09 17:16:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (56, 1, 56, 56, 'single', 1.0, '创造思维训练课上，教师给出钳子、绳子等材料，要求学生想办法同时够到从天花板垂下的两根相距较远、无法一手同时抓住的绳子。多数学生只把钳子看作夹持工具，想不到可把它系在绳端当作摆锤，晃动绳子后趁机抓住。这一现象主要说明问题解决受到（　）', '[["A","功能固着的影响"],["B","学习动机的影响"],["C","原型启发的影响"],["D","正迁移的影响"]]', '["A"]', '功能固着是指个体只看到事物惯常的功能而看不到它其他可能用途的现象。学生只认定钳子是夹持工具，想不到它可作摆锤，这是梅尔双绳实验所揭示的功能固着。原型启发是从其他事物中找到解决问题的途径，正迁移和学习动机与该现象无关。', '["A"]', 1, 1.0, '2026-11-09 17:16:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (57, 1, 57, 57, 'single', 1.0, '班上的小亮打碎了教室里1只杯子后主动认错；小杰为偷吃糖果打碎了10只杯子却谎称不是自己干的。问“哪个孩子更不好、应受更重惩罚”时，小学三年级学生大多认为小杰更坏、因为打碎了10只杯子。依据皮亚杰道德发展阶段理论，这些学生的判断主要处于（　）', '[["A","他律道德阶段"],["B","自律道德阶段"],["C","公正道德阶段"],["D","前道德阶段"]]', '["A"]', '皮亚杰通过对偶故事研究发现，他律道德阶段（约5—8岁）的儿童根据行为的客观后果数量判断责任，而不考虑行为动机；自律阶段儿童才会结合主观动机判断。只看打碎杯子数量、忽视说谎与偷拿动机，属于他律道德阶段的特点。', '["A"]', 1, 1.0, '2026-11-09 17:16:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (58, 1, 58, 58, 'single', 1.0, '某班在校内劳动实践基地上劳动课，教师事先讲解了工具的安全使用方法并示范操作，一名学生仍未按要求握持工具，不慎被划伤。事后学校及时送医并通知家长。依法学校（　）', '[["A","应承担全部赔偿责任"],["B","已尽到教育、管理和保护职责，不承担侵权责任"],["C","无论有无过错都必须给予赔偿"],["D","应与任课教师平均分担损失"]]', '["B"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任。教师已进行安全教育和操作示范、学校事后及时救助，对学生违反操作规程造成的自伤没有过错，故不承担侵权责任。', '["A"]', 0, 0.0, '2026-11-09 17:16:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (59, 1, 59, 59, 'single', 1.0, '课堂上，数学老师要求学生一边听讲一边在草稿本上记录关键步骤，多数学生能较好地同时完成两项任务。这主要体现了注意的（　）', '[["A","注意的稳定性"],["B","注意的转移"],["C","注意的分配"],["D","注意的范围"]]', '["C"]', '注意的分配是指个体在同一时间内把注意指向两种或两种以上的对象或活动。边听讲边记录要求学生在听和写之间合理分配注意。注意范围强调同一瞬间把握对象的数量，稳定性强调持续时间，转移强调根据任务主动把注意从一个对象转向另一个对象。', '["A"]', 0, 0.0, '2026-11-09 17:16:20');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (60, 1, 60, 60, 'single', 1.0, '一位中学教师持续跟踪本学科研究进展，把经过筛选的最新科研成果转化为教学案例，帮助学生了解学科前沿。这主要体现了（　）', '[["A","教师把科研任务转嫁给学生"],["B","以研究取代常规课堂教学"],["C","教学完全脱离教材体系"],["D","教学内容与学术研究相结合"]]', '["D"]', '教师把学科前沿成果筛选、转化为适切的教学素材，体现了科研与教学相长，有利于拓宽学生视野、培养科学素养。A项把科研成果转化曲解为“转嫁任务”，与教师主动筛选转化的行为不符；B项将科研促教绝对化为“取代课堂教学”，C项则完全否定教材体系，均与题干事实相悖。', '["A"]', 0, 0.0, '2026-11-09 17:16:20');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (61, 1, 61, 61, 'single', 1.0, '复习化学时，某生把零散的物质按“单质—化合物—混合物”的类别整理成表格，再把各类物质的性质、制法和用途归并到一起记忆。该学习策略主要属于（　）', '[["A","元认知策略中的计划策略"],["B","复述策略"],["C","精细加工策略中的记忆术"],["D","组织策略中的归类法"]]', '["D"]', '组织策略是对学习材料进行加工，按照其内在联系加以归类、整理，形成清晰认知结构的策略。该生按物质分类建表、归并性质与用途，正是归类法的典型运用。复述侧重重复巩固，记忆术侧重人为联想以增强保持，计划策略侧重对学习活动的预先安排。', '["A"]', 0, 0.0, '2026-11-09 17:16:21');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (62, 1, 62, 62, 'single', 1.0, '部分学生习惯于机械背诵，对知识不求甚解，遇到变式题就出错。教师应着重引导其（　）', '[["A","加大机械重复的遍数"],["B","放弃记忆，只做难题"],["C","在理解的基础上进行有意义学习"],["D","延长每次记忆的时间"]]', '["C"]', '机械学习获得的知识难以迁移，变式题出错的根源是没有理解知识的实质和内在联系。教师应帮助学生把新知识纳入已有认知结构，开展有意义学习，并辅以变式练习。', '["A"]', 0, 0.0, '2026-11-09 17:16:21');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (63, 1, 63, 63, 'single', 1.0, '升入初中后，小芸在家长帮助下制定学习计划时，会主动预估某项任务大约需要多长时间，并据此安排先后顺序。这种对认知活动的预先规划属于（　）', '[["A","资源管理策略中的时间管理"],["B","元认知计划策略"],["C","复述策略"],["D","精加工策略"]]', '["B"]', '元认知策略包括计划、监控和调节策略。在认知活动开始前设置目标、预估任务难度与时间、安排学习步骤，属于元认知计划策略。复述策略侧重重复保持信息，精加工策略侧重为信息增加意义，时间管理策略侧重对学习时间资源的统筹，均不直接指向对认知过程的预先规划。', '["A"]', 0, 0.0, '2026-11-09 17:16:22');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (64, 1, 64, 64, 'single', 1.0, '某校在防治校园欺凌中建立早期预警机制。下列做法中，不属于早期预警措施的是（　）', '[["A","定期开展心理健康普查并建立重点关注台账"],["B","仅在发生严重伤害事件后再介入处理"],["C","畅通学生、家长欺凌线索报告渠道"],["D","通过日常观察和同伴关系调查识别风险信号"]]', '["B"]', '早期预警强调关口前移，通过心理筛查、风险排查、线索报告和主题教育等主动发现隐患。事后处理是末端应对而非预防预警。', '["A"]', 0, 0.0, '2026-11-09 17:16:22');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (65, 1, 65, 65, 'single', 1.0, '一位教师在教学后记中写道：“今天进度偏快，部分学生来不及思考，下次应放慢节奏，多留讨论时间。”这主要反映了教师的（　）', '[["A","关注学情并自觉改进教学的反思意识"],["B","只关注教学进度完成情况"],["C","对学生差异的无条件迁就"],["D","以个人经验否定教学计划"]]', '["A"]', '教师依据课堂上观察到的学习状态审视教学，并提出针对性的调整方案，属于教学反思，体现了以学定教和持续改进的专业意识。', '["A"]', 1, 1.0, '2026-11-09 17:16:23');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (66, 1, 66, 66, 'single', 1.0, '一名学生因家境困难而自卑，很少与同学交往。班主任一方面关心鼓励他、协助其申请助学金，另一方面引导同学在小组活动中主动接纳他。该做法体现了（　）', '[["A","以经济资助代替思想教育"],["B","关爱学生与集体教育相结合"],["C","只依靠班集体进行教育"],["D","把学生的家庭情况公开通报"]]', '["B"]', '教师个人的关爱与帮扶解决了学生的实际困难和心理压力，组织同伴互助则发挥了集体的教育力量，两者结合帮助学生走出自卑，符合关爱学生与集体教育相结合的要求。', '["A"]', 0, 0.0, '2026-11-09 17:16:23');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (67, 1, 67, 67, 'single', 1.0, '一名学生因沉迷手机游戏导致成绩明显下降、上课精神不振。班主任较恰当的做法是（　）', '[["A","不经学生同意直接查阅其手机全部内容"],["B","把问题完全推给家长，学校不再过问"],["C","了解原因，引导其认识危害并共同制定合理用机计划"],["D","当众严厉训斥并永久禁止其接触手机"]]', '["C"]', '手机沉迷的成因复杂，简单禁止或放任都难以奏效。教师应在尊重学生的基础上了解需求、讲清危害，与学生、家长协商制定可执行的用机规则，并以丰富的活动转移注意。', '["A"]', 0, 0.0, '2026-11-09 17:16:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (68, 1, 68, 68, 'single', 1.0, '作文基础薄弱的学生，在老师系统指导和同伴互助下，能独立完成此前无法完成的800字议论文；脱离帮助后，他仍只能写约500字。维果斯基把“独立解决问题的实际水平”与“成人指导下可达到的水平”之间的差距称为（　）', '[["A","关键期"],["B","学习准备状态"],["C","最近发展区"],["D","认知风格差异"]]', '["C"]', '维果斯基提出的最近发展区，是指儿童独立解决问题所确定的现有发展水平，与在成人指导或与有能力同伴合作下解决问题所达到的潜在发展水平之间的差距，教学应着眼于“跳一跳、摘桃子”。关键期强调特定能力发展的最佳时机，认知风格、学习准备均不描述这一差距。', '["A"]', 0, 0.0, '2026-11-09 17:16:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (69, 1, 69, 69, 'single', 1.0, '课堂上一名学生对教材结论提出有依据的质疑。教师最恰当的回应是（　）', '[["A","暂时回避，课后单独批评"],["B","以维护教材权威为由不予讨论"],["C","提醒学生只需记住考试结论"],["D","肯定质疑精神，组织学生辨析求证"]]', '["D"]', '面对有价值的质疑，教师应发扬教学民主，把质疑转化为教学资源，引导学生寻找证据、辨析论证，既解决问题又培养批判精神。', '["A"]', 0, 0.0, '2026-11-09 17:16:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (70, 1, 70, 70, 'single', 1.0, '某市推行“阳光招生”，要求招生计划、程序、结果全程公开，接受社会监督。这一做法主要有利于（　）', '[["A","维护教育公平，保障群众的知情权和监督权"],["B","扩大学校的招生自由裁量权"],["C","弱化教育行政部门的监管责任"],["D","以社会评价替代教育评价"]]', '["A"]', '招生信息公开把入学机会置于社会监督之下，有助于遏制“掐尖招生”“条子生”等违规行为，保障入学机会公平和群众的知情权、监督权。', '["A"]', 1, 1.0, '2026-11-09 17:16:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (71, 1, 71, 71, 'single', 1.0, '学生把ambulance（救护车）谐音联想为“俺不能死”来记忆单词。这种记忆方法属于（　）', '[["A","复述策略"],["B","精细加工策略中的谐音联想法"],["C","组织策略中的纲要法"],["D","元认知策略中的调节策略"]]', '["B"]', '谐音联想法是借助读音相似把抽象、无意义材料转化为有意义表象的精细加工策略。复述、组织、元认知策略的功能与题干方法不符。', '["A"]', 0, 0.0, '2026-11-09 17:16:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (72, 1, 72, 72, 'single', 1.0, '学生作文普遍空洞，教师分析后发现主要原因是生活观察和体验不足。下列做法中最有针对性的是（　）', '[["A","以抄写优美句段代替写作训练"],["B","要求学生大量背诵优秀作文模板"],["C","降低字数和立意要求"],["D","组织观察、实践活动，丰富直接经验和写作素材"]]', '["D"]', '写作是对生活经验加工表达的过程。“无米下锅”靠套模板、抄句段无法根治，组织观察与实践活动可充实感性经验，解决素材贫乏的根源问题。', '["A"]', 0, 0.0, '2026-11-09 17:16:26');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (73, 1, 73, 73, 'single', 1.0, '一位教师坚持每周撰写教学反思，系统记录成功经验、问题教训和改进设想，三年后教学水平显著提升。这一专业发展途径主要是（　）', '[["A","脱产学历进修"],["B","单纯依靠专家讲座"],["C","自我反思与行动研究"],["D","同事之间的随机闲谈"]]', '["C"]', '波斯纳提出“教师成长 = 经验 + 反思”。持续、系统地反思教学并据以改进，是教师立足岗位的自我教育和行动研究，是专业发展最直接的途径之一。', '["A"]', 0, 0.0, '2026-11-09 17:16:26');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (74, 1, 74, 74, 'single', 1.0, '春游中，一名学生在自由活动时违反事先反复强调的安全要求，与同学追逐打闹致自己摔伤。学校事前勘察了路线、进行了安全教育并安排足够教师跟班。依法学校（　）', '[["A","已尽到教育管理职责，不承担侵权责任"],["B","只要发生在校外活动中就须担责"],["C","应与受伤学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["A"]', '依据《学生伤害事故处理办法》和《民法典》相关规定，学校责任以过错为前提。学校履行了安全教育、路线勘查和人员配备义务，损害由学生违反纪律的自险行为造成，学校没有过错，故不承担侵权责任。B项将校外活动一律归责，C项无法律依据要求平均分摊，D项全额赔偿更无事实与法律基础。', '["A"]', 1, 1.0, '2026-11-09 17:16:27');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (75, 1, 75, 75, 'single', 1.0, '学生计算能力正常，却常常不会做应用题，主要问题在于读不懂题意、抓不住数量关系。教师应优先培养其（　）', '[["A","阅读理解与关键信息提取能力"],["B","机械背诵公式的能力"],["C","几何作图能力"],["D","计算的速度和准确率"]]', '["A"]', '应用题解题的前提是理解文字情境、识别已知条件与问题、抽象出数量关系。困难出在题意理解环节，就应通过说题、画示意图、圈画关键词等方式提高阅读理解和信息提取能力。', '["A"]', 1, 1.0, '2026-11-09 17:16:27');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (76, 1, 76, 76, 'single', 1.0, '教师注意发现每名学生身上的闪光点，及时给予具体的肯定和鼓励，学生的自信心和完成任务的坚持性明显增强。这种做法主要是通过提升（　）发挥作用的。', '[["A","流体智力水平"],["B","学习兴趣的广度"],["C","认知风格的灵活性"],["D","自我效能感"]]', '["D"]', '自我效能感是个体对自己能否成功完成某一任务的信念，成败经验和他人的积极评价是其重要来源。具体、真诚的肯定能帮助学生积累成功体验，提高自我效能感。', '["A"]', 0, 0.0, '2026-11-09 17:16:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (77, 1, 77, 77, 'single', 1.0, '某校把师德师风考核结果作为教师年度考核、职称评聘和评优奖励的首要标准，实行师德失范“一票否决”。这一做法体现了（　）', '[["A","以科研论文数量主导考核"],["B","以学历层次决定教师待遇"],["C","把师德师风作为评价教师第一标准"],["D","以教学成绩为核心的评价导向"]]', '["C"]', '《深化新时代教育评价改革总体方案》和《关于加强和改进新时代师德师风建设的意见》均强调把师德师风作为教师评价的第一标准，落实师德失范“一票否决”。', '["A"]', 0, 0.0, '2026-11-09 17:16:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (78, 1, 78, 78, 'single', 1.0, '学英语时，小梅先掌握的汉语拼音发音，常使她把英语字母读成拼音；经过一段时间练习后，新学的英语拼读又偶尔干扰她认读拼音。前一种情形主要属于（　）', '[["A","消退抑制"],["B","前摄抑制"],["C","超限抑制"],["D","倒摄抑制"]]', '["B"]', '先学习的材料对识记和回忆后学习材料的干扰称前摄抑制；后学习的材料对保持先学习材料的干扰称倒摄抑制。汉语拼音先学并干扰英语认读，属于前摄抑制。题干后半句英语反过来干扰拼音才是倒摄抑制，应注意二者的时间顺序。', '["A"]', 0, 0.0, '2026-11-09 17:16:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (79, 1, 79, 79, 'single', 1.0, '一名家庭经济困难学生产生辍学念头，班主任多次家访劝学，协助其申请助学金和社会资助，最终帮助其安心完成学业。该做法主要体现了教师（　）', '[["A","控辍保学、保障适龄儿童接受义务教育的责任"],["B","管理学校财务的行政责任"],["C","开展教育科学研究的责任"],["D","提高班级升学率的教学责任"]]', '["A"]', '《中华人民共和国义务教育法》要求政府、学校、家庭共同做好控辍保学工作，发现学生辍学应及时劝返并帮助解决实际困难。班主任劝学并协助资助，是落实控辍保学责任的体现。', '["A"]', 1, 1.0, '2026-11-09 17:16:29');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (80, 1, 80, 80, 'single', 1.0, '某市推进教育数字化，支持学校建设智慧课堂，利用大数据开展学情诊断、推送分层学习资源。这一举措的主要价值在于（　）', '[["A","减少学校对教学管理的投入"],["B","用信息技术完全取代教师"],["C","赋能因材施教，提高教学质量"],["D","统一拉平所有学生的学习进度"]]', '["C"]', '《教育强国建设规划纲要（2024—2035年）》强调建设教育数字化体系。智慧课堂和学情数据分析有助于精准把握差异、提供个性化资源，赋能因材施教和质量提升，但技术是辅助手段，不能取代教师。', '["A"]', 0, 0.0, '2026-11-09 17:16:29');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (81, 1, 81, 81, 'multi', 1.6, '某小学深化课程改革，采取了下列措施：开设可供选择的兴趣选修课、推行项目式学习、实行多元过程性评价、鼓励教师合作开发校本课程。这些措施体现的新课程理念有（　）', '[["A","课程结构的选择性"],["B","项目式学习意味着完全取消教师讲授和系统知识学习"],["C","把学生考试成绩作为唯一衡量标准"],["D","评价主体与方式的多元化"],["E","校本课程只能由校外专家开发，教师只负责执行"]]', '["A","D"]', 'A正确：开设可供选择的兴趣选修课体现了课程结构的选择性，照顾学生差异。B错误：项目式学习倡导自主、合作、探究，但并不否定必要的教师讲授和系统知识学习，二者应有机结合。D正确：多元过程性评价体现评价主体和方式多元化。C错误：以分数为唯一标准是新课改要破除的甄别式评价。E错误：教师是课程的建设者和开发者，可以参与校本课程开发。', '["A"]', 0, 0.0, '2026-11-09 17:16:30');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (82, 1, 82, 82, 'multi', 1.6, '学习中，不同问题可以采用不同的学习策略：上课容易走神时需要加强注意的自我监控；记不住零散知识点时需要精加工和及时复习；不会写作文时需要增加观察体验并借鉴范文结构。下列对应正确的有（　）', '[["A","上课走神——运用元认知监控策略，及时调节注意"],["B","记不住知识点——适当运用复述、精加工和组织策略并及时复习"],["C","学习困难只能靠延长学习时间、增加重复遍数解决"],["D","不会写作文——丰富直接经验，运用读写结合的方法"],["E","只要学习策略足够好，就可以忽略学习动机和原有知识基础"]]', '["A","B","D"]', 'A正确：对注意和理解过程的自我觉察、及时调节属于元认知监控策略。B正确：针对零散知识，复述、精细加工、归类组织并依据遗忘规律及时复习是有效方法。D正确：写作困难常源于直接经验不足，应通过观察实践和范文借鉴加以解决。C错误：机械延长时间、简单重复忽视理解和策略运用，效率低下。E错误：策略运用受学习动机、原有知识基础等因素制约，不能脱离这些条件孤立发挥作用。', '["A"]', 0, 0.0, '2026-11-09 17:16:30');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (83, 1, 83, 83, 'multi', 1.6, '某班主任在班级管理中采取了下列做法：实行值日班长轮流制、定期召开班会讨论班级事务、建立班级公约和岗位责任制、对违纪学生只靠罚抄课文处理。其中符合现代班级管理理念的有（　）', '[["A","实行值日班长轮流制，让学生在参与中学会自治"],["B","定期召开班会讨论班级事务，发挥学生的主体作用"],["C","建立班级公约和岗位责任制，实现班级管理的制度化"],["D","对违纪学生一律罚抄课文，以加重学生负担来维持纪律"],["E","班级事务完全由班主任一人决定，学生只需服从执行"]]', '["A","B","C"]', 'A、B、C正确：轮流管理、班会民主议事、公约与岗位责任制体现了学生主体、民主参与和自主管理的现代班级管理理念。D错误：罚抄课文属于变相体罚和机械惩罚，既不符合教育惩戒要求，也不能从根本上引导学生自律。E错误：班主任独断专行会压抑学生的主动性和责任感，不符合班级民主管理方向。', '["A"]', 0, 0.0, '2026-11-09 17:16:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (84, 1, 84, 84, 'multi', 1.6, '某校六年级两名学生在课间追逐打闹，教师多次提醒后，一名学生仍将同学推倒致其骨折。关于学校责任的认定，下列说法正确的有（　）', '[["A","学校是否承担责任，以其是否尽到教育、管理职责为判断标准"],["B","学校已进行必要的安全教育和管理且无过错的，不承担侵权责任"],["C","有过错的学生监护人依法承担相应的侵权责任"],["D","伤害发生在校园内，学校无论有无过错都必须承担全部赔偿责任"],["E","学校应当及时救助受伤害学生，并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任，以是否尽到教育、管理职责为判断标准（A、B正确）；加害学生一方有过错的，由其监护人依法承担相应责任（C正确）；学校还负有及时救助、告知监护人的法定义务（E正确）。D错误：校园内发生伤害并不导致学校当然全责，归责仍以过错为要件。', '["A"]', 0, 0.0, '2026-11-09 17:16:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (85, 1, 85, 85, 'multi', 1.6, '某市对学校课后服务工作提出要求：服务内容要多样化，要尊重学生和家长的自主选择，要为学习有困难的学生提供辅导，不得利用课后服务时间统一讲授新课。这些要求符合（　）', '[["A","满足学生多样化发展需求"],["B","尊重学生和家长的自愿选择"],["C","对学习困难学生进行必要的学业帮扶"],["D","借课后服务之名集体补课、增加学生负担"],["E","把课后服务办成统一的新课教学"]]', '["A","B","C"]', 'A正确：多样化内容有助于发展兴趣特长、促进全面发展。B正确：课后服务坚持学生自愿、家长自愿原则。C正确：对学习有困难的学生进行答疑辅导是课后服务的重要内容。D、E错误：依据“双减”政策，课后服务不得变成集体补课或讲授新课，不得加重学生课业负担。', '["A"]', 0, 0.0, '2026-11-09 17:16:32');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (86, 1, 86, 86, 'multi', 1.6, '一位语文教师经常运用情境教学。下列属于情境教学法基本特征的有（　）', '[["A","以生动具体的形象激发学生的情感体验"],["B","课堂中只允许学生体验，不进行任何理性概括和知识讲授"],["C","教师只作旁观，完全不加以引导和点拨"],["D","创设与教学内容相适应的真实或模拟情境"],["E","情境越离奇、越脱离学生生活，教学效果越好"]]', '["A","D"]', '情境教学（以李吉林情境教育为代表）以“形真、情切、意远、理寓其中”为特点：A正确，借助生动具体的形象唤起情感体验；D正确，强调围绕教学内容创设真实或模拟的情境。B错误：情境教学主张情知交融、在体验基础上引导概括，并不排斥理性认识和必要讲授。C错误：教师要适时引导、点拨、升华，而非放任旁观。E错误：情境应贴近学生已有生活经验和认知水平，脱离生活反而妨碍理解。', '["A"]', 0, 0.0, '2026-11-09 17:16:32');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (87, 1, 87, 87, 'multi', 1.6, '某校组织学生乘大巴参加校外实践活动，途中因其他车辆违章变道发生交通事故，造成学生受伤，学校大巴驾驶员和随车教师并无过错。关于责任承担，下列说法正确的有（　）', '[["A","学生有权依法获得赔偿"],["B","事故责任应由违章车辆一方依法承担"],["C","学校已尽到组织管理和安全保障义务的，不承担侵权责任"],["D","只要发生在校外活动中，学校就应承担全部责任"],["E","学校应及时救助受伤学生并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》侵权责任编和《学生伤害事故处理办法》，学生伤害事故责任以过错为原则。本案由第三方违章造成，应由责任方承担赔偿；学校无过错则不承担侵权责任，但仍负有及时救助、告知和报告义务，A、B、C、E正确。D错误：学校责任不依“校外”这一地点当然成立，而取决于是否尽到教育、管理职责。', '["A"]', 0, 0.0, '2026-11-09 17:16:34');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (88, 1, 88, 88, 'multi', 1.6, '某校校园文化节安排了经典诵读、民族歌舞表演、传统手工艺制作和民族文化展板等活动。这些活动的育人价值在于（　）', '[["A","增进学生对中华优秀传统文化的认同"],["B","促进民族团结教育和文化理解"],["C","在实践体验中提高学生的审美和动手能力"],["D","文化节只是娱乐活动，与育人目标无关"],["E","丰富校园文化生活，营造良好的隐性课程环境"]]', '["A","B","C","E"]', '传统文化展示有助于文化认同与文化自信（A）；民族歌舞、民族文化内容可渗透民族团结教育（B）；表演与手工艺制作能发展审美和实践能力（C）；丰富的校园文化本身构成隐性课程，发挥潜移默化的育人作用（E）。D错误：校园文化活动是学校教育和隐性课程的重要载体，具有明确的育人功能。', '["A"]', 0, 0.0, '2026-11-09 17:16:35');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (89, 1, 89, 89, 'multi', 1.6, '一位教师反思后发现自己“讲得太多、学生参与太少”，于是调整教学：增加课堂提问与讨论、设计小组合作任务、留出学生练习和展示时间。这种调整符合（　）', '[["A","启发性教学原则"],["B","教师主导与学生主体相统一的规律"],["C","以学生活动完全取代教师讲授"],["D","调动学生学习的主动性"],["E","促进学生从学会走向会学"]]', '["A","B","D","E"]', '增加提问讨论、合作探究体现启发性原则（A）和教师主导作用与学生主体作用相统一的教学规律（B）；学生在提问、讨论和展示中由被动接受转为主动参与，有利于调动学习主动性（D）；教师由“教会知识”转向引导学生掌握方法，促进学生从“学会”走向“会学”（E）。C错误：强调学生主体并不否定教师必要的讲授与引导，讲授法在系统传授知识方面仍有不可替代的价值。', '["A"]', 0, 0.0, '2026-11-09 17:16:37');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (90, 1, 90, 90, 'multi', 1.6, '某市要求学校改革学生评价：不以分数作为评价学生的唯一依据、关注学生成长过程、重视学生的自我反思与同伴互评。这体现的评价理念有（　）', '[["A","评价内容的综合化，关注德智体美劳全面发展"],["B","评价方式的过程化与多元化"],["C","评价主体的多元化，强调学生参与"],["D","以甄别和选拔为唯一目的的评价观"],["E","发挥评价促进学生发展的教育功能"]]', '["A","B","C","E"]', '不以分数为唯一依据体现评价内容综合化（A）；关注成长过程、采用多元方式体现过程性、多元化评价（B）；自我反思与同伴互评体现评价主体多元（C）；改革的落脚点是促进发展（E）。D错误：甄别选拔是传统评价的突出功能，发展性评价强调激励、诊断与改进，反对“为了选拔而评价”。', '["A"]', 0, 0.0, '2026-11-09 17:16:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (91, 2, 1, 1, 'judge', 0.6, '某小学数学老师教学乘法时，先让学生用加法算 3 + 3 + 3 + 3 = 12，再引入乘法 3×4 = 12。这种从加法到乘法的学习属于下位学习。', '[["A","正确"],["B","错误"]]', '["A"]', '乘法是几个相同加数连加的简便运算，是加法概念下的派生类属概念。学生在已掌握加法的基础上学习乘法，新概念从属于原有概念，属于奥苏贝尔所说的下位学习（派生类属学习）。', '["A"]', 1, 0.6, '2026-11-09 17:19:36');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (92, 2, 2, 2, 'judge', 0.6, '高一学生小柯在“学医还是学文”之间犹豫：父母希望他学医，他自己热爱文学，两个目标都想得到却只能选择其一。小柯面临的这种心理冲突属于趋避冲突。', '[["A","正确"],["B","错误"]]', '["B"]', '两个都想要的目标只能择其一，属于双趋冲突（接近—接近型冲突）。趋避冲突是指同一个目标同时具有吸引力和排斥力；双避冲突是两个目标都想回避却必须选择其一。题干把双趋冲突误判为趋避冲突。', '["A"]', 0, 0.0, '2026-11-09 17:19:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (93, 2, 3, 3, 'judge', 0.6, '某中学物理老师在学生回答与预设答案不同时，总是追问“你为什么这样想”，要求学生说明理由和依据。这种做法有利于培养学生的批判性思维。', '[["A","正确"],["B","错误"]]', '["A"]', '批判性思维要求学生对观点进行理性审视、有根据地思考和论证。教师持续追问理由和依据，能促使学生不盲从结论、学会用证据支持观点。', '["A"]', 1, 0.6, '2026-11-09 17:19:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (94, 2, 4, 4, 'judge', 0.6, '小学六年级学生小芳学完百分数后，能用百分数表示折扣、利率等生活中的比例关系。这种把课堂知识用于新情境的表现体现了学习迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '学习迁移是指一种学习对另一种学习的影响。学生把课堂上获得的百分数知识运用到折扣、利率等陌生的生活情境中，属于知识在新情境中的正迁移。', '["A"]', 1, 0.6, '2026-11-09 17:19:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (95, 2, 5, 5, 'judge', 0.6, '某市教育局在评估中发现某校向学生统一推销教辅资料并收取费用，遂责令学校立即整改、退还费用。该教育局的处理于法有据。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国义务教育法》第二十五条，学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益；《中小学教师违反职业道德行为处理办法》也明令禁止教师强制或变相强制学生订购教辅。教育行政部门有权责令改正、退还费用。', '["A"]', 1, 0.6, '2026-11-09 17:19:39');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (96, 2, 6, 6, 'judge', 0.6, '某小学教师为提高成绩，每天布置大量重复性抄写作业，多数学生要写到深夜。该做法违反了“双减”政策关于作业总量和时长调控的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》要求小学三至六年级书面作业平均完成时间不超过60分钟，并鼓励布置分层、弹性和个性化作业，避免机械重复训练。大量重复性抄写加重了学生负担。', '["A"]', 1, 0.6, '2026-11-09 17:19:39');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (97, 2, 7, 7, 'judge', 0.6, '英语考试中，小明做阅读理解时先快速浏览全文把握结构，再带着题目回读相关段落。小明运用的主要是元认知策略。', '[["A","正确"],["B","错误"]]', '["A"]', '先浏览全文以确定阅读目标和重点，属于元认知策略中的计划策略；带着问题有针对性地回读、随时检验自己是否读懂，属于监控策略。二者均属元认知策略。', '["A"]', 1, 0.6, '2026-11-09 17:19:40');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (98, 2, 8, 8, 'judge', 0.6, '心理辅导老师把辅导中获悉的学生家庭变故等隐私，当作谈资告诉了其他任课教师。该做法侵犯了学生的隐私权。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国未成年人保护法》第四条规定处理未成年人事项应当保护未成年人隐私权和个人信息。心理辅导记录涉及未成年人个人隐私，未经本人及其监护人同意不得向无关人员披露。', '["A"]', 1, 0.6, '2026-11-09 17:19:40');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (99, 2, 9, 9, 'judge', 0.6, '某初中教师试行翻转课堂：基础知识由学生课前借助微课自学，课堂主要用于答疑、探究和协作练习。这种模式有利于培养学生的自主学习能力。', '[["A","正确"],["B","错误"]]', '["A"]', '翻转课堂把知识传授前移到课前由学生自主完成，课堂则转向深度学习与合作探究，客观上要求并锻炼学生自我规划、自我监控的学习能力。', '["A"]', 1, 0.6, '2026-11-09 17:19:40');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (100, 2, 10, 10, 'judge', 0.6, '某小学教师以成绩差为由，长期安排一名学生单独坐在教室最后一排。该做法没有侵犯学生的合法权益。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《中华人民共和国义务教育法》和《未成年人保护法》，学生在入学、升学等方面依法享有平等权利，其人格尊严应受尊重。因成绩差而将学生孤立地安排在最后一排，带有歧视和标签意味，侵犯了学生的平等受教育权和人格尊严。', '["A"]', 0, 0.0, '2026-11-09 17:19:41');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (101, 2, 11, 11, 'judge', 0.6, '某中学组织学生停课参加某商家开业庆典以烘托人气，并接受了商家支付的“活动费”。学校认为这属于正常的社会实践活动，于法不悖。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国义务教育法》第二十五条明确禁止学校以向学生推销或者变相推销商品、服务等方式谋取利益。组织学生参加商业庆典并收取费用，既影响正常教学秩序，又属利用学生牟利的违法行为。', '["A"]', 0, 0.0, '2026-11-09 17:19:41');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (102, 2, 12, 12, 'judge', 0.6, '语文老师教一篇新课文时，先让学生默读感知，再指名朗读体会情感，最后组织讨论、归纳主旨。这一安排符合由感知到理解、再到表达的认识规律。', '[["A","正确"],["B","错误"]]', '["A"]', '默读侧重整体感知文本，朗读深化情感体验，讨论与归纳则推动理解走向理性概括和口头表达。整个过程由感性到理性、由输入到输出，符合学生认识发展的一般规律。', '["A"]', 1, 0.6, '2026-11-09 17:19:42');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (103, 2, 13, 13, 'judge', 0.6, '校运动会上，一名学生在已被检查过的场地内比赛时，因突发阵雨导致场地湿滑而摔伤。学校赛前检查了场地并作了安全提醒，其已尽到教育管理职责，不承担侵权责任。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国民法典》第一千一百九十九条、第一千二百条及《学生伤害事故处理办法》，学校对学生伤害承担过错责任。学校赛前检查场地、进行安全教育，对突发阵雨这一难以预见的情形没有过错，故依法不承担侵权责任。', '["A"]', 1, 0.6, '2026-11-09 17:19:42');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (104, 2, 14, 14, 'judge', 0.6, '某初中教师利用午休时间为学习困难学生义务辅导，分文未取。该教师的行为违反了严禁有偿补课的规定。', '[["A","正确"],["B","错误"]]', '["B"]', '《严禁中小学校和在职中小学教师有偿补课的规定》所禁止的是组织、参与有偿补课或收受费用的行为。该教师利用休息时间免费辅导学生，不具有有偿性，不属于有偿补课。', '["A"]', 0, 0.0, '2026-11-09 17:19:43');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (105, 2, 15, 15, 'judge', 0.6, '某县建立义务教育优质均衡发展督导评估机制，把校际差距、随迁子女入学、教师交流等情况纳入对政府履行教育职责的考核。这种做法不利于扩大校际差距，也不是推进义务教育均衡的重要抓手。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《义务教育优质均衡发展县（市、区）评估认定标准》和教育督导条例，对县级政府开展义务教育优质均衡发展督导评估，把资源配置、校际差距、教师交流等纳入考核，正是推动义务教育优质均衡、督促政府履职的重要制度安排。题干否定其作用。', '["A"]', 0, 0.0, '2026-11-09 17:19:43');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (106, 2, 16, 16, 'judge', 0.6, '根据皮亚杰的认知发展阶段理论，能够进行假设—演绎推理、抽象逻辑思维的中学生，其认知发展处于具体运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '皮亚杰认知发展理论中，具体运算阶段（约7—11岁）的儿童虽获得守恒概念，但思维仍需具体事物支持；能够脱离具体情境进行假设—演绎推理和抽象逻辑思维，是形式运算阶段（约11岁以后）的典型特征。题干阶段归属错误。', '["A"]', 0, 0.0, '2026-11-09 17:19:43');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (107, 2, 17, 17, 'judge', 0.6, '班主任只指定几名成绩优秀、能力强的学生长期固定担任班干部，认为这样班级管理更高效，其他学生无需参与。这体现了面向全体学生的教育理念。', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育要求面向全体学生，促进每一名学生主动发展。只让少数优秀学生长期固定担任班干部，剥夺了多数学生参与班级管理、获得锻炼的机会，是面向少数学生的做法，违背了面向全体学生的教育理念。', '["A"]', 0, 0.0, '2026-11-09 17:19:44');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (108, 2, 18, 18, 'judge', 0.6, '学生设计出有创意的物理实验方案，教师担心“耽误复习、影响考试成绩”，不予表扬也不推荐其参加科技创新比赛。该做法有利于培养学生的创新精神和实践能力。', '[["A","正确"],["B","错误"]]', '["B"]', '培养创新精神和实践能力是素质教育的重点。教师对学生的创新设计持消极态度、不予鼓励和支持，会挫伤学生探究与创造的积极性，与素质教育要求背道而驰。', '["A"]', 0, 0.0, '2026-11-09 17:19:44');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (109, 2, 19, 19, 'judge', 0.6, '学生在解几何题时能够举一反三，把刚学的一种证明方法灵活用于多道变式题。这说明其产生了正迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '正迁移是指先前学习对后继学习产生积极的促进作用。学生把习得的证明方法成功运用到同类变式题中，促进了新问题的解决，属于正迁移。', '["A"]', 1, 0.6, '2026-11-09 17:19:45');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (110, 2, 20, 20, 'judge', 0.6, '某市教育局明确要求学校不得把考试成绩排名作为评价学生的唯一依据。这一要求体现了多元化评价的理念。', '[["A","正确"],["B","错误"]]', '["A"]', '《深化新时代教育评价改革总体方案》要求创新过程性评价方法、完善综合素质评价体系，改变以分数给学生贴标签的做法。不以成绩排名为唯一依据，正体现了评价内容、方式和主体的多元化。', '["A"]', 1, 0.6, '2026-11-09 17:19:45');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (111, 2, 21, 21, 'judge', 0.6, '学生在课堂上提出与教材不同的看法，任课教师为维护教材权威和课堂秩序，当即予以否定并提醒其他学生不要效仿。该做法有利于保护学生的好奇心和求知欲。', '[["A","正确"],["B","错误"]]', '["B"]', '好奇心和求知欲是创造性思维的起点。教师对学生的异见简单否定、当众压制，会造成紧张的心理氛围，使学生不敢质疑，损害其探究兴趣和批判精神；正确做法是肯定独立思考并引导辨析求证。', '["A"]', 0, 0.0, '2026-11-09 17:19:45');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (112, 2, 22, 22, 'judge', 0.6, '小丽学习时总等老师给出标准答案，不习惯主动质疑和探究。从建构主义学习理论看，她需要转变为知识的主动建构者。', '[["A","正确"],["B","错误"]]', '["A"]', '建构主义认为，学习不是知识由教师向学生的单向传递，而是学生在原有经验基础上主动建构意义的过程。被动等待答案难以实现深层理解，小丽应主动探究、合作建构。', '["A"]', 1, 0.6, '2026-11-09 17:19:46');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (113, 2, 23, 23, 'judge', 0.6, '学生每次作业没达到教师要求，都要被点名批评并罚重做。学生为了不被批评，不得不认真完成作业。从强化理论看，教师的批评在这里起到了正强化的作用，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["B"]', '正强化是行为发生后呈现愉快刺激以提高行为概率。批评是学生力图回避的厌恶刺激，学生为逃避或避免批评而认真完成作业，属于负强化（撤销厌恶刺激的预期）或惩罚情境，并非正强化。', '["A"]', 0, 0.0, '2026-11-09 17:19:46');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (114, 2, 24, 24, 'judge', 0.6, '某小学把一名受警告处分学生的姓名、班级和处分决定在全校大会上宣读，并张贴于公告栏。学校认为这是正当的警示教育，不构成侵权。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国未成年人保护法》要求保护未成年人的人格尊严和隐私权、个人信息。对违纪学生的处分应在必要范围内告知本人及其监护人，公开宣读、张贴处分决定带有示众羞辱性质，会使学生的违纪信息被不当扩散，侵犯其人格尊严和隐私权。', '["A"]', 0, 0.0, '2026-11-09 17:19:47');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (115, 2, 25, 25, 'judge', 0.6, '教师节来临，某班家长委员会凑钱为班主任购买了一条名牌项链，班主任认为家长的好意不便推辞，便收下了。该做法符合教师职业行为准则。', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》和《中小学教师违反职业道德行为处理办法》明确要求教师坚守廉洁自律，不得收受学生及家长赠送的可能影响公正执行公务的礼品礼金。项链价值较高，班主任应当婉言谢绝。', '["A"]', 0, 0.0, '2026-11-09 17:19:47');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (116, 2, 26, 26, 'judge', 0.6, '某初中教师每节课都以系统讲授为主，把知识完整讲透并要求学生认真听讲记笔记，几乎不安排自主学习和合作探究。与问题导向、自主探究的教学相比，这种全程系统讲授更能突出学生的主体地位。', '[["A","正确"],["B","错误"]]', '["B"]', '系统讲授以教师活动为主，学生主要是被动接受；问题导向教学通过自主学习、合作探究让学生主动建构知识，更能突出学生的主体地位。题中全程讲授、缺少学生主动参与，反而是教师主体而非学生主体。', '["A"]', 0, 0.0, '2026-11-09 17:19:48');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (117, 2, 27, 27, 'judge', 0.6, '考试失利后，小强认为“题太难、运气差”，自己怎么努力也没用，于是愈发消沉。他的这种反应符合习得性无助的表现。', '[["A","正确"],["B","错误"]]', '["A"]', '习得性无助是指个体反复经历失败后，形成无论怎样努力都无法控制结果的信念，进而产生逃避、放弃等反应。小强把失败外归因并断定努力无用、情绪消沉，正是习得性无助的典型表现。', '["A"]', 1, 0.6, '2026-11-09 17:19:48');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (118, 2, 28, 28, 'judge', 0.6, '学生把连续几次考试失利都归因于“自己天生脑子笨”，并认为再努力也改变不了。这种归因会增强其后续学习的坚持性。', '[["A","正确"],["B","错误"]]', '["B"]', '“天生脑子笨”属于内部、稳定、不可控的能力归因。依据韦纳归因理论，把失败稳定地归于能力不足，会降低自我效能感和成功预期，导致放弃努力，而非增强坚持性。教师应引导其归因于努力、方法等可控因素。', '["A"]', 0, 0.0, '2026-11-09 17:19:48');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (119, 2, 29, 29, 'judge', 0.6, '化学实验中学生如实记录了一个与预期不符的现象，教师以“不在考试范围内”为由要求其删除记录。该做法有利于培养学生的科学精神。', '[["A","正确"],["B","错误"]]', '["B"]', '实事求是、尊重证据是科学精神的核心。教师要求学生删除真实的意外记录，违背了严谨求实的治学态度，也错失了引导学生分析异常现象的教育契机。', '["A"]', 0, 0.0, '2026-11-09 17:19:49');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (120, 2, 30, 30, 'judge', 0.6, '2024年8月26日，中共中央、国务院印发《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。该文件将教育家精神凝练为“心有大我、至诚报国”等十个方面，其中“勤学笃行、求是创新的躬耕态度”要求教师严谨笃学、求真创造。', '[["A","正确"],["B","错误"]]', '["A"]', '该文件确由中共中央、国务院于2024年8月26日印发，全称为《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。教育家精神包括心有大我至诚报国、言为士则行为世范、启智润心因材施教、勤学笃行求是创新、乐教爱生甘于奉献、胸怀天下以文化人等十个方面，题干时间、文件名和对躬耕态度的表述均正确。', '["A"]', 1, 0.6, '2026-11-09 17:19:49');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (121, 2, 31, 31, 'single', 1.0, '三年级数学老师教学面积时，先让学生用手掌量课桌面，再用方格纸量，最后引出面积公式。这一教学过程体现了（　）', '[["A","从理论到实践的顺序原则"],["B","从一般到个别的演绎过程"],["C","从具体到抽象的认识规律"],["D","从抽象到具体的认识规律"]]', '["C"]', '手掌测量是具体操作，方格纸是半抽象的表象工具，面积公式是抽象概括。教学沿着动作感知—表象—概念的路径推进，体现了从具体到抽象的认识规律。A项“顺序原则”强调由浅入深、由易到难的组织顺序，与题意不完全吻合；B项方向相反（从一般到个别属于演绎，而题干是从个别到一般）；D项方向也相反。', '["A"]', 0, 0.0, '2026-11-09 17:19:50');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (122, 2, 32, 32, 'single', 1.0, '小明学习英语语法时，常把英语和汉语的句式放在一起比较，找出二者的异同。他运用的学习策略主要是（　）', '[["A","复述策略"],["B","精细加工策略中的比较法"],["C","组织策略中的归类法"],["D","元认知策略中的监控策略"]]', '["B"]', '比较法是精细加工策略的重要方法，通过对易混知识逐项对照异同，加深理解和辨别。将中英语法进行对比正是比较法的运用。复述侧重重复巩固，组织侧重归类建网，元认知侧重对学习过程的计划与监控，均不贴切。', '["A"]', 0, 0.0, '2026-11-09 17:19:50');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (123, 2, 33, 33, 'single', 1.0, '物理兴趣小组探究单摆周期时，几名中学生先提出“周期可能与摆长、摆锤质量、释放角度都有关”的猜想，再固定其他条件、每次只改变一个变量，分别设计实验加以检验。依据皮亚杰的认知发展阶段理论，这种系统的假设—演绎推理表明他们处于（　）', '[["A","感知运动阶段"],["B","具体运算阶段"],["C","前运算阶段"],["D","形式运算阶段"]]', '["D"]', '皮亚杰通过钟摆实验等研究发现，形式运算阶段（约11岁以后）的个体能够针对问题提出多种假设，并运用控制变量、假设—演绎的方法系统验证。前三个阶段（感知运动、前运算、具体运算）的儿童尚不能脱离具体情境进行严密的假设检验。', '["A"]', 0, 0.0, '2026-11-09 17:19:51');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (124, 2, 34, 34, 'single', 1.0, '物理教师在讲浮力前先问：“为什么铁块沉入水中，而钢铁造的轮船却能浮在水面？”以激发学生的求知欲。该导入方式属于（　）', '[["A","直接导入"],["B","故事导入"],["C","复习导入"],["D","问题导入"]]', '["D"]', '教师围绕教学内容设置悬念性问题，使学生产生认知冲突和探究愿望，属于问题导入（设疑导入）。复习导入依托旧知，故事导入借助故事情境，直接导入则开门见山点明课题，均与题干不同。', '["A"]', 0, 0.0, '2026-11-09 17:19:51');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (125, 2, 35, 35, 'single', 1.0, '某生因考试取得进步，被老师在班上当众表扬，此后他学习更加努力。按班杜拉的强化分类，该生受到的强化属于（　）', '[["A","自我强化"],["B","替代强化"],["C","负强化"],["D","直接强化"]]', '["D"]', '直接强化是指学习者本人的行为因直接得到外部强化而增强。该生自己的进步行为直接受到教师表扬，属于直接强化。替代强化是观察他人受奖惩而受影响，自我强化是依据自己的标准自我奖惩，负强化是撤销厌恶刺激以增加行为。', '["A"]', 0, 0.0, '2026-11-09 17:19:51');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (126, 2, 36, 36, 'single', 1.0, '某市明确要求义务教育阶段学校招生不得采取笔试、面试或任何变相形式的知识性考查。这一要求主要在于维护（　）', '[["A","学校分层教学的自主权"],["B","民办学校优先招生的权利"],["C","适龄儿童免试就近入学的权利"],["D","学校依法自主招生的权利"]]', '["C"]', '《中华人民共和国义务教育法》第十二条规定，适龄儿童、少年免试入学，地方各级人民政府应当保障其在户籍所在地学校就近入学。禁止入学考试和面试，目的在于维护免试就近入学原则和教育公平。B、D项与免试入学要求无关，民办学校招生同样纳入免试入学规范管理。', '["A"]', 0, 0.0, '2026-11-09 17:19:52');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (127, 2, 37, 37, 'single', 1.0, '学生在化学方程式配平中反复出错。下列做法中，最有利于从根本上解决问题的是（　）', '[["A","先引导学生理解质量守恒定律再学配平"],["B","让学生熟记配平口诀和典型例题"],["C","降低要求，暂不要求掌握配平"],["D","增加抄写和重复练习的数量"]]', '["A"]', '配平的依据是质量守恒定律。学生理解反应前后原子种类、数目不变的本质后，才能在新情境中灵活配平，这属于有意义学习，能从根本上减少错误。机械重复和背诵口诀只形成暂时的技能，回避难点则不能解决问题。', '["A"]', 1, 1.0, '2026-11-09 17:19:52');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (128, 2, 38, 38, 'single', 1.0, '初二学生小杰总认为同学和老师都在注意自己的发型和穿着，因而在集体活动中格外紧张、不敢表现。这种“感到自己是他人关注中心”的心理属于（　）', '[["A","客体永久性"],["B","假想的观众"],["C","守恒观念"],["D","思维的不可逆性"]]', '["B"]', '青少年自我中心思维的典型表现之一是“假想的观众”，即总觉得自己处在他人关注的焦点，因而过分在意自己的外表和行为。不可逆性、缺乏守恒是前运算阶段儿童的特点，客体永久性形成于感知运动阶段，均与题干不符。', '["A"]', 0, 0.0, '2026-11-09 17:19:53');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (129, 2, 39, 39, 'single', 1.0, '学生解题时习惯于沿用同一种思路，想不到其他途径，思维明显缺乏变通。教师应着重培养其（　）', '[["A","观察力的敏锐性"],["B","思维的流畅性"],["C","注意力的稳定性"],["D","思维的变通性（灵活性）"]]', '["D"]', '发散思维具有流畅性、变通性和独创性三个特征。只能用一种方法、不能多角度转换思路，反映变通性不足，应通过一题多解、条件变式等训练加以培养。流畅性强调单位时间内观念的数量，注意、观察品质与题干问题不对应。', '["A"]', 0, 0.0, '2026-11-09 17:19:53');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (130, 2, 40, 40, 'single', 1.0, '学校要求教师每学期至少精读一本教育专著并撰写读书笔记。这一要求直接体现的师德规范是（　）', '[["A","终身学习"],["B","为人师表"],["C","爱岗敬业"],["D","关爱学生"]]', '["A"]', '《中小学教师职业道德规范》中的“终身学习”要求教师崇尚科学精神、树立终身学习理念、拓宽知识视野、更新知识结构。持续研读专业著作、撰写笔记是教师专业自我更新的典型表现。', '["A"]', 1, 1.0, '2026-11-09 17:19:54');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (131, 2, 41, 41, 'single', 1.0, '数学课上，老师讲“果实”时既举苹果、花生等可食用的例子，也举棉籽、橡子等不可直接食用的例子，并对比“果实与根、茎”。这些变化正例与反例的运用主要是为了促进学生（　）', '[["A","产生学习迁移"],["B","对概念的变式掌握"],["C","形成操作技能"],["D","机械识记定义"]]', '["B"]', '变式是指变换概念的非本质特征、保持本质特征不变的各类正例，配合反例比较，可帮助学生排除无关特征、准确概括概念的本质属性。机械识记不强调例证比较；操作技能、学习迁移与题干例证设计的直接目的不符。', '["A"]', 0, 0.0, '2026-11-09 17:19:54');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (132, 2, 42, 42, 'single', 1.0, '学生在学习新概念时，总是主动寻找它与已有知识之间的内在联系。按奥苏贝尔的理论，这种学习属于（　）', '[["A","有意义学习"],["B","机械学习"],["C","发现学习"],["D","信号学习"]]', '["A"]', '有意义学习的实质是符号所代表的新知识与学习者认知结构中已有的适当观念建立非人为的、实质性的联系。学生主动把新旧知识联系起来，正是有意义学习的表现。机械学习缺乏这种联系，发现学习强调知识获得的方式，信号学习属于较低级的学习层次。', '["A"]', 1, 1.0, '2026-11-09 17:19:54');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (133, 2, 43, 43, 'single', 1.0, '学生小雯学习十分刻苦，但总把考试成绩归结为题目难易、临场运气等自己无法左右的因素。依据韦纳的成败归因理论，这些因素主要属于（　）', '[["A","外部、不可控的因素"],["B","内部、可控的因素"],["C","内部、稳定的因素"],["D","内部、不稳定的因素"]]', '["A"]', '韦纳把归因分为内外源、稳定性、可控性三个维度。任务难度属外部、稳定、不可控，运气属外部、不稳定、不可控，二者共同点是外部且不可控。努力才是内部、不稳定、可控因素，能力是内部、稳定、不可控因素。', '["A"]', 1, 1.0, '2026-11-09 17:19:55');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (134, 2, 44, 44, 'single', 1.0, '课间，两名七年级学生聊起为什么而学。泽宇说：“我学几何完全是因为图形证明太有意思了，越想越入迷，搞不懂就睡不着。”他既没想着拿名次，也不为换取表扬。按照奥苏贝尔对学校情境中成就动机成分的划分，泽宇身上占主导的是（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","生理需要驱动"],["D","自我提高内驱力"]]', '["B"]', '认知内驱力是一种指向学习任务本身、以求知和解决问题为满足的内部动机，在有意义学习中是最重要、最稳定的动机。泽宇因几何本身的趣味而主动钻研、不计名次表扬，正属认知内驱力。自我提高内驱力指向由成就带来的地位与自尊，附属内驱力指向获得长者和同伴赞许。', '["A"]', 0, 0.0, '2026-11-09 17:19:55');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (135, 2, 45, 45, 'single', 1.0, '教师先呈现一个真实问题，让学生带着问题研读教材、查找资料，再在讨论中形成认识。这种教学的主要理论基础是（　）', '[["A","认知—接受学习理论"],["B","建构主义学习理论"],["C","行为主义学习理论"],["D","人本主义学习理论"]]', '["B"]', '建构主义强调学习的情境性和主动建构性，主张通过真实问题情境中的探究、协作与会话，由学生自主建构知识意义。基于问题、借助资料和讨论的教学与此高度一致。', '["A"]', 0, 0.0, '2026-11-09 17:19:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (136, 2, 46, 46, 'single', 1.0, '某小学将消防安全、应急疏散演练纳入学校安全管理制度，规定每学期至少组织一次。学校开展安全教育和应急演练的直接部门规章依据是（　）', '[["A","《中华人民共和国民办教育促进法》"],["B","《中华人民共和国高等教育法》"],["C","《中小学幼儿园安全管理办法》"],["D","《中华人民共和国学位条例》"]]', '["C"]', '《中小学幼儿园安全管理办法》（教育部等部门发布）明确规定，学校应当对学生开展消防安全、交通安全等安全教育，制定应急预案并定期组织应急演练，是中小学开展疏散演练最直接的规范依据。A、B、D项均不针对中小学日常安全管理与演练。', '["A"]', 0, 0.0, '2026-11-09 17:19:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (137, 2, 47, 47, 'single', 1.0, '每逢数学考试前，某生就出现头痛、肚子痛、心慌出汗等症状，进入考场后注意力难以集中，考试结束症状随即缓解。该生最可能的问题是（　）', '[["A","躯体器质性疾病"],["B","一般性厌学情绪"],["C","考试焦虑"],["D","注意缺陷多动障碍"]]', '["C"]', '考试焦虑是在一定应试情境下，受个体认知评价、人格倾向等影响而产生的以担忧为特征、伴有生理唤醒的心理状态，躯体化症状随考试情境出现和消退是其典型表现。器质性疾病不会随考试结束而缓解，注意缺陷障碍具有跨情境的持续性。', '["A"]', 0, 0.0, '2026-11-09 17:19:57');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (138, 2, 48, 48, 'single', 1.0, '学生苦练硬笔书法一段时间后，最初进步明显，但随后连续几周成绩似乎停滞不前，再练也难有提高，甚至出现烦躁情绪。这种练习中期出现的成绩暂时停顿现象，在心理学上称为（　）', '[["A","功能固着现象"],["B","高原现象"],["C","迁移现象"],["D","遗忘现象"]]', '["B"]', '在操作技能形成过程中，练习中期常出现成绩提升暂时停顿、甚至略有下降的现象，称为“高原现象”，其成因包括旧动作结构需要改造、练习方法不当、兴趣和动机下降等。迁移是学习之间的相互影响，遗忘是记忆内容的消退，功能固着属于问题解决中的思维障碍。', '["A"]', 0, 0.0, '2026-11-09 17:19:57');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (139, 2, 49, 49, 'single', 1.0, '期末复习时，小周把英语单词分散在两周内每天记忆20分钟，而不是考前一天连续背4小时。这种安排主要利用了（　）', '[["A","集中复习优于分散复习的规律"],["B","倒摄抑制的作用"],["C","艾宾浩斯遗忘先快后慢的规律"],["D","高原现象的规律"]]', '["C"]', '艾宾浩斯遗忘曲线表明遗忘进程先快后慢、先多后少，因此应及时复习、合理分散复习时间，在大规模遗忘发生前加以巩固。一般情况下分散复习效果优于集中复习；倒摄抑制指后学材料对先学材料的干扰；高原现象是技能练习中期出现的暂时停顿。', '["A"]', 0, 0.0, '2026-11-09 17:19:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (140, 2, 50, 50, 'single', 1.0, '某中学开设生涯规划课程，引导学生认识自己的兴趣、能力与价值观，了解职业世界并规划发展方向。该课程在德育内容上主要属于（　）', '[["A","人生观与生涯发展指导"],["B","美育中的审美教育"],["C","劳动技术教育中的技能训练"],["D","智育中的思维训练"]]', '["A"]', '德育包括理想信念、社会主义核心价值观、生涯规划等内容。生涯规划教育帮助学生认识自我、明确人生目标，属于德育中的人生观、价值观教育和人生（生涯）发展指导。', '["A"]', 1, 1.0, '2026-11-09 17:19:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (141, 2, 51, 51, 'single', 1.0, '校篮球赛中，一名学生在正常对抗中落地受伤。赛前学校进行了专项安全教育、检查了场地并配备了校医。依法学校（　）', '[["A","无论有无过错均应补偿"],["B","已尽到教育管理职责，不承担侵权责任"],["C","应与对方学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["B"]', '依据《民法典》第一千二百条，限制民事行为能力人在学校学习、生活期间受到人身损害，学校未尽到教育、管理职责的才承担责任。学校已开展安全教育、检查场地、配备医护人员，对正常竞技中的意外受伤没有过错，故不承担侵权责任。', '["A"]', 0, 0.0, '2026-11-09 17:19:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (142, 2, 52, 52, 'single', 1.0, '某教师因几名学生未完成作业，罚他们到操场上跑十圈，致使一名学生体力不支晕倒。该教师的行为属于（　）', '[["A","体罚，侵犯学生身体权和健康权"],["B","合法的教育惩戒"],["C","一般性的课堂管理措施"],["D","正常的体育锻炼"]]', '["A"]', '《中小学教育惩戒规则（试行）》允许的惩戒不包括超越学生身心承受能力的体力惩罚。罚跑十圈直接造成身体痛苦和伤害，属于体罚而非法惩戒，侵犯了学生的身体权、健康权。', '["A"]', 1, 1.0, '2026-11-09 17:19:59');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (143, 2, 53, 53, 'single', 1.0, '市场监管和教育行政部门联合检查时，发现某校食堂操作间卫生不达标、留样不规范，遂责令其限期改正。该执法行为（　）', '[["A","只能在发生食物中毒后实施"],["B","于法有据，是履行食品安全监管职责"],["C","应完全交由学校家委会处理"],["D","属于越权干预学校自主经营"]]', '["B"]', '依据《中华人民共和国食品安全法》和《学校食品安全与营养健康管理规定》，学校食堂实行预防为主、风险管理原则，教育、市场监管部门依法负有日常监督检查职责。事前责令限期整改正是依法履职。', '["A"]', 0, 0.0, '2026-11-09 17:19:59');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (144, 2, 54, 54, 'single', 1.0, '自习课上，教师发现一名学生正用手机玩游戏。最恰当的处理方式是（　）', '[["A","暂时代为保管，课后归还并进行教育引导"],["B","当着全班的面摔毁手机以示警戒"],["C","立即将学生逐出教室反思"],["D","当场将手机没收并永久不予归还"]]', '["A"]', '依据中小学学生手机管理相关规定，学生违规带入或使用手机的，学校可统一保管并及时告知家长。教师暂时代管、课后归还并辅以教育，既维护课堂秩序，又尊重学生财产权和人格尊严。没收不还、逐出教室、损毁财物均缺乏法律依据并可能侵权。', '["A"]', 1, 1.0, '2026-11-09 17:20:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (145, 2, 55, 55, 'single', 1.0, '中共中央、国务院《深化新时代教育评价改革总体方案》要求改革学生评价。下列做法中，不符合该方案方向的是（　）', '[["A","坚决改变以分数给学生贴标签的做法"],["B","健全学生综合素质评价体系"],["C","完善德智体美劳过程性评价"],["D","把升学率作为评价学校办学质量的唯一指标"]]', '["D"]', '《深化新时代教育评价改革总体方案》（2020年印发）提出坚决纠正片面追求升学率倾向，不得把升学率作为评价学校、教师和学生的唯一依据，强调过程性评价和综合素质评价。D项正是方案要破除的做法。', '["A"]', 0, 0.0, '2026-11-09 17:20:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (146, 2, 56, 56, 'single', 1.0, '创造思维训练课上，教师给出钳子、绳子等材料，要求学生想办法同时够到从天花板垂下的两根相距较远、无法一手同时抓住的绳子。多数学生只把钳子看作夹持工具，想不到可把它系在绳端当作摆锤，晃动绳子后趁机抓住。这一现象主要说明问题解决受到（　）', '[["A","功能固着的影响"],["B","学习动机的影响"],["C","原型启发的影响"],["D","正迁移的影响"]]', '["A"]', '功能固着是指个体只看到事物惯常的功能而看不到它其他可能用途的现象。学生只认定钳子是夹持工具，想不到它可作摆锤，这是梅尔双绳实验所揭示的功能固着。原型启发是从其他事物中找到解决问题的途径，正迁移和学习动机与该现象无关。', '["A"]', 1, 1.0, '2026-11-09 17:20:01');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (147, 2, 57, 57, 'single', 1.0, '班上的小亮打碎了教室里1只杯子后主动认错；小杰为偷吃糖果打碎了10只杯子却谎称不是自己干的。问“哪个孩子更不好、应受更重惩罚”时，小学三年级学生大多认为小杰更坏、因为打碎了10只杯子。依据皮亚杰道德发展阶段理论，这些学生的判断主要处于（　）', '[["A","他律道德阶段"],["B","自律道德阶段"],["C","公正道德阶段"],["D","前道德阶段"]]', '["A"]', '皮亚杰通过对偶故事研究发现，他律道德阶段（约5—8岁）的儿童根据行为的客观后果数量判断责任，而不考虑行为动机；自律阶段儿童才会结合主观动机判断。只看打碎杯子数量、忽视说谎与偷拿动机，属于他律道德阶段的特点。', '["A"]', 1, 1.0, '2026-11-09 17:20:01');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (148, 2, 58, 58, 'single', 1.0, '某班在校内劳动实践基地上劳动课，教师事先讲解了工具的安全使用方法并示范操作，一名学生仍未按要求握持工具，不慎被划伤。事后学校及时送医并通知家长。依法学校（　）', '[["A","应承担全部赔偿责任"],["B","已尽到教育、管理和保护职责，不承担侵权责任"],["C","无论有无过错都必须给予赔偿"],["D","应与任课教师平均分担损失"]]', '["B"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任。教师已进行安全教育和操作示范、学校事后及时救助，对学生违反操作规程造成的自伤没有过错，故不承担侵权责任。', '["A"]', 0, 0.0, '2026-11-09 17:20:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (149, 2, 59, 59, 'single', 1.0, '课堂上，数学老师要求学生一边听讲一边在草稿本上记录关键步骤，多数学生能较好地同时完成两项任务。这主要体现了注意的（　）', '[["A","注意的稳定性"],["B","注意的转移"],["C","注意的分配"],["D","注意的范围"]]', '["C"]', '注意的分配是指个体在同一时间内把注意指向两种或两种以上的对象或活动。边听讲边记录要求学生在听和写之间合理分配注意。注意范围强调同一瞬间把握对象的数量，稳定性强调持续时间，转移强调根据任务主动把注意从一个对象转向另一个对象。', '["A"]', 0, 0.0, '2026-11-09 17:20:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (150, 2, 60, 60, 'single', 1.0, '一位中学教师持续跟踪本学科研究进展，把经过筛选的最新科研成果转化为教学案例，帮助学生了解学科前沿。这主要体现了（　）', '[["A","教师把科研任务转嫁给学生"],["B","以研究取代常规课堂教学"],["C","教学完全脱离教材体系"],["D","教学内容与学术研究相结合"]]', '["D"]', '教师把学科前沿成果筛选、转化为适切的教学素材，体现了科研与教学相长，有利于拓宽学生视野、培养科学素养。A项把科研成果转化曲解为“转嫁任务”，与教师主动筛选转化的行为不符；B项将科研促教绝对化为“取代课堂教学”，C项则完全否定教材体系，均与题干事实相悖。', '["A"]', 0, 0.0, '2026-11-09 17:20:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (151, 2, 61, 61, 'single', 1.0, '复习化学时，某生把零散的物质按“单质—化合物—混合物”的类别整理成表格，再把各类物质的性质、制法和用途归并到一起记忆。该学习策略主要属于（　）', '[["A","元认知策略中的计划策略"],["B","复述策略"],["C","精细加工策略中的记忆术"],["D","组织策略中的归类法"]]', '["D"]', '组织策略是对学习材料进行加工，按照其内在联系加以归类、整理，形成清晰认知结构的策略。该生按物质分类建表、归并性质与用途，正是归类法的典型运用。复述侧重重复巩固，记忆术侧重人为联想以增强保持，计划策略侧重对学习活动的预先安排。', '["A"]', 0, 0.0, '2026-11-09 17:20:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (152, 2, 62, 62, 'single', 1.0, '部分学生习惯于机械背诵，对知识不求甚解，遇到变式题就出错。教师应着重引导其（　）', '[["A","加大机械重复的遍数"],["B","放弃记忆，只做难题"],["C","在理解的基础上进行有意义学习"],["D","延长每次记忆的时间"]]', '["C"]', '机械学习获得的知识难以迁移，变式题出错的根源是没有理解知识的实质和内在联系。教师应帮助学生把新知识纳入已有认知结构，开展有意义学习，并辅以变式练习。', '["A"]', 0, 0.0, '2026-11-09 17:20:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (153, 2, 63, 63, 'single', 1.0, '升入初中后，小芸在家长帮助下制定学习计划时，会主动预估某项任务大约需要多长时间，并据此安排先后顺序。这种对认知活动的预先规划属于（　）', '[["A","资源管理策略中的时间管理"],["B","元认知计划策略"],["C","复述策略"],["D","精加工策略"]]', '["B"]', '元认知策略包括计划、监控和调节策略。在认知活动开始前设置目标、预估任务难度与时间、安排学习步骤，属于元认知计划策略。复述策略侧重重复保持信息，精加工策略侧重为信息增加意义，时间管理策略侧重对学习时间资源的统筹，均不直接指向对认知过程的预先规划。', '["A"]', 0, 0.0, '2026-11-09 17:20:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (154, 2, 64, 64, 'single', 1.0, '某校在防治校园欺凌中建立早期预警机制。下列做法中，不属于早期预警措施的是（　）', '[["A","定期开展心理健康普查并建立重点关注台账"],["B","仅在发生严重伤害事件后再介入处理"],["C","畅通学生、家长欺凌线索报告渠道"],["D","通过日常观察和同伴关系调查识别风险信号"]]', '["B"]', '早期预警强调关口前移，通过心理筛查、风险排查、线索报告和主题教育等主动发现隐患。事后处理是末端应对而非预防预警。', '["A"]', 0, 0.0, '2026-11-09 17:20:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (155, 2, 65, 65, 'single', 1.0, '一位教师在教学后记中写道：“今天进度偏快，部分学生来不及思考，下次应放慢节奏，多留讨论时间。”这主要反映了教师的（　）', '[["A","关注学情并自觉改进教学的反思意识"],["B","只关注教学进度完成情况"],["C","对学生差异的无条件迁就"],["D","以个人经验否定教学计划"]]', '["A"]', '教师依据课堂上观察到的学习状态审视教学，并提出针对性的调整方案，属于教学反思，体现了以学定教和持续改进的专业意识。', '["A"]', 1, 1.0, '2026-11-09 17:20:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (156, 2, 66, 66, 'single', 1.0, '一名学生因家境困难而自卑，很少与同学交往。班主任一方面关心鼓励他、协助其申请助学金，另一方面引导同学在小组活动中主动接纳他。该做法体现了（　）', '[["A","以经济资助代替思想教育"],["B","关爱学生与集体教育相结合"],["C","只依靠班集体进行教育"],["D","把学生的家庭情况公开通报"]]', '["B"]', '教师个人的关爱与帮扶解决了学生的实际困难和心理压力，组织同伴互助则发挥了集体的教育力量，两者结合帮助学生走出自卑，符合关爱学生与集体教育相结合的要求。', '["A"]', 0, 0.0, '2026-11-09 17:20:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (157, 2, 67, 67, 'single', 1.0, '一名学生因沉迷手机游戏导致成绩明显下降、上课精神不振。班主任较恰当的做法是（　）', '[["A","不经学生同意直接查阅其手机全部内容"],["B","把问题完全推给家长，学校不再过问"],["C","了解原因，引导其认识危害并共同制定合理用机计划"],["D","当众严厉训斥并永久禁止其接触手机"]]', '["C"]', '手机沉迷的成因复杂，简单禁止或放任都难以奏效。教师应在尊重学生的基础上了解需求、讲清危害，与学生、家长协商制定可执行的用机规则，并以丰富的活动转移注意。', '["A"]', 0, 0.0, '2026-11-09 17:20:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (158, 2, 68, 68, 'single', 1.0, '作文基础薄弱的学生，在老师系统指导和同伴互助下，能独立完成此前无法完成的800字议论文；脱离帮助后，他仍只能写约500字。维果斯基把“独立解决问题的实际水平”与“成人指导下可达到的水平”之间的差距称为（　）', '[["A","关键期"],["B","学习准备状态"],["C","最近发展区"],["D","认知风格差异"]]', '["C"]', '维果斯基提出的最近发展区，是指儿童独立解决问题所确定的现有发展水平，与在成人指导或与有能力同伴合作下解决问题所达到的潜在发展水平之间的差距，教学应着眼于“跳一跳、摘桃子”。关键期强调特定能力发展的最佳时机，认知风格、学习准备均不描述这一差距。', '["A"]', 0, 0.0, '2026-11-09 17:20:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (159, 2, 69, 69, 'single', 1.0, '课堂上一名学生对教材结论提出有依据的质疑。教师最恰当的回应是（　）', '[["A","暂时回避，课后单独批评"],["B","以维护教材权威为由不予讨论"],["C","提醒学生只需记住考试结论"],["D","肯定质疑精神，组织学生辨析求证"]]', '["D"]', '面对有价值的质疑，教师应发扬教学民主，把质疑转化为教学资源，引导学生寻找证据、辨析论证，既解决问题又培养批判精神。', '["A"]', 0, 0.0, '2026-11-09 17:20:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (160, 2, 70, 70, 'single', 1.0, '某市推行“阳光招生”，要求招生计划、程序、结果全程公开，接受社会监督。这一做法主要有利于（　）', '[["A","维护教育公平，保障群众的知情权和监督权"],["B","扩大学校的招生自由裁量权"],["C","弱化教育行政部门的监管责任"],["D","以社会评价替代教育评价"]]', '["A"]', '招生信息公开把入学机会置于社会监督之下，有助于遏制“掐尖招生”“条子生”等违规行为，保障入学机会公平和群众的知情权、监督权。', '["A"]', 1, 1.0, '2026-11-09 17:20:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (161, 2, 71, 71, 'single', 1.0, '学生把ambulance（救护车）谐音联想为“俺不能死”来记忆单词。这种记忆方法属于（　）', '[["A","复述策略"],["B","精细加工策略中的谐音联想法"],["C","组织策略中的纲要法"],["D","元认知策略中的调节策略"]]', '["B"]', '谐音联想法是借助读音相似把抽象、无意义材料转化为有意义表象的精细加工策略。复述、组织、元认知策略的功能与题干方法不符。', '["A"]', 0, 0.0, '2026-11-09 17:20:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (162, 2, 72, 72, 'single', 1.0, '学生作文普遍空洞，教师分析后发现主要原因是生活观察和体验不足。下列做法中最有针对性的是（　）', '[["A","以抄写优美句段代替写作训练"],["B","要求学生大量背诵优秀作文模板"],["C","降低字数和立意要求"],["D","组织观察、实践活动，丰富直接经验和写作素材"]]', '["D"]', '写作是对生活经验加工表达的过程。“无米下锅”靠套模板、抄句段无法根治，组织观察与实践活动可充实感性经验，解决素材贫乏的根源问题。', '["A"]', 0, 0.0, '2026-11-09 17:20:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (163, 2, 73, 73, 'single', 1.0, '一位教师坚持每周撰写教学反思，系统记录成功经验、问题教训和改进设想，三年后教学水平显著提升。这一专业发展途径主要是（　）', '[["A","脱产学历进修"],["B","单纯依靠专家讲座"],["C","自我反思与行动研究"],["D","同事之间的随机闲谈"]]', '["C"]', '波斯纳提出“教师成长 = 经验 + 反思”。持续、系统地反思教学并据以改进，是教师立足岗位的自我教育和行动研究，是专业发展最直接的途径之一。', '["A"]', 0, 0.0, '2026-11-09 17:20:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (164, 2, 74, 74, 'single', 1.0, '春游中，一名学生在自由活动时违反事先反复强调的安全要求，与同学追逐打闹致自己摔伤。学校事前勘察了路线、进行了安全教育并安排足够教师跟班。依法学校（　）', '[["A","已尽到教育管理职责，不承担侵权责任"],["B","只要发生在校外活动中就须担责"],["C","应与受伤学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["A"]', '依据《学生伤害事故处理办法》和《民法典》相关规定，学校责任以过错为前提。学校履行了安全教育、路线勘查和人员配备义务，损害由学生违反纪律的自险行为造成，学校没有过错，故不承担侵权责任。B项将校外活动一律归责，C项无法律依据要求平均分摊，D项全额赔偿更无事实与法律基础。', '["A"]', 1, 1.0, '2026-11-09 17:20:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (165, 2, 75, 75, 'single', 1.0, '学生计算能力正常，却常常不会做应用题，主要问题在于读不懂题意、抓不住数量关系。教师应优先培养其（　）', '[["A","阅读理解与关键信息提取能力"],["B","机械背诵公式的能力"],["C","几何作图能力"],["D","计算的速度和准确率"]]', '["A"]', '应用题解题的前提是理解文字情境、识别已知条件与问题、抽象出数量关系。困难出在题意理解环节，就应通过说题、画示意图、圈画关键词等方式提高阅读理解和信息提取能力。', '["A"]', 1, 1.0, '2026-11-09 17:20:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (166, 2, 76, 76, 'single', 1.0, '教师注意发现每名学生身上的闪光点，及时给予具体的肯定和鼓励，学生的自信心和完成任务的坚持性明显增强。这种做法主要是通过提升（　）发挥作用的。', '[["A","流体智力水平"],["B","学习兴趣的广度"],["C","认知风格的灵活性"],["D","自我效能感"]]', '["D"]', '自我效能感是个体对自己能否成功完成某一任务的信念，成败经验和他人的积极评价是其重要来源。具体、真诚的肯定能帮助学生积累成功体验，提高自我效能感。', '["B"]', 0, 0.0, '2026-11-09 17:20:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (167, 2, 77, 77, 'single', 1.0, '某校把师德师风考核结果作为教师年度考核、职称评聘和评优奖励的首要标准，实行师德失范“一票否决”。这一做法体现了（　）', '[["A","以科研论文数量主导考核"],["B","以学历层次决定教师待遇"],["C","把师德师风作为评价教师第一标准"],["D","以教学成绩为核心的评价导向"]]', '["C"]', '《深化新时代教育评价改革总体方案》和《关于加强和改进新时代师德师风建设的意见》均强调把师德师风作为教师评价的第一标准，落实师德失范“一票否决”。', '["B"]', 0, 0.0, '2026-11-09 17:20:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (168, 2, 78, 78, 'single', 1.0, '学英语时，小梅先掌握的汉语拼音发音，常使她把英语字母读成拼音；经过一段时间练习后，新学的英语拼读又偶尔干扰她认读拼音。前一种情形主要属于（　）', '[["A","消退抑制"],["B","前摄抑制"],["C","超限抑制"],["D","倒摄抑制"]]', '["B"]', '先学习的材料对识记和回忆后学习材料的干扰称前摄抑制；后学习的材料对保持先学习材料的干扰称倒摄抑制。汉语拼音先学并干扰英语认读，属于前摄抑制。题干后半句英语反过来干扰拼音才是倒摄抑制，应注意二者的时间顺序。', '["B"]', 1, 1.0, '2026-11-09 17:20:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (169, 2, 79, 79, 'single', 1.0, '一名家庭经济困难学生产生辍学念头，班主任多次家访劝学，协助其申请助学金和社会资助，最终帮助其安心完成学业。该做法主要体现了教师（　）', '[["A","控辍保学、保障适龄儿童接受义务教育的责任"],["B","管理学校财务的行政责任"],["C","开展教育科学研究的责任"],["D","提高班级升学率的教学责任"]]', '["A"]', '《中华人民共和国义务教育法》要求政府、学校、家庭共同做好控辍保学工作，发现学生辍学应及时劝返并帮助解决实际困难。班主任劝学并协助资助，是落实控辍保学责任的体现。', '["B"]', 0, 0.0, '2026-11-09 17:20:13');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (170, 2, 80, 80, 'single', 1.0, '某市推进教育数字化，支持学校建设智慧课堂，利用大数据开展学情诊断、推送分层学习资源。这一举措的主要价值在于（　）', '[["A","减少学校对教学管理的投入"],["B","用信息技术完全取代教师"],["C","赋能因材施教，提高教学质量"],["D","统一拉平所有学生的学习进度"]]', '["C"]', '《教育强国建设规划纲要（2024—2035年）》强调建设教育数字化体系。智慧课堂和学情数据分析有助于精准把握差异、提供个性化资源，赋能因材施教和质量提升，但技术是辅助手段，不能取代教师。', '["B"]', 0, 0.0, '2026-11-09 17:20:13');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (171, 2, 81, 81, 'multi', 1.6, '某小学深化课程改革，采取了下列措施：开设可供选择的兴趣选修课、推行项目式学习、实行多元过程性评价、鼓励教师合作开发校本课程。这些措施体现的新课程理念有（　）', '[["A","课程结构的选择性"],["B","项目式学习意味着完全取消教师讲授和系统知识学习"],["C","把学生考试成绩作为唯一衡量标准"],["D","评价主体与方式的多元化"],["E","校本课程只能由校外专家开发，教师只负责执行"]]', '["A","D"]', 'A正确：开设可供选择的兴趣选修课体现了课程结构的选择性，照顾学生差异。B错误：项目式学习倡导自主、合作、探究，但并不否定必要的教师讲授和系统知识学习，二者应有机结合。D正确：多元过程性评价体现评价主体和方式多元化。C错误：以分数为唯一标准是新课改要破除的甄别式评价。E错误：教师是课程的建设者和开发者，可以参与校本课程开发。', '["B"]', 0, 0.0, '2026-11-09 17:20:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (172, 2, 82, 82, 'multi', 1.6, '学习中，不同问题可以采用不同的学习策略：上课容易走神时需要加强注意的自我监控；记不住零散知识点时需要精加工和及时复习；不会写作文时需要增加观察体验并借鉴范文结构。下列对应正确的有（　）', '[["A","上课走神——运用元认知监控策略，及时调节注意"],["B","记不住知识点——适当运用复述、精加工和组织策略并及时复习"],["C","学习困难只能靠延长学习时间、增加重复遍数解决"],["D","不会写作文——丰富直接经验，运用读写结合的方法"],["E","只要学习策略足够好，就可以忽略学习动机和原有知识基础"]]', '["A","B","D"]', 'A正确：对注意和理解过程的自我觉察、及时调节属于元认知监控策略。B正确：针对零散知识，复述、精细加工、归类组织并依据遗忘规律及时复习是有效方法。D正确：写作困难常源于直接经验不足，应通过观察实践和范文借鉴加以解决。C错误：机械延长时间、简单重复忽视理解和策略运用，效率低下。E错误：策略运用受学习动机、原有知识基础等因素制约，不能脱离这些条件孤立发挥作用。', '["B"]', 0, 0.0, '2026-11-09 17:20:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (173, 2, 83, 83, 'multi', 1.6, '某班主任在班级管理中采取了下列做法：实行值日班长轮流制、定期召开班会讨论班级事务、建立班级公约和岗位责任制、对违纪学生只靠罚抄课文处理。其中符合现代班级管理理念的有（　）', '[["A","实行值日班长轮流制，让学生在参与中学会自治"],["B","定期召开班会讨论班级事务，发挥学生的主体作用"],["C","建立班级公约和岗位责任制，实现班级管理的制度化"],["D","对违纪学生一律罚抄课文，以加重学生负担来维持纪律"],["E","班级事务完全由班主任一人决定，学生只需服从执行"]]', '["A","B","C"]', 'A、B、C正确：轮流管理、班会民主议事、公约与岗位责任制体现了学生主体、民主参与和自主管理的现代班级管理理念。D错误：罚抄课文属于变相体罚和机械惩罚，既不符合教育惩戒要求，也不能从根本上引导学生自律。E错误：班主任独断专行会压抑学生的主动性和责任感，不符合班级民主管理方向。', '["B"]', 0, 0.0, '2026-11-09 17:20:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (174, 2, 84, 84, 'multi', 1.6, '某校六年级两名学生在课间追逐打闹，教师多次提醒后，一名学生仍将同学推倒致其骨折。关于学校责任的认定，下列说法正确的有（　）', '[["A","学校是否承担责任，以其是否尽到教育、管理职责为判断标准"],["B","学校已进行必要的安全教育和管理且无过错的，不承担侵权责任"],["C","有过错的学生监护人依法承担相应的侵权责任"],["D","伤害发生在校园内，学校无论有无过错都必须承担全部赔偿责任"],["E","学校应当及时救助受伤害学生，并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任，以是否尽到教育、管理职责为判断标准（A、B正确）；加害学生一方有过错的，由其监护人依法承担相应责任（C正确）；学校还负有及时救助、告知监护人的法定义务（E正确）。D错误：校园内发生伤害并不导致学校当然全责，归责仍以过错为要件。', '["B"]', 0, 0.0, '2026-11-09 17:20:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (175, 2, 85, 85, 'multi', 1.6, '某市对学校课后服务工作提出要求：服务内容要多样化，要尊重学生和家长的自主选择，要为学习有困难的学生提供辅导，不得利用课后服务时间统一讲授新课。这些要求符合（　）', '[["A","满足学生多样化发展需求"],["B","尊重学生和家长的自愿选择"],["C","对学习困难学生进行必要的学业帮扶"],["D","借课后服务之名集体补课、增加学生负担"],["E","把课后服务办成统一的新课教学"]]', '["A","B","C"]', 'A正确：多样化内容有助于发展兴趣特长、促进全面发展。B正确：课后服务坚持学生自愿、家长自愿原则。C正确：对学习有困难的学生进行答疑辅导是课后服务的重要内容。D、E错误：依据“双减”政策，课后服务不得变成集体补课或讲授新课，不得加重学生课业负担。', '["B"]', 0, 0.0, '2026-11-09 17:20:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (176, 2, 86, 86, 'multi', 1.6, '一位语文教师经常运用情境教学。下列属于情境教学法基本特征的有（　）', '[["A","以生动具体的形象激发学生的情感体验"],["B","课堂中只允许学生体验，不进行任何理性概括和知识讲授"],["C","教师只作旁观，完全不加以引导和点拨"],["D","创设与教学内容相适应的真实或模拟情境"],["E","情境越离奇、越脱离学生生活，教学效果越好"]]', '["A","D"]', '情境教学（以李吉林情境教育为代表）以“形真、情切、意远、理寓其中”为特点：A正确，借助生动具体的形象唤起情感体验；D正确，强调围绕教学内容创设真实或模拟的情境。B错误：情境教学主张情知交融、在体验基础上引导概括，并不排斥理性认识和必要讲授。C错误：教师要适时引导、点拨、升华，而非放任旁观。E错误：情境应贴近学生已有生活经验和认知水平，脱离生活反而妨碍理解。', '["B"]', 0, 0.0, '2026-11-09 17:20:16');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (177, 2, 87, 87, 'multi', 1.6, '某校组织学生乘大巴参加校外实践活动，途中因其他车辆违章变道发生交通事故，造成学生受伤，学校大巴驾驶员和随车教师并无过错。关于责任承担，下列说法正确的有（　）', '[["A","学生有权依法获得赔偿"],["B","事故责任应由违章车辆一方依法承担"],["C","学校已尽到组织管理和安全保障义务的，不承担侵权责任"],["D","只要发生在校外活动中，学校就应承担全部责任"],["E","学校应及时救助受伤学生并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》侵权责任编和《学生伤害事故处理办法》，学生伤害事故责任以过错为原则。本案由第三方违章造成，应由责任方承担赔偿；学校无过错则不承担侵权责任，但仍负有及时救助、告知和报告义务，A、B、C、E正确。D错误：学校责任不依“校外”这一地点当然成立，而取决于是否尽到教育、管理职责。', '["B"]', 0, 0.0, '2026-11-09 17:20:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (178, 2, 88, 88, 'multi', 1.6, '某校校园文化节安排了经典诵读、民族歌舞表演、传统手工艺制作和民族文化展板等活动。这些活动的育人价值在于（　）', '[["A","增进学生对中华优秀传统文化的认同"],["B","促进民族团结教育和文化理解"],["C","在实践体验中提高学生的审美和动手能力"],["D","文化节只是娱乐活动，与育人目标无关"],["E","丰富校园文化生活，营造良好的隐性课程环境"]]', '["A","B","C","E"]', '传统文化展示有助于文化认同与文化自信（A）；民族歌舞、民族文化内容可渗透民族团结教育（B）；表演与手工艺制作能发展审美和实践能力（C）；丰富的校园文化本身构成隐性课程，发挥潜移默化的育人作用（E）。D错误：校园文化活动是学校教育和隐性课程的重要载体，具有明确的育人功能。', '["B"]', 0, 0.0, '2026-11-09 17:20:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (179, 2, 89, 89, 'multi', 1.6, '一位教师反思后发现自己“讲得太多、学生参与太少”，于是调整教学：增加课堂提问与讨论、设计小组合作任务、留出学生练习和展示时间。这种调整符合（　）', '[["A","启发性教学原则"],["B","教师主导与学生主体相统一的规律"],["C","以学生活动完全取代教师讲授"],["D","调动学生学习的主动性"],["E","促进学生从学会走向会学"]]', '["A","B","D","E"]', '增加提问讨论、合作探究体现启发性原则（A）和教师主导作用与学生主体作用相统一的教学规律（B）；学生在提问、讨论和展示中由被动接受转为主动参与，有利于调动学习主动性（D）；教师由“教会知识”转向引导学生掌握方法，促进学生从“学会”走向“会学”（E）。C错误：强调学生主体并不否定教师必要的讲授与引导，讲授法在系统传授知识方面仍有不可替代的价值。', '["B"]', 0, 0.0, '2026-11-09 17:20:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (180, 2, 90, 90, 'multi', 1.6, '某市要求学校改革学生评价：不以分数作为评价学生的唯一依据、关注学生成长过程、重视学生的自我反思与同伴互评。这体现的评价理念有（　）', '[["A","评价内容的综合化，关注德智体美劳全面发展"],["B","评价方式的过程化与多元化"],["C","评价主体的多元化，强调学生参与"],["D","以甄别和选拔为唯一目的的评价观"],["E","发挥评价促进学生发展的教育功能"]]', '["A","B","C","E"]', '不以分数为唯一依据体现评价内容综合化（A）；关注成长过程、采用多元方式体现过程性、多元化评价（B）；自我反思与同伴互评体现评价主体多元（C）；改革的落脚点是促进发展（E）。D错误：甄别选拔是传统评价的突出功能，发展性评价强调激励、诊断与改进，反对“为了选拔而评价”。', '["B"]', 0, 0.0, '2026-11-09 17:20:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (181, 4, 1, 1, 'judge', 0.6, '某小学数学老师教学乘法时，先让学生用加法算 3 + 3 + 3 + 3 = 12，再引入乘法 3×4 = 12。这种从加法到乘法的学习属于下位学习。', '[["A","正确"],["B","错误"]]', '["A"]', '乘法是几个相同加数连加的简便运算，是加法概念下的派生类属概念。学生在已掌握加法的基础上学习乘法，新概念从属于原有概念，属于奥苏贝尔所说的下位学习（派生类属学习）。', '["A"]', 1, 0.6, '2026-11-09 17:21:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (182, 4, 2, 2, 'judge', 0.6, '高一学生小柯在“学医还是学文”之间犹豫：父母希望他学医，他自己热爱文学，两个目标都想得到却只能选择其一。小柯面临的这种心理冲突属于趋避冲突。', '[["A","正确"],["B","错误"]]', '["B"]', '两个都想要的目标只能择其一，属于双趋冲突（接近—接近型冲突）。趋避冲突是指同一个目标同时具有吸引力和排斥力；双避冲突是两个目标都想回避却必须选择其一。题干把双趋冲突误判为趋避冲突。', '["B"]', 1, 0.6, '2026-11-09 17:21:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (183, 4, 3, 3, 'judge', 0.6, '某中学物理老师在学生回答与预设答案不同时，总是追问“你为什么这样想”，要求学生说明理由和依据。这种做法有利于培养学生的批判性思维。', '[["A","正确"],["B","错误"]]', '["A"]', '批判性思维要求学生对观点进行理性审视、有根据地思考和论证。教师持续追问理由和依据，能促使学生不盲从结论、学会用证据支持观点。', '["B"]', 0, 0.0, '2026-11-09 17:21:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (184, 4, 4, 4, 'judge', 0.6, '小学六年级学生小芳学完百分数后，能用百分数表示折扣、利率等生活中的比例关系。这种把课堂知识用于新情境的表现体现了学习迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '学习迁移是指一种学习对另一种学习的影响。学生把课堂上获得的百分数知识运用到折扣、利率等陌生的生活情境中，属于知识在新情境中的正迁移。', '["B"]', 0, 0.0, '2026-11-09 17:21:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (185, 4, 5, 5, 'judge', 0.6, '某市教育局在评估中发现某校向学生统一推销教辅资料并收取费用，遂责令学校立即整改、退还费用。该教育局的处理于法有据。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国义务教育法》第二十五条，学校不得违反国家规定收取费用，不得以向学生推销或者变相推销商品、服务等方式谋取利益；《中小学教师违反职业道德行为处理办法》也明令禁止教师强制或变相强制学生订购教辅。教育行政部门有权责令改正、退还费用。', '["B"]', 0, 0.0, '2026-11-09 17:21:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (186, 4, 6, 6, 'judge', 0.6, '某小学教师为提高成绩，每天布置大量重复性抄写作业，多数学生要写到深夜。该做法违反了“双减”政策关于作业总量和时长调控的要求。', '[["A","正确"],["B","错误"]]', '["A"]', '《关于进一步减轻义务教育阶段学生作业负担和校外培训负担的意见》要求小学三至六年级书面作业平均完成时间不超过60分钟，并鼓励布置分层、弹性和个性化作业，避免机械重复训练。大量重复性抄写加重了学生负担。', '["B"]', 0, 0.0, '2026-11-09 17:21:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (187, 4, 7, 7, 'judge', 0.6, '英语考试中，小明做阅读理解时先快速浏览全文把握结构，再带着题目回读相关段落。小明运用的主要是元认知策略。', '[["A","正确"],["B","错误"]]', '["A"]', '先浏览全文以确定阅读目标和重点，属于元认知策略中的计划策略；带着问题有针对性地回读、随时检验自己是否读懂，属于监控策略。二者均属元认知策略。', '["B"]', 0, 0.0, '2026-11-09 17:21:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (188, 4, 8, 8, 'judge', 0.6, '心理辅导老师把辅导中获悉的学生家庭变故等隐私，当作谈资告诉了其他任课教师。该做法侵犯了学生的隐私权。', '[["A","正确"],["B","错误"]]', '["A"]', '《中华人民共和国未成年人保护法》第四条规定处理未成年人事项应当保护未成年人隐私权和个人信息。心理辅导记录涉及未成年人个人隐私，未经本人及其监护人同意不得向无关人员披露。', '["B"]', 0, 0.0, '2026-11-09 17:21:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (189, 4, 9, 9, 'judge', 0.6, '某初中教师试行翻转课堂：基础知识由学生课前借助微课自学，课堂主要用于答疑、探究和协作练习。这种模式有利于培养学生的自主学习能力。', '[["A","正确"],["B","错误"]]', '["A"]', '翻转课堂把知识传授前移到课前由学生自主完成，课堂则转向深度学习与合作探究，客观上要求并锻炼学生自我规划、自我监控的学习能力。', '["B"]', 0, 0.0, '2026-11-09 17:21:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (190, 4, 10, 10, 'judge', 0.6, '某小学教师以成绩差为由，长期安排一名学生单独坐在教室最后一排。该做法没有侵犯学生的合法权益。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《中华人民共和国义务教育法》和《未成年人保护法》，学生在入学、升学等方面依法享有平等权利，其人格尊严应受尊重。因成绩差而将学生孤立地安排在最后一排，带有歧视和标签意味，侵犯了学生的平等受教育权和人格尊严。', '["B"]', 1, 0.6, '2026-11-09 17:21:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (191, 4, 11, 11, 'judge', 0.6, '某中学组织学生停课参加某商家开业庆典以烘托人气，并接受了商家支付的“活动费”。学校认为这属于正常的社会实践活动，于法不悖。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国义务教育法》第二十五条明确禁止学校以向学生推销或者变相推销商品、服务等方式谋取利益。组织学生参加商业庆典并收取费用，既影响正常教学秩序，又属利用学生牟利的违法行为。', '["B"]', 1, 0.6, '2026-11-09 17:21:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (192, 4, 12, 12, 'judge', 0.6, '语文老师教一篇新课文时，先让学生默读感知，再指名朗读体会情感，最后组织讨论、归纳主旨。这一安排符合由感知到理解、再到表达的认识规律。', '[["A","正确"],["B","错误"]]', '["A"]', '默读侧重整体感知文本，朗读深化情感体验，讨论与归纳则推动理解走向理性概括和口头表达。整个过程由感性到理性、由输入到输出，符合学生认识发展的一般规律。', '["B"]', 0, 0.0, '2026-11-09 17:21:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (193, 4, 13, 13, 'judge', 0.6, '校运动会上，一名学生在已被检查过的场地内比赛时，因突发阵雨导致场地湿滑而摔伤。学校赛前检查了场地并作了安全提醒，其已尽到教育管理职责，不承担侵权责任。', '[["A","正确"],["B","错误"]]', '["A"]', '依据《中华人民共和国民法典》第一千一百九十九条、第一千二百条及《学生伤害事故处理办法》，学校对学生伤害承担过错责任。学校赛前检查场地、进行安全教育，对突发阵雨这一难以预见的情形没有过错，故依法不承担侵权责任。', '["B"]', 0, 0.0, '2026-11-09 17:21:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (194, 4, 14, 14, 'judge', 0.6, '某初中教师利用午休时间为学习困难学生义务辅导，分文未取。该教师的行为违反了严禁有偿补课的规定。', '[["A","正确"],["B","错误"]]', '["B"]', '《严禁中小学校和在职中小学教师有偿补课的规定》所禁止的是组织、参与有偿补课或收受费用的行为。该教师利用休息时间免费辅导学生，不具有有偿性，不属于有偿补课。', '["B"]', 1, 0.6, '2026-11-09 17:21:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (195, 4, 15, 15, 'judge', 0.6, '某县建立义务教育优质均衡发展督导评估机制，把校际差距、随迁子女入学、教师交流等情况纳入对政府履行教育职责的考核。这种做法不利于扩大校际差距，也不是推进义务教育均衡的重要抓手。', '[["A","正确"],["B","错误"]]', '["B"]', '依据《义务教育优质均衡发展县（市、区）评估认定标准》和教育督导条例，对县级政府开展义务教育优质均衡发展督导评估，把资源配置、校际差距、教师交流等纳入考核，正是推动义务教育优质均衡、督促政府履职的重要制度安排。题干否定其作用。', '["B"]', 1, 0.6, '2026-11-09 17:21:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (196, 4, 16, 16, 'judge', 0.6, '根据皮亚杰的认知发展阶段理论，能够进行假设—演绎推理、抽象逻辑思维的中学生，其认知发展处于具体运算阶段。', '[["A","正确"],["B","错误"]]', '["B"]', '皮亚杰认知发展理论中，具体运算阶段（约7—11岁）的儿童虽获得守恒概念，但思维仍需具体事物支持；能够脱离具体情境进行假设—演绎推理和抽象逻辑思维，是形式运算阶段（约11岁以后）的典型特征。题干阶段归属错误。', '["B"]', 1, 0.6, '2026-11-09 17:21:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (197, 4, 17, 17, 'judge', 0.6, '班主任只指定几名成绩优秀、能力强的学生长期固定担任班干部，认为这样班级管理更高效，其他学生无需参与。这体现了面向全体学生的教育理念。', '[["A","正确"],["B","错误"]]', '["B"]', '素质教育要求面向全体学生，促进每一名学生主动发展。只让少数优秀学生长期固定担任班干部，剥夺了多数学生参与班级管理、获得锻炼的机会，是面向少数学生的做法，违背了面向全体学生的教育理念。', '["B"]', 1, 0.6, '2026-11-09 17:21:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (198, 4, 18, 18, 'judge', 0.6, '学生设计出有创意的物理实验方案，教师担心“耽误复习、影响考试成绩”，不予表扬也不推荐其参加科技创新比赛。该做法有利于培养学生的创新精神和实践能力。', '[["A","正确"],["B","错误"]]', '["B"]', '培养创新精神和实践能力是素质教育的重点。教师对学生的创新设计持消极态度、不予鼓励和支持，会挫伤学生探究与创造的积极性，与素质教育要求背道而驰。', '["B"]', 1, 0.6, '2026-11-09 17:21:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (199, 4, 19, 19, 'judge', 0.6, '学生在解几何题时能够举一反三，把刚学的一种证明方法灵活用于多道变式题。这说明其产生了正迁移。', '[["A","正确"],["B","错误"]]', '["A"]', '正迁移是指先前学习对后继学习产生积极的促进作用。学生把习得的证明方法成功运用到同类变式题中，促进了新问题的解决，属于正迁移。', '["B"]', 0, 0.0, '2026-11-09 17:21:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (200, 4, 20, 20, 'judge', 0.6, '某市教育局明确要求学校不得把考试成绩排名作为评价学生的唯一依据。这一要求体现了多元化评价的理念。', '[["A","正确"],["B","错误"]]', '["A"]', '《深化新时代教育评价改革总体方案》要求创新过程性评价方法、完善综合素质评价体系，改变以分数给学生贴标签的做法。不以成绩排名为唯一依据，正体现了评价内容、方式和主体的多元化。', '["B"]', 0, 0.0, '2026-11-09 17:21:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (201, 4, 21, 21, 'judge', 0.6, '学生在课堂上提出与教材不同的看法，任课教师为维护教材权威和课堂秩序，当即予以否定并提醒其他学生不要效仿。该做法有利于保护学生的好奇心和求知欲。', '[["A","正确"],["B","错误"]]', '["B"]', '好奇心和求知欲是创造性思维的起点。教师对学生的异见简单否定、当众压制，会造成紧张的心理氛围，使学生不敢质疑，损害其探究兴趣和批判精神；正确做法是肯定独立思考并引导辨析求证。', '["B"]', 1, 0.6, '2026-11-09 17:21:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (202, 4, 22, 22, 'judge', 0.6, '小丽学习时总等老师给出标准答案，不习惯主动质疑和探究。从建构主义学习理论看，她需要转变为知识的主动建构者。', '[["A","正确"],["B","错误"]]', '["A"]', '建构主义认为，学习不是知识由教师向学生的单向传递，而是学生在原有经验基础上主动建构意义的过程。被动等待答案难以实现深层理解，小丽应主动探究、合作建构。', '["B"]', 0, 0.0, '2026-11-09 17:21:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (203, 4, 23, 23, 'judge', 0.6, '学生每次作业没达到教师要求，都要被点名批评并罚重做。学生为了不被批评，不得不认真完成作业。从强化理论看，教师的批评在这里起到了正强化的作用，这种说法是正确的。', '[["A","正确"],["B","错误"]]', '["B"]', '正强化是行为发生后呈现愉快刺激以提高行为概率。批评是学生力图回避的厌恶刺激，学生为逃避或避免批评而认真完成作业，属于负强化（撤销厌恶刺激的预期）或惩罚情境，并非正强化。', '["B"]', 1, 0.6, '2026-11-09 17:21:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (204, 4, 24, 24, 'judge', 0.6, '某小学把一名受警告处分学生的姓名、班级和处分决定在全校大会上宣读，并张贴于公告栏。学校认为这是正当的警示教育，不构成侵权。', '[["A","正确"],["B","错误"]]', '["B"]', '《中华人民共和国未成年人保护法》要求保护未成年人的人格尊严和隐私权、个人信息。对违纪学生的处分应在必要范围内告知本人及其监护人，公开宣读、张贴处分决定带有示众羞辱性质，会使学生的违纪信息被不当扩散，侵犯其人格尊严和隐私权。', '["B"]', 1, 0.6, '2026-11-09 17:21:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (205, 4, 25, 25, 'judge', 0.6, '教师节来临，某班家长委员会凑钱为班主任购买了一条名牌项链，班主任认为家长的好意不便推辞，便收下了。该做法符合教师职业行为准则。', '[["A","正确"],["B","错误"]]', '["B"]', '《新时代中小学教师职业行为十项准则》和《中小学教师违反职业道德行为处理办法》明确要求教师坚守廉洁自律，不得收受学生及家长赠送的可能影响公正执行公务的礼品礼金。项链价值较高，班主任应当婉言谢绝。', '["B"]', 1, 0.6, '2026-11-09 17:21:13');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (206, 4, 26, 26, 'judge', 0.6, '某初中教师每节课都以系统讲授为主，把知识完整讲透并要求学生认真听讲记笔记，几乎不安排自主学习和合作探究。与问题导向、自主探究的教学相比，这种全程系统讲授更能突出学生的主体地位。', '[["A","正确"],["B","错误"]]', '["B"]', '系统讲授以教师活动为主，学生主要是被动接受；问题导向教学通过自主学习、合作探究让学生主动建构知识，更能突出学生的主体地位。题中全程讲授、缺少学生主动参与，反而是教师主体而非学生主体。', '["B"]', 1, 0.6, '2026-11-09 17:21:13');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (207, 4, 27, 27, 'judge', 0.6, '考试失利后，小强认为“题太难、运气差”，自己怎么努力也没用，于是愈发消沉。他的这种反应符合习得性无助的表现。', '[["A","正确"],["B","错误"]]', '["A"]', '习得性无助是指个体反复经历失败后，形成无论怎样努力都无法控制结果的信念，进而产生逃避、放弃等反应。小强把失败外归因并断定努力无用、情绪消沉，正是习得性无助的典型表现。', '["B"]', 0, 0.0, '2026-11-09 17:21:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (208, 4, 28, 28, 'judge', 0.6, '学生把连续几次考试失利都归因于“自己天生脑子笨”，并认为再努力也改变不了。这种归因会增强其后续学习的坚持性。', '[["A","正确"],["B","错误"]]', '["B"]', '“天生脑子笨”属于内部、稳定、不可控的能力归因。依据韦纳归因理论，把失败稳定地归于能力不足，会降低自我效能感和成功预期，导致放弃努力，而非增强坚持性。教师应引导其归因于努力、方法等可控因素。', '["B"]', 1, 0.6, '2026-11-09 17:21:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (209, 4, 29, 29, 'judge', 0.6, '化学实验中学生如实记录了一个与预期不符的现象，教师以“不在考试范围内”为由要求其删除记录。该做法有利于培养学生的科学精神。', '[["A","正确"],["B","错误"]]', '["B"]', '实事求是、尊重证据是科学精神的核心。教师要求学生删除真实的意外记录，违背了严谨求实的治学态度，也错失了引导学生分析异常现象的教育契机。', '["B"]', 1, 0.6, '2026-11-09 17:21:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (210, 4, 30, 30, 'judge', 0.6, '2024年8月26日，中共中央、国务院印发《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。该文件将教育家精神凝练为“心有大我、至诚报国”等十个方面，其中“勤学笃行、求是创新的躬耕态度”要求教师严谨笃学、求真创造。', '[["A","正确"],["B","错误"]]', '["A"]', '该文件确由中共中央、国务院于2024年8月26日印发，全称为《关于弘扬教育家精神加强新时代高素质专业化教师队伍建设的意见》。教育家精神包括心有大我至诚报国、言为士则行为世范、启智润心因材施教、勤学笃行求是创新、乐教爱生甘于奉献、胸怀天下以文化人等十个方面，题干时间、文件名和对躬耕态度的表述均正确。', '["B"]', 0, 0.0, '2026-11-09 17:21:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (211, 4, 31, 31, 'single', 1.0, '三年级数学老师教学面积时，先让学生用手掌量课桌面，再用方格纸量，最后引出面积公式。这一教学过程体现了（　）', '[["A","从理论到实践的顺序原则"],["B","从一般到个别的演绎过程"],["C","从具体到抽象的认识规律"],["D","从抽象到具体的认识规律"]]', '["C"]', '手掌测量是具体操作，方格纸是半抽象的表象工具，面积公式是抽象概括。教学沿着动作感知—表象—概念的路径推进，体现了从具体到抽象的认识规律。A项“顺序原则”强调由浅入深、由易到难的组织顺序，与题意不完全吻合；B项方向相反（从一般到个别属于演绎，而题干是从个别到一般）；D项方向也相反。', '["B"]', 0, 0.0, '2026-11-09 17:21:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (212, 4, 32, 32, 'single', 1.0, '小明学习英语语法时，常把英语和汉语的句式放在一起比较，找出二者的异同。他运用的学习策略主要是（　）', '[["A","复述策略"],["B","精细加工策略中的比较法"],["C","组织策略中的归类法"],["D","元认知策略中的监控策略"]]', '["B"]', '比较法是精细加工策略的重要方法，通过对易混知识逐项对照异同，加深理解和辨别。将中英语法进行对比正是比较法的运用。复述侧重重复巩固，组织侧重归类建网，元认知侧重对学习过程的计划与监控，均不贴切。', '["B"]', 1, 1.0, '2026-11-09 17:21:16');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (213, 4, 33, 33, 'single', 1.0, '物理兴趣小组探究单摆周期时，几名中学生先提出“周期可能与摆长、摆锤质量、释放角度都有关”的猜想，再固定其他条件、每次只改变一个变量，分别设计实验加以检验。依据皮亚杰的认知发展阶段理论，这种系统的假设—演绎推理表明他们处于（　）', '[["A","感知运动阶段"],["B","具体运算阶段"],["C","前运算阶段"],["D","形式运算阶段"]]', '["D"]', '皮亚杰通过钟摆实验等研究发现，形式运算阶段（约11岁以后）的个体能够针对问题提出多种假设，并运用控制变量、假设—演绎的方法系统验证。前三个阶段（感知运动、前运算、具体运算）的儿童尚不能脱离具体情境进行严密的假设检验。', '["B"]', 0, 0.0, '2026-11-09 17:21:16');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (214, 4, 34, 34, 'single', 1.0, '物理教师在讲浮力前先问：“为什么铁块沉入水中，而钢铁造的轮船却能浮在水面？”以激发学生的求知欲。该导入方式属于（　）', '[["A","直接导入"],["B","故事导入"],["C","复习导入"],["D","问题导入"]]', '["D"]', '教师围绕教学内容设置悬念性问题，使学生产生认知冲突和探究愿望，属于问题导入（设疑导入）。复习导入依托旧知，故事导入借助故事情境，直接导入则开门见山点明课题，均与题干不同。', '["B"]', 0, 0.0, '2026-11-09 17:21:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (215, 4, 35, 35, 'single', 1.0, '某生因考试取得进步，被老师在班上当众表扬，此后他学习更加努力。按班杜拉的强化分类，该生受到的强化属于（　）', '[["A","自我强化"],["B","替代强化"],["C","负强化"],["D","直接强化"]]', '["D"]', '直接强化是指学习者本人的行为因直接得到外部强化而增强。该生自己的进步行为直接受到教师表扬，属于直接强化。替代强化是观察他人受奖惩而受影响，自我强化是依据自己的标准自我奖惩，负强化是撤销厌恶刺激以增加行为。', '["B"]', 0, 0.0, '2026-11-09 17:21:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (216, 4, 36, 36, 'single', 1.0, '某市明确要求义务教育阶段学校招生不得采取笔试、面试或任何变相形式的知识性考查。这一要求主要在于维护（　）', '[["A","学校分层教学的自主权"],["B","民办学校优先招生的权利"],["C","适龄儿童免试就近入学的权利"],["D","学校依法自主招生的权利"]]', '["C"]', '《中华人民共和国义务教育法》第十二条规定，适龄儿童、少年免试入学，地方各级人民政府应当保障其在户籍所在地学校就近入学。禁止入学考试和面试，目的在于维护免试就近入学原则和教育公平。B、D项与免试入学要求无关，民办学校招生同样纳入免试入学规范管理。', '["B"]', 0, 0.0, '2026-11-09 17:21:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (217, 4, 37, 37, 'single', 1.0, '学生在化学方程式配平中反复出错。下列做法中，最有利于从根本上解决问题的是（　）', '[["A","先引导学生理解质量守恒定律再学配平"],["B","让学生熟记配平口诀和典型例题"],["C","降低要求，暂不要求掌握配平"],["D","增加抄写和重复练习的数量"]]', '["A"]', '配平的依据是质量守恒定律。学生理解反应前后原子种类、数目不变的本质后，才能在新情境中灵活配平，这属于有意义学习，能从根本上减少错误。机械重复和背诵口诀只形成暂时的技能，回避难点则不能解决问题。', '["B"]', 0, 0.0, '2026-11-09 17:21:18');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (218, 4, 38, 38, 'single', 1.0, '初二学生小杰总认为同学和老师都在注意自己的发型和穿着，因而在集体活动中格外紧张、不敢表现。这种“感到自己是他人关注中心”的心理属于（　）', '[["A","客体永久性"],["B","假想的观众"],["C","守恒观念"],["D","思维的不可逆性"]]', '["B"]', '青少年自我中心思维的典型表现之一是“假想的观众”，即总觉得自己处在他人关注的焦点，因而过分在意自己的外表和行为。不可逆性、缺乏守恒是前运算阶段儿童的特点，客体永久性形成于感知运动阶段，均与题干不符。', '["B"]', 1, 1.0, '2026-11-09 17:21:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (219, 4, 39, 39, 'single', 1.0, '学生解题时习惯于沿用同一种思路，想不到其他途径，思维明显缺乏变通。教师应着重培养其（　）', '[["A","观察力的敏锐性"],["B","思维的流畅性"],["C","注意力的稳定性"],["D","思维的变通性（灵活性）"]]', '["D"]', '发散思维具有流畅性、变通性和独创性三个特征。只能用一种方法、不能多角度转换思路，反映变通性不足，应通过一题多解、条件变式等训练加以培养。流畅性强调单位时间内观念的数量，注意、观察品质与题干问题不对应。', '["B"]', 0, 0.0, '2026-11-09 17:21:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (220, 4, 40, 40, 'single', 1.0, '学校要求教师每学期至少精读一本教育专著并撰写读书笔记。这一要求直接体现的师德规范是（　）', '[["A","终身学习"],["B","为人师表"],["C","爱岗敬业"],["D","关爱学生"]]', '["A"]', '《中小学教师职业道德规范》中的“终身学习”要求教师崇尚科学精神、树立终身学习理念、拓宽知识视野、更新知识结构。持续研读专业著作、撰写笔记是教师专业自我更新的典型表现。', '["B"]', 0, 0.0, '2026-11-09 17:21:20');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (221, 4, 41, 41, 'single', 1.0, '数学课上，老师讲“果实”时既举苹果、花生等可食用的例子，也举棉籽、橡子等不可直接食用的例子，并对比“果实与根、茎”。这些变化正例与反例的运用主要是为了促进学生（　）', '[["A","产生学习迁移"],["B","对概念的变式掌握"],["C","形成操作技能"],["D","机械识记定义"]]', '["B"]', '变式是指变换概念的非本质特征、保持本质特征不变的各类正例，配合反例比较，可帮助学生排除无关特征、准确概括概念的本质属性。机械识记不强调例证比较；操作技能、学习迁移与题干例证设计的直接目的不符。', '["B"]', 1, 1.0, '2026-11-09 17:21:20');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (222, 4, 42, 42, 'single', 1.0, '学生在学习新概念时，总是主动寻找它与已有知识之间的内在联系。按奥苏贝尔的理论，这种学习属于（　）', '[["A","有意义学习"],["B","机械学习"],["C","发现学习"],["D","信号学习"]]', '["A"]', '有意义学习的实质是符号所代表的新知识与学习者认知结构中已有的适当观念建立非人为的、实质性的联系。学生主动把新旧知识联系起来，正是有意义学习的表现。机械学习缺乏这种联系，发现学习强调知识获得的方式，信号学习属于较低级的学习层次。', '["B"]', 0, 0.0, '2026-11-09 17:21:21');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (223, 4, 43, 43, 'single', 1.0, '学生小雯学习十分刻苦，但总把考试成绩归结为题目难易、临场运气等自己无法左右的因素。依据韦纳的成败归因理论，这些因素主要属于（　）', '[["A","外部、不可控的因素"],["B","内部、可控的因素"],["C","内部、稳定的因素"],["D","内部、不稳定的因素"]]', '["A"]', '韦纳把归因分为内外源、稳定性、可控性三个维度。任务难度属外部、稳定、不可控，运气属外部、不稳定、不可控，二者共同点是外部且不可控。努力才是内部、不稳定、可控因素，能力是内部、稳定、不可控因素。', '["B"]', 0, 0.0, '2026-11-09 17:21:21');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (224, 4, 44, 44, 'single', 1.0, '课间，两名七年级学生聊起为什么而学。泽宇说：“我学几何完全是因为图形证明太有意思了，越想越入迷，搞不懂就睡不着。”他既没想着拿名次，也不为换取表扬。按照奥苏贝尔对学校情境中成就动机成分的划分，泽宇身上占主导的是（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","生理需要驱动"],["D","自我提高内驱力"]]', '["B"]', '认知内驱力是一种指向学习任务本身、以求知和解决问题为满足的内部动机，在有意义学习中是最重要、最稳定的动机。泽宇因几何本身的趣味而主动钻研、不计名次表扬，正属认知内驱力。自我提高内驱力指向由成就带来的地位与自尊，附属内驱力指向获得长者和同伴赞许。', '["B"]', 1, 1.0, '2026-11-09 17:21:22');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (225, 4, 45, 45, 'single', 1.0, '教师先呈现一个真实问题，让学生带着问题研读教材、查找资料，再在讨论中形成认识。这种教学的主要理论基础是（　）', '[["A","认知—接受学习理论"],["B","建构主义学习理论"],["C","行为主义学习理论"],["D","人本主义学习理论"]]', '["B"]', '建构主义强调学习的情境性和主动建构性，主张通过真实问题情境中的探究、协作与会话，由学生自主建构知识意义。基于问题、借助资料和讨论的教学与此高度一致。', '["B"]', 1, 1.0, '2026-11-09 17:21:22');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (226, 4, 46, 46, 'single', 1.0, '某小学将消防安全、应急疏散演练纳入学校安全管理制度，规定每学期至少组织一次。学校开展安全教育和应急演练的直接部门规章依据是（　）', '[["A","《中华人民共和国民办教育促进法》"],["B","《中华人民共和国高等教育法》"],["C","《中小学幼儿园安全管理办法》"],["D","《中华人民共和国学位条例》"]]', '["C"]', '《中小学幼儿园安全管理办法》（教育部等部门发布）明确规定，学校应当对学生开展消防安全、交通安全等安全教育，制定应急预案并定期组织应急演练，是中小学开展疏散演练最直接的规范依据。A、B、D项均不针对中小学日常安全管理与演练。', '["B"]', 0, 0.0, '2026-11-09 17:21:22');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (227, 4, 47, 47, 'single', 1.0, '每逢数学考试前，某生就出现头痛、肚子痛、心慌出汗等症状，进入考场后注意力难以集中，考试结束症状随即缓解。该生最可能的问题是（　）', '[["A","躯体器质性疾病"],["B","一般性厌学情绪"],["C","考试焦虑"],["D","注意缺陷多动障碍"]]', '["C"]', '考试焦虑是在一定应试情境下，受个体认知评价、人格倾向等影响而产生的以担忧为特征、伴有生理唤醒的心理状态，躯体化症状随考试情境出现和消退是其典型表现。器质性疾病不会随考试结束而缓解，注意缺陷障碍具有跨情境的持续性。', '["B"]', 0, 0.0, '2026-11-09 17:21:23');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (228, 4, 48, 48, 'single', 1.0, '学生苦练硬笔书法一段时间后，最初进步明显，但随后连续几周成绩似乎停滞不前，再练也难有提高，甚至出现烦躁情绪。这种练习中期出现的成绩暂时停顿现象，在心理学上称为（　）', '[["A","功能固着现象"],["B","高原现象"],["C","迁移现象"],["D","遗忘现象"]]', '["B"]', '在操作技能形成过程中，练习中期常出现成绩提升暂时停顿、甚至略有下降的现象，称为“高原现象”，其成因包括旧动作结构需要改造、练习方法不当、兴趣和动机下降等。迁移是学习之间的相互影响，遗忘是记忆内容的消退，功能固着属于问题解决中的思维障碍。', '["B"]', 1, 1.0, '2026-11-09 17:21:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (229, 4, 49, 49, 'single', 1.0, '期末复习时，小周把英语单词分散在两周内每天记忆20分钟，而不是考前一天连续背4小时。这种安排主要利用了（　）', '[["A","集中复习优于分散复习的规律"],["B","倒摄抑制的作用"],["C","艾宾浩斯遗忘先快后慢的规律"],["D","高原现象的规律"]]', '["C"]', '艾宾浩斯遗忘曲线表明遗忘进程先快后慢、先多后少，因此应及时复习、合理分散复习时间，在大规模遗忘发生前加以巩固。一般情况下分散复习效果优于集中复习；倒摄抑制指后学材料对先学材料的干扰；高原现象是技能练习中期出现的暂时停顿。', '["B"]', 0, 0.0, '2026-11-09 17:21:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (230, 4, 50, 50, 'single', 1.0, '某中学开设生涯规划课程，引导学生认识自己的兴趣、能力与价值观，了解职业世界并规划发展方向。该课程在德育内容上主要属于（　）', '[["A","人生观与生涯发展指导"],["B","美育中的审美教育"],["C","劳动技术教育中的技能训练"],["D","智育中的思维训练"]]', '["A"]', '德育包括理想信念、社会主义核心价值观、生涯规划等内容。生涯规划教育帮助学生认识自我、明确人生目标，属于德育中的人生观、价值观教育和人生（生涯）发展指导。', '["B"]', 0, 0.0, '2026-11-09 17:21:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (231, 4, 51, 51, 'single', 1.0, '校篮球赛中，一名学生在正常对抗中落地受伤。赛前学校进行了专项安全教育、检查了场地并配备了校医。依法学校（　）', '[["A","无论有无过错均应补偿"],["B","已尽到教育管理职责，不承担侵权责任"],["C","应与对方学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["B"]', '依据《民法典》第一千二百条，限制民事行为能力人在学校学习、生活期间受到人身损害，学校未尽到教育、管理职责的才承担责任。学校已开展安全教育、检查场地、配备医护人员，对正常竞技中的意外受伤没有过错，故不承担侵权责任。', '["B"]', 1, 1.0, '2026-11-09 17:21:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (232, 4, 52, 52, 'single', 1.0, '某教师因几名学生未完成作业，罚他们到操场上跑十圈，致使一名学生体力不支晕倒。该教师的行为属于（　）', '[["A","体罚，侵犯学生身体权和健康权"],["B","合法的教育惩戒"],["C","一般性的课堂管理措施"],["D","正常的体育锻炼"]]', '["A"]', '《中小学教育惩戒规则（试行）》允许的惩戒不包括超越学生身心承受能力的体力惩罚。罚跑十圈直接造成身体痛苦和伤害，属于体罚而非法惩戒，侵犯了学生的身体权、健康权。', '["B"]', 0, 0.0, '2026-11-09 17:21:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (233, 4, 53, 53, 'single', 1.0, '市场监管和教育行政部门联合检查时，发现某校食堂操作间卫生不达标、留样不规范，遂责令其限期改正。该执法行为（　）', '[["A","只能在发生食物中毒后实施"],["B","于法有据，是履行食品安全监管职责"],["C","应完全交由学校家委会处理"],["D","属于越权干预学校自主经营"]]', '["B"]', '依据《中华人民共和国食品安全法》和《学校食品安全与营养健康管理规定》，学校食堂实行预防为主、风险管理原则，教育、市场监管部门依法负有日常监督检查职责。事前责令限期整改正是依法履职。', '["B"]', 1, 1.0, '2026-11-09 17:21:26');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (234, 4, 54, 54, 'single', 1.0, '自习课上，教师发现一名学生正用手机玩游戏。最恰当的处理方式是（　）', '[["A","暂时代为保管，课后归还并进行教育引导"],["B","当着全班的面摔毁手机以示警戒"],["C","立即将学生逐出教室反思"],["D","当场将手机没收并永久不予归还"]]', '["A"]', '依据中小学学生手机管理相关规定，学生违规带入或使用手机的，学校可统一保管并及时告知家长。教师暂时代管、课后归还并辅以教育，既维护课堂秩序，又尊重学生财产权和人格尊严。没收不还、逐出教室、损毁财物均缺乏法律依据并可能侵权。', '["B"]', 0, 0.0, '2026-11-09 17:21:26');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (235, 4, 55, 55, 'single', 1.0, '中共中央、国务院《深化新时代教育评价改革总体方案》要求改革学生评价。下列做法中，不符合该方案方向的是（　）', '[["A","坚决改变以分数给学生贴标签的做法"],["B","健全学生综合素质评价体系"],["C","完善德智体美劳过程性评价"],["D","把升学率作为评价学校办学质量的唯一指标"]]', '["D"]', '《深化新时代教育评价改革总体方案》（2020年印发）提出坚决纠正片面追求升学率倾向，不得把升学率作为评价学校、教师和学生的唯一依据，强调过程性评价和综合素质评价。D项正是方案要破除的做法。', '["B"]', 0, 0.0, '2026-11-09 17:21:27');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (236, 4, 56, 56, 'single', 1.0, '创造思维训练课上，教师给出钳子、绳子等材料，要求学生想办法同时够到从天花板垂下的两根相距较远、无法一手同时抓住的绳子。多数学生只把钳子看作夹持工具，想不到可把它系在绳端当作摆锤，晃动绳子后趁机抓住。这一现象主要说明问题解决受到（　）', '[["A","功能固着的影响"],["B","学习动机的影响"],["C","原型启发的影响"],["D","正迁移的影响"]]', '["A"]', '功能固着是指个体只看到事物惯常的功能而看不到它其他可能用途的现象。学生只认定钳子是夹持工具，想不到它可作摆锤，这是梅尔双绳实验所揭示的功能固着。原型启发是从其他事物中找到解决问题的途径，正迁移和学习动机与该现象无关。', '["B"]', 0, 0.0, '2026-11-09 17:21:27');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (237, 4, 57, 57, 'single', 1.0, '班上的小亮打碎了教室里1只杯子后主动认错；小杰为偷吃糖果打碎了10只杯子却谎称不是自己干的。问“哪个孩子更不好、应受更重惩罚”时，小学三年级学生大多认为小杰更坏、因为打碎了10只杯子。依据皮亚杰道德发展阶段理论，这些学生的判断主要处于（　）', '[["A","他律道德阶段"],["B","自律道德阶段"],["C","公正道德阶段"],["D","前道德阶段"]]', '["A"]', '皮亚杰通过对偶故事研究发现，他律道德阶段（约5—8岁）的儿童根据行为的客观后果数量判断责任，而不考虑行为动机；自律阶段儿童才会结合主观动机判断。只看打碎杯子数量、忽视说谎与偷拿动机，属于他律道德阶段的特点。', '["B"]', 0, 0.0, '2026-11-09 17:21:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (238, 4, 58, 58, 'single', 1.0, '某班在校内劳动实践基地上劳动课，教师事先讲解了工具的安全使用方法并示范操作，一名学生仍未按要求握持工具，不慎被划伤。事后学校及时送医并通知家长。依法学校（　）', '[["A","应承担全部赔偿责任"],["B","已尽到教育、管理和保护职责，不承担侵权责任"],["C","无论有无过错都必须给予赔偿"],["D","应与任课教师平均分担损失"]]', '["B"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任。教师已进行安全教育和操作示范、学校事后及时救助，对学生违反操作规程造成的自伤没有过错，故不承担侵权责任。', '["B"]', 1, 1.0, '2026-11-09 17:21:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (239, 4, 59, 59, 'single', 1.0, '课堂上，数学老师要求学生一边听讲一边在草稿本上记录关键步骤，多数学生能较好地同时完成两项任务。这主要体现了注意的（　）', '[["A","注意的稳定性"],["B","注意的转移"],["C","注意的分配"],["D","注意的范围"]]', '["C"]', '注意的分配是指个体在同一时间内把注意指向两种或两种以上的对象或活动。边听讲边记录要求学生在听和写之间合理分配注意。注意范围强调同一瞬间把握对象的数量，稳定性强调持续时间，转移强调根据任务主动把注意从一个对象转向另一个对象。', '["B"]', 0, 0.0, '2026-11-09 17:21:29');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (240, 4, 60, 60, 'single', 1.0, '一位中学教师持续跟踪本学科研究进展，把经过筛选的最新科研成果转化为教学案例，帮助学生了解学科前沿。这主要体现了（　）', '[["A","教师把科研任务转嫁给学生"],["B","以研究取代常规课堂教学"],["C","教学完全脱离教材体系"],["D","教学内容与学术研究相结合"]]', '["D"]', '教师把学科前沿成果筛选、转化为适切的教学素材，体现了科研与教学相长，有利于拓宽学生视野、培养科学素养。A项把科研成果转化曲解为“转嫁任务”，与教师主动筛选转化的行为不符；B项将科研促教绝对化为“取代课堂教学”，C项则完全否定教材体系，均与题干事实相悖。', '["B"]', 0, 0.0, '2026-11-09 17:21:29');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (241, 4, 61, 61, 'single', 1.0, '复习化学时，某生把零散的物质按“单质—化合物—混合物”的类别整理成表格，再把各类物质的性质、制法和用途归并到一起记忆。该学习策略主要属于（　）', '[["A","元认知策略中的计划策略"],["B","复述策略"],["C","精细加工策略中的记忆术"],["D","组织策略中的归类法"]]', '["D"]', '组织策略是对学习材料进行加工，按照其内在联系加以归类、整理，形成清晰认知结构的策略。该生按物质分类建表、归并性质与用途，正是归类法的典型运用。复述侧重重复巩固，记忆术侧重人为联想以增强保持，计划策略侧重对学习活动的预先安排。', '["B"]', 0, 0.0, '2026-11-09 17:21:30');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (242, 4, 62, 62, 'single', 1.0, '部分学生习惯于机械背诵，对知识不求甚解，遇到变式题就出错。教师应着重引导其（　）', '[["A","加大机械重复的遍数"],["B","放弃记忆，只做难题"],["C","在理解的基础上进行有意义学习"],["D","延长每次记忆的时间"]]', '["C"]', '机械学习获得的知识难以迁移，变式题出错的根源是没有理解知识的实质和内在联系。教师应帮助学生把新知识纳入已有认知结构，开展有意义学习，并辅以变式练习。', '["B"]', 0, 0.0, '2026-11-09 17:21:30');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (243, 4, 63, 63, 'single', 1.0, '升入初中后，小芸在家长帮助下制定学习计划时，会主动预估某项任务大约需要多长时间，并据此安排先后顺序。这种对认知活动的预先规划属于（　）', '[["A","资源管理策略中的时间管理"],["B","元认知计划策略"],["C","复述策略"],["D","精加工策略"]]', '["B"]', '元认知策略包括计划、监控和调节策略。在认知活动开始前设置目标、预估任务难度与时间、安排学习步骤，属于元认知计划策略。复述策略侧重重复保持信息，精加工策略侧重为信息增加意义，时间管理策略侧重对学习时间资源的统筹，均不直接指向对认知过程的预先规划。', '["B"]', 1, 1.0, '2026-11-09 17:21:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (244, 4, 64, 64, 'single', 1.0, '某校在防治校园欺凌中建立早期预警机制。下列做法中，不属于早期预警措施的是（　）', '[["A","定期开展心理健康普查并建立重点关注台账"],["B","仅在发生严重伤害事件后再介入处理"],["C","畅通学生、家长欺凌线索报告渠道"],["D","通过日常观察和同伴关系调查识别风险信号"]]', '["B"]', '早期预警强调关口前移，通过心理筛查、风险排查、线索报告和主题教育等主动发现隐患。事后处理是末端应对而非预防预警。', '["B"]', 1, 1.0, '2026-11-09 17:21:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (245, 4, 65, 65, 'single', 1.0, '一位教师在教学后记中写道：“今天进度偏快，部分学生来不及思考，下次应放慢节奏，多留讨论时间。”这主要反映了教师的（　）', '[["A","关注学情并自觉改进教学的反思意识"],["B","只关注教学进度完成情况"],["C","对学生差异的无条件迁就"],["D","以个人经验否定教学计划"]]', '["A"]', '教师依据课堂上观察到的学习状态审视教学，并提出针对性的调整方案，属于教学反思，体现了以学定教和持续改进的专业意识。', '["B"]', 0, 0.0, '2026-11-09 17:21:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (246, 4, 66, 66, 'single', 1.0, '一名学生因家境困难而自卑，很少与同学交往。班主任一方面关心鼓励他、协助其申请助学金，另一方面引导同学在小组活动中主动接纳他。该做法体现了（　）', '[["A","以经济资助代替思想教育"],["B","关爱学生与集体教育相结合"],["C","只依靠班集体进行教育"],["D","把学生的家庭情况公开通报"]]', '["B"]', '教师个人的关爱与帮扶解决了学生的实际困难和心理压力，组织同伴互助则发挥了集体的教育力量，两者结合帮助学生走出自卑，符合关爱学生与集体教育相结合的要求。', '["B"]', 1, 1.0, '2026-11-09 17:21:32');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (247, 4, 67, 67, 'single', 1.0, '一名学生因沉迷手机游戏导致成绩明显下降、上课精神不振。班主任较恰当的做法是（　）', '[["A","不经学生同意直接查阅其手机全部内容"],["B","把问题完全推给家长，学校不再过问"],["C","了解原因，引导其认识危害并共同制定合理用机计划"],["D","当众严厉训斥并永久禁止其接触手机"]]', '["C"]', '手机沉迷的成因复杂，简单禁止或放任都难以奏效。教师应在尊重学生的基础上了解需求、讲清危害，与学生、家长协商制定可执行的用机规则，并以丰富的活动转移注意。', '["B"]', 0, 0.0, '2026-11-09 17:21:32');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (248, 4, 68, 68, 'single', 1.0, '作文基础薄弱的学生，在老师系统指导和同伴互助下，能独立完成此前无法完成的800字议论文；脱离帮助后，他仍只能写约500字。维果斯基把“独立解决问题的实际水平”与“成人指导下可达到的水平”之间的差距称为（　）', '[["A","关键期"],["B","学习准备状态"],["C","最近发展区"],["D","认知风格差异"]]', '["C"]', '维果斯基提出的最近发展区，是指儿童独立解决问题所确定的现有发展水平，与在成人指导或与有能力同伴合作下解决问题所达到的潜在发展水平之间的差距，教学应着眼于“跳一跳、摘桃子”。关键期强调特定能力发展的最佳时机，认知风格、学习准备均不描述这一差距。', '["B"]', 0, 0.0, '2026-11-09 17:21:33');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (249, 4, 69, 69, 'single', 1.0, '课堂上一名学生对教材结论提出有依据的质疑。教师最恰当的回应是（　）', '[["A","暂时回避，课后单独批评"],["B","以维护教材权威为由不予讨论"],["C","提醒学生只需记住考试结论"],["D","肯定质疑精神，组织学生辨析求证"]]', '["D"]', '面对有价值的质疑，教师应发扬教学民主，把质疑转化为教学资源，引导学生寻找证据、辨析论证，既解决问题又培养批判精神。', '["B"]', 0, 0.0, '2026-11-09 17:21:34');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (250, 4, 70, 70, 'single', 1.0, '某市推行“阳光招生”，要求招生计划、程序、结果全程公开，接受社会监督。这一做法主要有利于（　）', '[["A","维护教育公平，保障群众的知情权和监督权"],["B","扩大学校的招生自由裁量权"],["C","弱化教育行政部门的监管责任"],["D","以社会评价替代教育评价"]]', '["A"]', '招生信息公开把入学机会置于社会监督之下，有助于遏制“掐尖招生”“条子生”等违规行为，保障入学机会公平和群众的知情权、监督权。', '["B"]', 0, 0.0, '2026-11-09 17:21:34');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (251, 4, 71, 71, 'single', 1.0, '学生把ambulance（救护车）谐音联想为“俺不能死”来记忆单词。这种记忆方法属于（　）', '[["A","复述策略"],["B","精细加工策略中的谐音联想法"],["C","组织策略中的纲要法"],["D","元认知策略中的调节策略"]]', '["B"]', '谐音联想法是借助读音相似把抽象、无意义材料转化为有意义表象的精细加工策略。复述、组织、元认知策略的功能与题干方法不符。', '["B"]', 1, 1.0, '2026-11-09 17:21:35');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (252, 4, 72, 72, 'single', 1.0, '学生作文普遍空洞，教师分析后发现主要原因是生活观察和体验不足。下列做法中最有针对性的是（　）', '[["A","以抄写优美句段代替写作训练"],["B","要求学生大量背诵优秀作文模板"],["C","降低字数和立意要求"],["D","组织观察、实践活动，丰富直接经验和写作素材"]]', '["D"]', '写作是对生活经验加工表达的过程。“无米下锅”靠套模板、抄句段无法根治，组织观察与实践活动可充实感性经验，解决素材贫乏的根源问题。', '["B"]', 0, 0.0, '2026-11-09 17:21:35');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (253, 4, 73, 73, 'single', 1.0, '一位教师坚持每周撰写教学反思，系统记录成功经验、问题教训和改进设想，三年后教学水平显著提升。这一专业发展途径主要是（　）', '[["A","脱产学历进修"],["B","单纯依靠专家讲座"],["C","自我反思与行动研究"],["D","同事之间的随机闲谈"]]', '["C"]', '波斯纳提出“教师成长 = 经验 + 反思”。持续、系统地反思教学并据以改进，是教师立足岗位的自我教育和行动研究，是专业发展最直接的途径之一。', '["B"]', 0, 0.0, '2026-11-09 17:21:36');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (254, 4, 74, 74, 'single', 1.0, '春游中，一名学生在自由活动时违反事先反复强调的安全要求，与同学追逐打闹致自己摔伤。学校事前勘察了路线、进行了安全教育并安排足够教师跟班。依法学校（　）', '[["A","已尽到教育管理职责，不承担侵权责任"],["B","只要发生在校外活动中就须担责"],["C","应与受伤学生平均分担损失"],["D","应承担全部赔偿责任"]]', '["A"]', '依据《学生伤害事故处理办法》和《民法典》相关规定，学校责任以过错为前提。学校履行了安全教育、路线勘查和人员配备义务，损害由学生违反纪律的自险行为造成，学校没有过错，故不承担侵权责任。B项将校外活动一律归责，C项无法律依据要求平均分摊，D项全额赔偿更无事实与法律基础。', '["B"]', 0, 0.0, '2026-11-09 17:21:36');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (255, 4, 75, 75, 'single', 1.0, '学生计算能力正常，却常常不会做应用题，主要问题在于读不懂题意、抓不住数量关系。教师应优先培养其（　）', '[["A","阅读理解与关键信息提取能力"],["B","机械背诵公式的能力"],["C","几何作图能力"],["D","计算的速度和准确率"]]', '["A"]', '应用题解题的前提是理解文字情境、识别已知条件与问题、抽象出数量关系。困难出在题意理解环节，就应通过说题、画示意图、圈画关键词等方式提高阅读理解和信息提取能力。', '["B"]', 0, 0.0, '2026-11-09 17:21:36');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (256, 4, 76, 76, 'single', 1.0, '教师注意发现每名学生身上的闪光点，及时给予具体的肯定和鼓励，学生的自信心和完成任务的坚持性明显增强。这种做法主要是通过提升（　）发挥作用的。', '[["A","流体智力水平"],["B","学习兴趣的广度"],["C","认知风格的灵活性"],["D","自我效能感"]]', '["D"]', '自我效能感是个体对自己能否成功完成某一任务的信念，成败经验和他人的积极评价是其重要来源。具体、真诚的肯定能帮助学生积累成功体验，提高自我效能感。', '["B"]', 0, 0.0, '2026-11-09 17:21:37');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (257, 4, 77, 77, 'single', 1.0, '某校把师德师风考核结果作为教师年度考核、职称评聘和评优奖励的首要标准，实行师德失范“一票否决”。这一做法体现了（　）', '[["A","以科研论文数量主导考核"],["B","以学历层次决定教师待遇"],["C","把师德师风作为评价教师第一标准"],["D","以教学成绩为核心的评价导向"]]', '["C"]', '《深化新时代教育评价改革总体方案》和《关于加强和改进新时代师德师风建设的意见》均强调把师德师风作为教师评价的第一标准，落实师德失范“一票否决”。', '["B"]', 0, 0.0, '2026-11-09 17:21:37');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (258, 4, 78, 78, 'single', 1.0, '学英语时，小梅先掌握的汉语拼音发音，常使她把英语字母读成拼音；经过一段时间练习后，新学的英语拼读又偶尔干扰她认读拼音。前一种情形主要属于（　）', '[["A","消退抑制"],["B","前摄抑制"],["C","超限抑制"],["D","倒摄抑制"]]', '["B"]', '先学习的材料对识记和回忆后学习材料的干扰称前摄抑制；后学习的材料对保持先学习材料的干扰称倒摄抑制。汉语拼音先学并干扰英语认读，属于前摄抑制。题干后半句英语反过来干扰拼音才是倒摄抑制，应注意二者的时间顺序。', '["B"]', 1, 1.0, '2026-11-09 17:21:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (259, 4, 79, 79, 'single', 1.0, '一名家庭经济困难学生产生辍学念头，班主任多次家访劝学，协助其申请助学金和社会资助，最终帮助其安心完成学业。该做法主要体现了教师（　）', '[["A","控辍保学、保障适龄儿童接受义务教育的责任"],["B","管理学校财务的行政责任"],["C","开展教育科学研究的责任"],["D","提高班级升学率的教学责任"]]', '["A"]', '《中华人民共和国义务教育法》要求政府、学校、家庭共同做好控辍保学工作，发现学生辍学应及时劝返并帮助解决实际困难。班主任劝学并协助资助，是落实控辍保学责任的体现。', '["B"]', 0, 0.0, '2026-11-09 17:21:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (260, 4, 80, 80, 'single', 1.0, '某市推进教育数字化，支持学校建设智慧课堂，利用大数据开展学情诊断、推送分层学习资源。这一举措的主要价值在于（　）', '[["A","减少学校对教学管理的投入"],["B","用信息技术完全取代教师"],["C","赋能因材施教，提高教学质量"],["D","统一拉平所有学生的学习进度"]]', '["C"]', '《教育强国建设规划纲要（2024—2035年）》强调建设教育数字化体系。智慧课堂和学情数据分析有助于精准把握差异、提供个性化资源，赋能因材施教和质量提升，但技术是辅助手段，不能取代教师。', '["B"]', 0, 0.0, '2026-11-09 17:21:39');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (261, 4, 81, 81, 'multi', 1.6, '某小学深化课程改革，采取了下列措施：开设可供选择的兴趣选修课、推行项目式学习、实行多元过程性评价、鼓励教师合作开发校本课程。这些措施体现的新课程理念有（　）', '[["A","课程结构的选择性"],["B","项目式学习意味着完全取消教师讲授和系统知识学习"],["C","把学生考试成绩作为唯一衡量标准"],["D","评价主体与方式的多元化"],["E","校本课程只能由校外专家开发，教师只负责执行"]]', '["A","D"]', 'A正确：开设可供选择的兴趣选修课体现了课程结构的选择性，照顾学生差异。B错误：项目式学习倡导自主、合作、探究，但并不否定必要的教师讲授和系统知识学习，二者应有机结合。D正确：多元过程性评价体现评价主体和方式多元化。C错误：以分数为唯一标准是新课改要破除的甄别式评价。E错误：教师是课程的建设者和开发者，可以参与校本课程开发。', '["B"]', 0, 0.0, '2026-11-09 17:21:39');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (262, 4, 82, 82, 'multi', 1.6, '学习中，不同问题可以采用不同的学习策略：上课容易走神时需要加强注意的自我监控；记不住零散知识点时需要精加工和及时复习；不会写作文时需要增加观察体验并借鉴范文结构。下列对应正确的有（　）', '[["A","上课走神——运用元认知监控策略，及时调节注意"],["B","记不住知识点——适当运用复述、精加工和组织策略并及时复习"],["C","学习困难只能靠延长学习时间、增加重复遍数解决"],["D","不会写作文——丰富直接经验，运用读写结合的方法"],["E","只要学习策略足够好，就可以忽略学习动机和原有知识基础"]]', '["A","B","D"]', 'A正确：对注意和理解过程的自我觉察、及时调节属于元认知监控策略。B正确：针对零散知识，复述、精细加工、归类组织并依据遗忘规律及时复习是有效方法。D正确：写作困难常源于直接经验不足，应通过观察实践和范文借鉴加以解决。C错误：机械延长时间、简单重复忽视理解和策略运用，效率低下。E错误：策略运用受学习动机、原有知识基础等因素制约，不能脱离这些条件孤立发挥作用。', '["B"]', 0, 0.0, '2026-11-09 17:21:40');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (263, 4, 83, 83, 'multi', 1.6, '某班主任在班级管理中采取了下列做法：实行值日班长轮流制、定期召开班会讨论班级事务、建立班级公约和岗位责任制、对违纪学生只靠罚抄课文处理。其中符合现代班级管理理念的有（　）', '[["A","实行值日班长轮流制，让学生在参与中学会自治"],["B","定期召开班会讨论班级事务，发挥学生的主体作用"],["C","建立班级公约和岗位责任制，实现班级管理的制度化"],["D","对违纪学生一律罚抄课文，以加重学生负担来维持纪律"],["E","班级事务完全由班主任一人决定，学生只需服从执行"]]', '["A","B","C"]', 'A、B、C正确：轮流管理、班会民主议事、公约与岗位责任制体现了学生主体、民主参与和自主管理的现代班级管理理念。D错误：罚抄课文属于变相体罚和机械惩罚，既不符合教育惩戒要求，也不能从根本上引导学生自律。E错误：班主任独断专行会压抑学生的主动性和责任感，不符合班级民主管理方向。', '["B"]', 0, 0.0, '2026-11-09 17:21:41');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (264, 4, 84, 84, 'multi', 1.6, '某校六年级两名学生在课间追逐打闹，教师多次提醒后，一名学生仍将同学推倒致其骨折。关于学校责任的认定，下列说法正确的有（　）', '[["A","学校是否承担责任，以其是否尽到教育、管理职责为判断标准"],["B","学校已进行必要的安全教育和管理且无过错的，不承担侵权责任"],["C","有过错的学生监护人依法承担相应的侵权责任"],["D","伤害发生在校园内，学校无论有无过错都必须承担全部赔偿责任"],["E","学校应当及时救助受伤害学生，并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》第一千二百条和《学生伤害事故处理办法》，限制民事行为能力人在校受到人身损害，学校承担过错责任，以是否尽到教育、管理职责为判断标准（A、B正确）；加害学生一方有过错的，由其监护人依法承担相应责任（C正确）；学校还负有及时救助、告知监护人的法定义务（E正确）。D错误：校园内发生伤害并不导致学校当然全责，归责仍以过错为要件。', '["B"]', 0, 0.0, '2026-11-09 17:21:41');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (265, 4, 85, 85, 'multi', 1.6, '某市对学校课后服务工作提出要求：服务内容要多样化，要尊重学生和家长的自主选择，要为学习有困难的学生提供辅导，不得利用课后服务时间统一讲授新课。这些要求符合（　）', '[["A","满足学生多样化发展需求"],["B","尊重学生和家长的自愿选择"],["C","对学习困难学生进行必要的学业帮扶"],["D","借课后服务之名集体补课、增加学生负担"],["E","把课后服务办成统一的新课教学"]]', '["A","B","C"]', 'A正确：多样化内容有助于发展兴趣特长、促进全面发展。B正确：课后服务坚持学生自愿、家长自愿原则。C正确：对学习有困难的学生进行答疑辅导是课后服务的重要内容。D、E错误：依据“双减”政策，课后服务不得变成集体补课或讲授新课，不得加重学生课业负担。', '["B"]', 0, 0.0, '2026-11-09 17:21:42');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (266, 4, 86, 86, 'multi', 1.6, '一位语文教师经常运用情境教学。下列属于情境教学法基本特征的有（　）', '[["A","以生动具体的形象激发学生的情感体验"],["B","课堂中只允许学生体验，不进行任何理性概括和知识讲授"],["C","教师只作旁观，完全不加以引导和点拨"],["D","创设与教学内容相适应的真实或模拟情境"],["E","情境越离奇、越脱离学生生活，教学效果越好"]]', '["A","D"]', '情境教学（以李吉林情境教育为代表）以“形真、情切、意远、理寓其中”为特点：A正确，借助生动具体的形象唤起情感体验；D正确，强调围绕教学内容创设真实或模拟的情境。B错误：情境教学主张情知交融、在体验基础上引导概括，并不排斥理性认识和必要讲授。C错误：教师要适时引导、点拨、升华，而非放任旁观。E错误：情境应贴近学生已有生活经验和认知水平，脱离生活反而妨碍理解。', '["B"]', 0, 0.0, '2026-11-09 17:21:42');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (267, 4, 87, 87, 'multi', 1.6, '某校组织学生乘大巴参加校外实践活动，途中因其他车辆违章变道发生交通事故，造成学生受伤，学校大巴驾驶员和随车教师并无过错。关于责任承担，下列说法正确的有（　）', '[["A","学生有权依法获得赔偿"],["B","事故责任应由违章车辆一方依法承担"],["C","学校已尽到组织管理和安全保障义务的，不承担侵权责任"],["D","只要发生在校外活动中，学校就应承担全部责任"],["E","学校应及时救助受伤学生并告知其监护人"]]', '["A","B","C","E"]', '依据《民法典》侵权责任编和《学生伤害事故处理办法》，学生伤害事故责任以过错为原则。本案由第三方违章造成，应由责任方承担赔偿；学校无过错则不承担侵权责任，但仍负有及时救助、告知和报告义务，A、B、C、E正确。D错误：学校责任不依“校外”这一地点当然成立，而取决于是否尽到教育、管理职责。', '["B"]', 0, 0.0, '2026-11-09 17:21:43');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (268, 4, 88, 88, 'multi', 1.6, '某校校园文化节安排了经典诵读、民族歌舞表演、传统手工艺制作和民族文化展板等活动。这些活动的育人价值在于（　）', '[["A","增进学生对中华优秀传统文化的认同"],["B","促进民族团结教育和文化理解"],["C","在实践体验中提高学生的审美和动手能力"],["D","文化节只是娱乐活动，与育人目标无关"],["E","丰富校园文化生活，营造良好的隐性课程环境"]]', '["A","B","C","E"]', '传统文化展示有助于文化认同与文化自信（A）；民族歌舞、民族文化内容可渗透民族团结教育（B）；表演与手工艺制作能发展审美和实践能力（C）；丰富的校园文化本身构成隐性课程，发挥潜移默化的育人作用（E）。D错误：校园文化活动是学校教育和隐性课程的重要载体，具有明确的育人功能。', '["A","B","C","D","E"]', 0, 0.0, '2026-11-09 17:21:46');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (269, 4, 89, 89, 'multi', 1.6, '一位教师反思后发现自己“讲得太多、学生参与太少”，于是调整教学：增加课堂提问与讨论、设计小组合作任务、留出学生练习和展示时间。这种调整符合（　）', '[["A","启发性教学原则"],["B","教师主导与学生主体相统一的规律"],["C","以学生活动完全取代教师讲授"],["D","调动学生学习的主动性"],["E","促进学生从学会走向会学"]]', '["A","B","D","E"]', '增加提问讨论、合作探究体现启发性原则（A）和教师主导作用与学生主体作用相统一的教学规律（B）；学生在提问、讨论和展示中由被动接受转为主动参与，有利于调动学习主动性（D）；教师由“教会知识”转向引导学生掌握方法，促进学生从“学会”走向“会学”（E）。C错误：强调学生主体并不否定教师必要的讲授与引导，讲授法在系统传授知识方面仍有不可替代的价值。', '["A","B","D","E"]', 1, 1.6, '2026-11-09 17:21:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (270, 4, 90, 90, 'multi', 1.6, '某市要求学校改革学生评价：不以分数作为评价学生的唯一依据、关注学生成长过程、重视学生的自我反思与同伴互评。这体现的评价理念有（　）', '[["A","评价内容的综合化，关注德智体美劳全面发展"],["B","评价方式的过程化与多元化"],["C","评价主体的多元化，强调学生参与"],["D","以甄别和选拔为唯一目的的评价观"],["E","发挥评价促进学生发展的教育功能"]]', '["A","B","C","E"]', '不以分数为唯一依据体现评价内容综合化（A）；关注成长过程、采用多元方式体现过程性、多元化评价（B）；自我反思与同伴互评体现评价主体多元（C）；改革的落脚点是促进发展（E）。D错误：甄别选拔是传统评价的突出功能，发展性评价强调激励、诊断与改进，反对“为了选拔而评价”。', '["A","B","C","E"]', 1, 1.6, '2026-11-09 17:22:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (364, 16, 3152, 1, 'judge', 0.6, '斯金纳的操作性条件反射理论认为，可变比率强化程式比固定比率强化更能抵抗行为的消退。', '[["A","正确"],["B","错误"]]', '["A"]', '斯金纳操作性条件反射指出，间歇（可变比率、可变时距）强化比连续强化更能维持行为、抵抗消退，因为个体无法预测下一次强化何时出现。', '["A"]', 1, 0.6, '2026-11-10 11:49:54');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (365, 16, 3153, 2, 'judge', 0.6, '依据耶克斯一多德森定律，学习动机强度与学习效率之间呈倒U形关系，中等强度的动机最有利于学习效率的提高，且最佳动机水平随任务难度的不同而变化。', '[["A","正确"],["B","错误"]]', '["A"]', '耶克斯一多德森定律表明，动机强度与学习效率呈倒U形关系：动机过弱或过强都不利于效率提高，中等强度的动机最有利于学习；且任务难度不同，最佳动机水平也不同。', '["A"]', 1, 0.6, '2026-11-10 11:49:54');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (366, 16, 3154, 3, 'judge', 0.6, '塞利格曼（Seligman）的习得性无助实验表明，当个体反复经历无法控制的负面事件后，可能放弃尝试，产生“做什么都没用”的无助感。', '[["A","正确"],["B","错误"]]', '["A"]', '塞利格曼以狗为对象的实验发现，反复遭受不可控电击且无法逃避的狗，后来即使能轻易逃避也不再尝试，表现出习得性无助；该概念后被用于解释学生的无力感与动机缺失。', '["A"]', 1, 0.6, '2026-11-10 11:49:55');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (367, 16, 3155, 4, 'judge', 0.6, '形式训练说认为，迁移能否发生取决于两种学习情境是否存在共同要素，而迁移是具体的、有条件的。', '[["A","正确"],["B","错误"]]', '["B"]', '张冠李戴：形式训练说以官能心理学为依据，主张心理官能经训练改善后可普遍迁移；“迁移取决于两种情境是否存在共同要素、迁移是具体有条件的”是桑代克共同要素说的主张。', '["A"]', 0, 0.0, '2026-11-10 11:49:55');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (368, 16, 3156, 5, 'judge', 0.6, '罗森塔尔（Rosenthal）的实验表明，教师对学生的期望会通过态度与行为传递给学生，并可能使学生的表现朝期望方向发展；这种皮格马利翁效应往往借助教师不同的“强化”方式影响学生的自我效能。', '[["A","正确"],["B","错误"]]', '["A"]', '罗森塔尔效应（皮格马利翁效应）说明教师期望具有自我实现预言作用：教师对高期望学生给予更多关注、鼓励与“强化”，学生因而更自信、表现更好，形成良性循环。', '["A"]', 1, 0.6, '2026-11-10 11:49:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (369, 16, 3157, 6, 'judge', 0.6, '在创造性解决问题时，从其他事物（原型）中获得启发、找到解决途径的心理机制称为原型启发，如鲁班受草叶划伤启发而发明锯子。', '[["A","正确"],["B","错误"]]', '["A"]', '原型启发是创造性思维的重要机制，指从自然界或生活中的“原型”获得启示，迁移到当前问题的解决方案；鲁班受草叶边缘小齿划伤手启发发明锯，即典型例子。', '["A"]', 1, 0.6, '2026-11-10 11:49:56');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (370, 16, 3158, 7, 'judge', 0.6, '学生在学校享有受教育权、人身权和财产权等基本权利。', '[["A","正确"],["B","错误"]]', '["A"]', '学生依法享有受教育权、人身权（人格尊严、隐私、身心健康等）和财产权。', '["A"]', 1, 0.6, '2026-11-10 11:49:57');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (371, 16, 3159, 8, 'judge', 0.6, '《中华人民共和国教师法》规定，教师的医疗同当地国家公务员享受同等的待遇，并定期对教师进行身体健康检查。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》第二十九条规定，教师的医疗同当地国家公务员享受同等的待遇，定期对教师进行身体健康检查，并因地制宜安排教师进行休养。', '["A"]', 1, 0.6, '2026-11-10 11:49:57');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (372, 16, 3160, 9, 'judge', 0.6, '《中华人民共和国义务教育法》规定，适龄儿童、少年的父母或者其他监护人无正当理由未送其入学接受义务教育的，由公安机关给予治安管理处罚。', '[["A","正确"],["B","错误"]]', '["B"]', '法律后果张冠李戴：《义务教育法》第五十八条规定，父母或者其他监护人无正当理由未送适龄儿童、少年入学接受义务教育的，由当地乡镇人民政府或者县级人民政府教育行政部门给予批评教育、责令限期改正，而非由公安机关给予治安管理处罚。', '["A"]', 0, 0.0, '2026-11-10 11:49:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (373, 16, 3161, 10, 'judge', 0.6, '《中华人民共和国未成年人保护法》（社会保护）规定，营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所，不得允许未成年人进入。', '[["A","正确"],["B","错误"]]', '["A"]', '《未成年人保护法》（社会保护）第五十八条等规定，营业性歌舞娱乐场所、酒吧、互联网上网服务营业场所等不适宜未成年人活动的场所，不得允许未成年人进入，并应在显著位置设置未成年人禁入标志。', '["A"]', 1, 0.6, '2026-11-10 11:49:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (374, 16, 3162, 11, 'judge', 0.6, '依据《教师资格条例》，参加教师资格考试有作弊行为的，其考试成绩作废，且1年内不得再次参加教师资格考试。', '[["A","正确"],["B","错误"]]', '["B"]', '年限设错：《教师资格条例》第二十条规定，参加教师资格考试有作弊行为的，其考试成绩作废，3年内不得再次参加教师资格考试，题干“1年”错误。', '["A"]', 0, 0.0, '2026-11-10 11:49:58');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (375, 16, 3163, 12, 'judge', 0.6, '《中小学教师职业道德规范》要求教师为人师表，以身作则、言传身教，自觉抵制社会不良风气影响，不利用职务之便谋取私利。', '[["A","正确"],["B","错误"]]', '["A"]', '《中小学教师职业道德规范》之“为人师表”要求教师以身作则、言传身教，自觉抵制社会不良风气影响，不利用职务之便谋取私利，作风正派、廉洁奉公。', '["A"]', 1, 0.6, '2026-11-10 11:49:59');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (376, 16, 3164, 13, 'judge', 0.6, '《新时代中小学教师职业行为十项准则》要求教师增强安全意识，加强安全教育，保护学生安全，在教育教学活动中遇突发事件、面临危险时，不得不顾学生安危、擅离职守。', '[["A","正确"],["B","错误"]]', '["A"]', '“加强安全防范”是十项准则之一：要求教师增强安全意识、加强安全教育、保护学生安全、防范事故风险，在教育教学活动中遇突发事件、面临危险时，不得不顾学生安危、擅离职守、自行逃离。', '["A"]', 1, 0.6, '2026-11-10 11:49:59');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (377, 16, 3165, 14, 'judge', 0.6, '中共中央办公厅、国务院办公厅2021年印发的"双减"文件，要求全面压减作业总量和时长，提升学校课后服务水平，不再审批新的面向义务教育阶段学生的学科类校外培训机构。', '[["A","正确"],["B","错误"]]', '["A"]', '“双减”政策核心在减轻过重作业负担与校外培训负担，提升学校教育教学质量与课后服务水平。', '["A"]', 1, 0.6, '2026-11-10 11:50:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (378, 16, 3166, 15, 'judge', 0.6, '教育部印发的《中小学德育工作指南》明确，中小学德育的主要内容包括理想信念教育、社会主义核心价值观教育、中华优秀传统文化教育、生态文明教育和心理健康教育。', '[["A","正确"],["B","错误"]]', '["A"]', '教育部2017年印发的《中小学德育工作指南》明确德育内容包括理想信念教育、社会主义核心价值观教育、中华优秀传统文化教育、生态文明教育、心理健康教育五大板块。', '["A"]', 1, 0.6, '2026-11-10 11:50:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (379, 16, 3167, 16, 'judge', 0.6, '教育目的只对学校层面的培养目标起指导作用，对课程目标和教学目标没有约束力。', '[["A","正确"],["B","错误"]]', '["B"]', '作用窄化：教育目的贯穿教育活动的全过程，对培养目标、课程目标、教学目标均具有导向、调控和评价作用。', '["A"]', 0, 0.0, '2026-11-10 11:50:00');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (380, 16, 3168, 17, 'judge', 0.6, '学校教育制度简称学制，它规定各级各类学校的性质、任务、入学条件、修业年限以及它们之间的关系。', '[["A","正确"],["B","错误"]]', '["A"]', '学制是各级各类学校的总体系，规定学校的性质、任务、入学条件、修业年限及其相互关系。', '["A"]', 1, 0.6, '2026-11-10 11:50:01');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (381, 16, 3169, 18, 'judge', 0.6, '遗忘的进程受学习材料的性质、学习程度、材料所处位置等因素影响。', '[["A","正确"],["B","错误"]]', '["A"]', '影响遗忘进程的因素是多方面的，题干列举的几项均为常见变量。', '["A"]', 1, 0.6, '2026-11-10 11:50:01');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (382, 16, 3170, 19, 'judge', 0.6, '研究表明，过度学习达到 150%（即恰能背诵后再学习 50%）时保持效果最好，因此过度学习的程度越高（如达到 200%、300%），保持效果就越好，也不会出现疲劳与厌烦。', '[["A","正确"],["B","错误"]]', '["B"]', '推论过度：过度学习达到 150% 时保持效果最佳，但超过这一限度后保持效果不再显著提高，还可能出现疲劳、厌烦等“报酬递减”现象。', '["A"]', 0, 0.0, '2026-11-10 11:50:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (383, 16, 3171, 20, 'judge', 0.6, '教学中既要传授知识，又要进行思想品德教育，这一要求体现的是理论联系实际原则。', '[["A","正确"],["B","错误"]]', '["B"]', '原则混淆：传授知识与思想品德教育相统一是科学性与思想性相统一原则的要求；理论联系实际原则强调以实际为出发点、学以致用。', '["A"]', 0, 0.0, '2026-11-10 11:50:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (384, 16, 3172, 21, 'judge', 0.6, '班主任了解学生最常用、最基本的方法是问卷法，观察法只在特殊情况下使用。', '[["A","正确"],["B","错误"]]', '["B"]', '方法错位：观察法是班主任了解学生最常用、最基本的方法，可在自然状态下获取真实信息；问卷法、谈话法等为辅助手段。', '["A"]', 0, 0.0, '2026-11-10 11:50:02');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (385, 16, 3173, 22, 'judge', 0.6, '气质类型没有好坏之分，而性格则有优劣之别。', '[["A","正确"],["B","错误"]]', '["A"]', '气质无好坏之分（类型差异），性格有优劣之别（受社会评价）。', '["A"]', 1, 0.6, '2026-11-10 11:50:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (386, 16, 3174, 23, 'judge', 0.6, '学习仅仅是外在行为的改变，不需要个体内部的信息加工过程。', '[["A","正确"],["B","错误"]]', '["B"]', '条件缺失：学习是由经验引起的行为或行为潜能的相对持久变化，包含个体内部的信息加工过程。', '["A"]', 0, 0.0, '2026-11-10 11:50:03');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (387, 16, 3175, 24, 'judge', 0.6, '正迁移就是顺向迁移，二者是按照同一标准划分出来的同一类迁移。', '[["A","正确"],["B","错误"]]', '["B"]', '概念混淆：正/负迁移按“效果”划分，顺向/逆向迁移按“方向”划分，划分标准不同，不能等同。', '["A"]', 0, 0.0, '2026-11-10 11:50:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (388, 16, 3176, 25, 'judge', 0.6, '学习策略是先天具备的，教师无法通过教学加以培养。', '[["A","正确"],["B","错误"]]', '["B"]', '绝对化表述：学习策略是可以教授和训练的，是学习策略教学的核心观点。', '["A"]', 0, 0.0, '2026-11-10 11:50:04');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (389, 16, 3177, 26, 'judge', 0.6, '学校心理健康教育就是开设一门心理健康课，其余工作由专业机构承担。', '[["A","正确"],["B","错误"]]', '["B"]', '以偏概全：心理健康教育应面向全体、渗透于学科教学与班级管理、辅以个别辅导与转介，不能只靠一门课。', '["A"]', 0, 0.0, '2026-11-10 11:50:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (390, 16, 3178, 27, 'judge', 0.6, '《中华人民共和国义务教育法》规定，义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育。', '[["A","正确"],["B","错误"]]', '["A"]', '《义务教育法》第二条：义务教育是国家统一实施的所有适龄儿童、少年必须接受的教育，是国家必须予以保障的公益性事业。', '["A"]', 1, 0.6, '2026-11-10 11:50:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (391, 16, 3179, 28, 'judge', 0.6, '学校不得聘用因故意犯罪受到有期徒刑以上刑事处罚的人员担任教职工。', '[["A","正确"],["B","错误"]]', '["A"]', '《教师法》第十四条：受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格，已取得的丧失教师资格；《义务教育法》第二十四条第三款、《未成年人保护法》第六十二条另有从业禁止与入职查询规定。', '["A"]', 1, 0.6, '2026-11-10 11:50:05');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (392, 16, 3180, 29, 'judge', 0.6, '教师职业道德修养的最终目的在于养成良好的职业道德行为习惯。', '[["A","正确"],["B","错误"]]', '["A"]', '教师职业道德修养的最终目的在于养成良好的职业道德行为习惯，实现知行统一。', '["A"]', 1, 0.6, '2026-11-10 11:50:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (393, 16, 3181, 30, 'judge', 0.6, '《义务教育课程方案（2022年版）》提出，劳动、综合实践活动、地方课程与校本课程的课时可统筹使用。', '[["A","正确"],["B","错误"]]', '["A"]', '2022年版课程方案提出劳动、综合实践活动、地方课程与校本课程课时可统筹使用，并强调劳动课程独立设置。', '["A"]', 1, 0.6, '2026-11-10 11:50:06');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (394, 16, 3182, 31, 'single', 1.0, '在自由回忆实验中，被试对词表开头和结尾部分的记忆较好、中间部分记忆较差。这种"记忆"中的现象被称为（　）', '[["A","前摄抑制"],["B","系列位置效应"],["C","倒摄抑制"],["D","刻板效应"]]', '["B"]', '系列位置效应指在自由回忆中，开头（首因效应，因更多复述进入长时记忆）与结尾（近因效应，仍在短时记忆）的项目回忆率高于中间项目；中间部分受前摄抑制与倒摄抑制双重干扰。', '["A"]', 0, 0.0, '2026-11-10 11:50:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (395, 16, 3183, 32, 'single', 1.0, '学生上课时一边听讲一边记笔记，还能兼顾观察板书，几项活动在同一时间内同时进行。上述表现属于注意品质中的（　）', '[["A","广度"],["B","稳定性"],["C","分配"],["D","转移"]]', '["C"]', '注意的分配指在同一时间内把注意指向两种或两种以上对象/活动；边听讲边记笔记同时进行，依赖注意分配。', '["A"]', 0, 0.0, '2026-11-10 11:50:07');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (396, 16, 3184, 33, 'single', 1.0, '学生在复习时把零散知识点按逻辑关系画成思维导图、列提纲，这类学习策略属于（　）', '[["A","组织策略"],["B","复述策略"],["C","精细加工策略"],["D","资源管理策略"]]', '["A"]', '组织策略是对相关内容进行归类、整理以形成清晰结构的策略，如列提纲、画图表、构建网络关系。', '["A"]', 1, 1.0, '2026-11-10 11:50:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (397, 16, 3185, 34, 'single', 1.0, '在问题解决中，反复思考一道难题久未解决，搁置一段时间后再回来却豁然开朗。这种“悬而不决—中断—突现”的现象称为（　）', '[["A","功能固着"],["B","酝酿效应"],["C","定势"],["D","原型启发"]]', '["B"]', '酝酿效应指问题暂时搁置后，由于潜意识仍在加工、或脱离僵化思路，重新面对时突然找到解法。', '["A"]', 0, 0.0, '2026-11-10 11:50:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (398, 16, 3186, 35, 'single', 1.0, '奥苏贝尔认为，在儿童早期，学生努力学习往往是为了得到家长或老师的赞许与认可。这种学习动机属于（　）', '[["A","附属内驱力"],["B","认知内驱力"],["C","自我提高内驱力"],["D","成就内驱力"]]', '["A"]', '奥苏贝尔将学校情境中的成就动机分为认知内驱力（求知欲）、自我提高内驱力（赢得地位）和附属内驱力（获长者赞许）；儿童早期附属内驱力最突出。', '["A"]', 1, 1.0, '2026-11-10 11:50:08');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (399, 16, 3187, 36, 'single', 1.0, '某校在组织教师业务培训时，培训专家指出：“成年教师随着年龄增长，其运用已有知识经验去解决问题的能力仍可持续提升。”依据卡特尔（Cattell）的智力理论，专家所描述的智力成分是（　）', '[["A","流体智力"],["B","晶体智力"],["C","一般智力"],["D","多元智力"]]', '["B"]', '卡特尔将智力分为流体智力（依赖先天禀赋与加工速度）与晶体智力（依赖知识经验与文化积累，随年龄增长仍可持续提升）；题干指向晶体智力。', '["A"]', 0, 0.0, '2026-11-10 11:50:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (400, 16, 3188, 37, 'single', 1.0, '为增加学生举手发言的频率，教师在该生发言后当即给予表扬。依据操作性条件反射，这种在行为之后呈现愉快刺激、以提高该行为发生频率的做法属于（　）', '[["A","负强化"],["B","惩罚"],["C","正强化"],["D","消退"]]', '["C"]', '正强化是在期望行为之后施加愉快刺激（如表扬）以提高其发生频率；负强化是通过移除厌恶刺激来增强行为。', '["A"]', 0, 0.0, '2026-11-10 11:50:09');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (401, 16, 3189, 38, 'single', 1.0, '某教师完整示范了“如何用刻度尺测量物体长度”，随后让学生复述操作步骤、在脑中回放示范动作，再动手反复练习。按班杜拉的理论，这一教学过程依次对应的观察学习子过程是（　）', '[["A","注意一保持一动作再现"],["B","保持一注意一动作再现"],["C","动作再现一注意一保持"],["D","注意一动作再现一保持"]]', '["A"]', '班杜拉把观察学习分为注意、保持、动作再现和动机四个子过程。示范—复述回放—动手练习的顺序与注意—保持—动作再现一一对应。', '["A"]', 1, 1.0, '2026-11-10 11:50:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (402, 16, 3190, 39, 'single', 1.0, '维果斯基理论在教学上的重要应用是“支架式教学”：教师先在学生学习中提供临时性支持，待其能力增长后逐步撤去。这里的“支架”喻指（　）', '[["A","最终要学生独立完成的作业"],["B","教师提供的临时性支持与引导"],["C","固定的知识框架模板"],["D","同伴之间的竞争压力"]]', '["B"]', '支架式教学源于维果斯基“最近发展区”：教师在学习初期提供提示、示范、分解任务等临时性支持（支架），随着学生能力提高逐步撤去。', '["A"]', 0, 0.0, '2026-11-10 11:50:10');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (403, 16, 3191, 40, 'single', 1.0, '某校在制定育人方案时，校长提出“学校的一切工作都应围绕升学率展开，劳动与实践活动可以全部取消”。依据《中华人民共和国教育法》规定的教育方针，该校的育人方案应当坚持（　）', '[["A","与生产劳动和社会实践相结合"],["B","与宗教相结合"],["C","与市场经济相结合"],["D","与家庭教育相脱离"]]', '["A"]', '《教育法》第五条规定的教育方针要求教育必须为社会主义现代化建设服务、为人民服务，必须与生产劳动和社会实践相结合。', '["A"]', 1, 1.0, '2026-11-10 11:50:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (404, 16, 3192, 41, 'single', 1.0, '《中华人民共和国义务教育法》规定，教师在教育教学中应当关心、爱护学生，尊重学生的人格，不得对学生实施体罚、变相体罚或者其他侮辱人格尊严的行为。这一规定的直接目的是（　）', '[["A","提高学生的考试成绩"],["B","维护学生的人格尊严与合法权益"],["C","减轻教师工作负担"],["D","便于学校统一管理"]]', '["B"]', '《义务教育法》第二十九条要求教师关心爱护学生、尊重人格，不得实施体罚、变相体罚或侮辱人格尊严的行为；这是教师法定义务，直接目的是维护学生的人格尊严与合法权益。', '["A"]', 0, 0.0, '2026-11-10 11:50:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (405, 16, 3193, 42, 'single', 1.0, '某中学初二学生小涛多次违纪，班主任向学校建议“干脆让他回家反省，以免影响班级”。依据《中华人民共和国未成年人保护法》（学校保护），学校对品行有缺点、学习有困难的学生应当耐心教育、帮助，不得违反法律和国家规定（　）：该班主任的建议如被采纳，即属此类。', '[["A","要求其参加课外辅导"],["B","调整其座位"],["C","开除未成年学生"],["D","与其家长沟通"]]', '["C"]', '《未成年人保护法》（学校保护）规定，学校应当关心、爱护学生，对品行有缺点、学习有困难的学生耐心教育、帮助，不得违反法律和国家规定开除未成年学生。', '["A"]', 0, 0.0, '2026-11-10 11:50:11');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (406, 16, 3194, 43, 'single', 1.0, '某校教师刘某在校门口发现有人向学生兜售含有淫秽、恐怖内容的出版物。依据《中华人民共和国教师法》规定的教师义务，刘某应当（　）', '[["A","制止有害于学生的行为，批评和抵制有害于学生健康成长的现象"],["B","视而不见，校外行为不属教师职责范围"],["C","直接对兜售者实施罚款并没收出版物"],["D","只在本班家长群中提醒，无需向学校报告"]]', '["A"]', '《教师法》第八条将“制止有害于学生的行为或者其他侵犯学生合法权益的行为，批评和抵制有害于学生健康成长的现象”列为教师义务。', '["A"]', 1, 1.0, '2026-11-10 11:50:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (407, 16, 3195, 44, 'single', 1.0, '某县因财政紧张，拟将本县教师工资与当地企业职工平均工资挂钩，并暂缓教师晋级增薪。依据《中华人民共和国教师法》，该县的做法（　）', '[["A","合法，教师工资标准可由县级人民政府根据财力自行确定"],["B","合法，只要教师平均工资不低于当地最低工资标准即可"],["C","不合法，教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高"],["D","不合法，但法律仅要求教师工资与公务员持平，并未要求逐步提高"]]', '["C"]', '《教师法》第二十五条规定，教师的平均工资水平应当不低于或者高于国家公务员的平均工资水平，并逐步提高。', '["A"]', 0, 0.0, '2026-11-10 11:50:12');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (408, 16, 3196, 45, 'single', 1.0, '某县教育局在新设公办初中配备校长时，明确校长由县教育局依法聘任、学校日常事务由校长全面负责。依据《中华人民共和国义务教育法》，该校实行的领导体制是（　）', '[["A","党委领导下的校长负责制"],["B","教师委员会集体负责制"],["C","董事会领导下的校长负责制"],["D","校长负责制"]]', '["D"]', '《义务教育法》第二十六条规定，学校实行校长负责制；校长由县级人民政府教育行政部门依法聘任，负责学校的教育教学和行政管理工作。', '["A"]', 0, 0.0, '2026-11-10 11:50:14');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (409, 16, 3197, 46, 'single', 1.0, '某小学六年级未成年学生小浩周六自行到校玩耍，攀爬体育器械时，不慎摔伤；学校已履行相应职责、行为并无不当。依据《学生伤害事故处理办法》，对该事故（　）', '[["A","学校应当承担全部赔偿责任"],["B","学校行为并无不当，不承担事故责任"],["C","学校应当承担一半责任"],["D","由班主任个人承担赔偿"]]', '["B"]', '《学生伤害事故处理办法》第十三条规定，在放学后、节假日或假期等学校工作时间以外，学生自行滞留学校或自行到校发生事故的，学校已履行相应职责、行为并无不当的，不承担事故责任。', '["A"]', 0, 0.0, '2026-11-10 11:50:15');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (410, 16, 3198, 47, 'single', 1.0, '某中学教师郑某因故意犯罪被判处有期徒刑三年，学校拟作出处理。依据《中华人民共和国教师法》《教师资格条例》，该教师的教师资格应当（　）', '[["A","丧失，且不能重新取得"],["B","保留，待其刑满释放后继续有效"],["C","由所在学校决定暂停或者恢复"],["D","暂缓注册，五年后自动恢复"]]', '["A"]', '《教师法》第十四条与《教师资格条例》规定，受到剥夺政治权利或者故意犯罪受到有期徒刑以上刑事处罚的，不能取得教师资格，已经取得的丧失教师资格且不能重新取得。', '["A"]', 1, 1.0, '2026-11-10 11:50:16');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (411, 16, 3199, 48, 'single', 1.0, '某校教师冯老师多次在节假日组织学生有偿补课，并通过家长群推销教辅资料获利。依据《新时代中小学教师职业行为十项准则》，冯老师的行为主要违背的准则是（　）', '[["A","坚定政治方向"],["B","自觉爱国守法"],["C","潜心教书育人"],["D","为人师表（坚守廉洁自律）"]]', '["D"]', '“坚守廉洁自律”要求教师不得索要、收受学生及家长财物，“规范从教行为”要求自觉抵制有偿补课；组织有偿补课并借家长群推销教辅获利，集中违背为人师表。', '["A"]', 0, 0.0, '2026-11-10 11:50:17');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (412, 16, 3200, 49, 'single', 1.0, '某校教师钱老师只按考试成绩排座位、只关注前几名学生，对后进生放任不管。依据《中小学教师职业道德规范》中“教书育人”的要求，钱老师的做法主要违背了（　）', '[["A","遵循教育规律，实施素质教育，不以分数作为评价学生的唯一标准"],["B","只关注学生的考试成绩"],["C","按家长要求布置作业"],["D","优先培养少数尖子生"]]', '["A"]', '“教书育人”要求遵循教育规律实施素质教育，循循善诱、因材施教，不以分数作为评价学生的唯一标准；按成绩排座位、只关注尖子生并放任后进生，均违背该要求。', '["A"]', 1, 1.0, '2026-11-10 11:50:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (413, 16, 3201, 50, 'single', 1.0, '某中学学生小宇经常旷课、顶撞教师，班主任多次教育时，他仍不改正。依据《中华人民共和国教育法》，受教育者应当履行的义务是（　）', '[["A","遵守法律、法规，遵守学生行为规范，尊敬师长，努力学习，完成规定的学习任务"],["B","参加教育教学计划安排的各种活动，使用教育教学设施、设备、图书资料"],["C","按照国家有关规定获得奖学金、贷学金、助学金"],["D","在学业成绩和品行上获得公正评价，完成规定学业后获得相应证书"]]', '["A"]', '《教育法》规定受教育者应当履行下列义务：遵守法律、法规；遵守学生行为规范，尊敬师长，养成良好的思想品德和行为习惯；努力学习，完成规定的学习任务。B、C、D属受教育者的权利而非义务。', '["A"]', 1, 1.0, '2026-11-10 11:50:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (414, 16, 3202, 51, 'single', 1.0, '某县在落实“双减”工作中拟采取一系列措施。下列措施中，属于“双减”政策治理重点的是（　）', '[["A","减少学校课程门类和课时"],["B","取消所有考试与作业"],["C","减轻学生过重作业负担和校外培训负担"],["D","降低教师待遇"]]', '["C"]', '“双减”即减轻义务教育阶段学生过重作业负担和校外培训负担，目标是提升学校教育教学质量、作业设计质量与课后服务水平。', '["A"]', 0, 0.0, '2026-11-10 11:50:19');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (415, 16, 3203, 52, 'single', 1.0, '某校在组织劳动教育周时，安排学生到校内种植园翻地播种、走进社区敬老院开展志愿服务，并向家长发放家务劳动清单。依据《关于全面加强新时代大中小学劳动教育的意见》，该校安排的劳动教育内容涵盖（　）', '[["A","日常起居事务"],["B","纯理论讲座"],["C","商业经营活动"],["D","日常生活劳动、生产劳动和服务性劳动"]]', '["D"]', '《关于全面加强新时代大中小学劳动教育的意见》明确劳动教育内容为日常生活劳动、生产劳动和服务性劳动三类。', '["A"]', 0, 0.0, '2026-11-10 11:50:20');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (416, 16, 3204, 53, 'single', 1.0, '按照课程资源的功能特点，可将其划分为（　）', '[["A","校内课程资源与校外课程资源"],["B","素材性课程资源与条件性课程资源"],["C","显性课程资源与隐性课程资源"],["D","自然课程资源与社会课程资源"]]', '["B"]', '按功能特点，课程资源分为素材性资源（知识、经验等）与条件性资源（人力、物力、财力等）。', '["A"]', 0, 0.0, '2026-11-10 11:50:20');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (417, 16, 3205, 54, 'single', 1.0, '下列因素中，不属于影响课程实施的因素的是（　）', '[["A","学生家庭的经济收入水平"],["B","课程方案本身的特征"],["C","教师的特征与态度"],["D","学校的支持与外部评价环境"]]', '["A"]', '影响课程实施的因素包括课程方案特征、教师特征、学校支持与外部环境，家庭经济收入属校外环境中较间接的因素。', '["A"]', 1, 1.0, '2026-11-10 11:50:21');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (418, 16, 3206, 55, 'single', 1.0, '关于教学与教育、智育的关系，下列说法正确的是（　）', '[["A","教学等于教育，二者没有区别"],["B","教学是实施全面发展教育的基本途径，智育主要通过教学来实现"],["C","教学是智育的唯一途径"],["D","教育与智育是同一概念"]]', '["B"]', '教学是实施全面发展教育的基本途径；智育主要通过教学实现，但还有其他途径。', '["A"]', 0, 0.0, '2026-11-10 11:50:21');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (419, 16, 3207, 56, 'single', 1.0, '“温故而知新”学而时习之”体现的教学原则是（　）', '[["A","巩固性原则"],["B","量力性原则"],["C","因材施教原则"],["D","直观性原则"]]', '["A"]', '“温故而知新”学而时习之”体现巩固性原则。', '["A"]', 1, 1.0, '2026-11-10 11:50:22');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (420, 16, 3208, 57, 'single', 1.0, '教师选择教学方法时需要考虑的首要依据是（　）', '[["A","教师个人的喜好"],["B","教学目标与任务"],["C","学校的硬件条件"],["D","家长的期望"]]', '["B"]', '选择教学方法的首要依据是教学目标与任务，同时兼顾内容、学生与条件。', '["A"]', 0, 0.0, '2026-11-10 11:50:23');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (421, 16, 3209, 58, 'single', 1.0, '班级授课制的特殊形式是（　）', '[["A","现场教学"],["B","个别辅导"],["C","分组教学"],["D","复式教学"]]', '["D"]', '复式教学是班级授课制的特殊形式（把不同年级编在一个班教学）。', '["A"]', 0, 0.0, '2026-11-10 11:50:23');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (422, 16, 3210, 59, 'single', 1.0, '一堂好课的基本要求不包括（　）', '[["A","目标明确、重点突出"],["B","内容正确、方法得当"],["C","板书越多越好、教师讲得越满越好"],["D","表达清晰、气氛热烈"]]', '["C"]', '好课标准重在教学有效，“板书越多越好、讲得越满越好”属错误认识。', '["A"]', 0, 0.0, '2026-11-10 11:50:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (423, 16, 3211, 60, 'single', 1.0, '某中学在月考后按成绩对学生排名并张榜公布，据此调整分层编班。按评价所参照的标准划分，该校采用的评价属于（　）', '[["A","相对性评价"],["B","绝对性评价"],["C","个体内差异评价"],["D","诊断性评价"]]', '["A"]', '相对性评价以被评价者在群体中的相对位置为参照标准；该校按成绩排名并据此分层编班，即属相对性评价。', '["A"]', 1, 1.0, '2026-11-10 11:50:24');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (424, 16, 3212, 61, 'single', 1.0, '德育过程与学生品德形成过程的关系是（　）', '[["A","二者完全等同"],["B","品德形成过程属于教育过程的一部分"],["C","德育过程是教育者有目的的培养过程，品德形成过程是学生个体自我发展的过程"],["D","二者互不相关"]]', '["C"]', '德育过程是教育者有目的、有计划的培养过程，品德形成过程是学生个体内部的发展过程，二者相互联系但性质不同。', '["A"]', 0, 0.0, '2026-11-10 11:50:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (425, 16, 3213, 62, 'single', 1.0, '马卡连柯说"要尽量多地要求一个人，也要尽可能地尊重一个人”。这体现的德育原则是（　）', '[["A","疏导原则"],["B","长善救失原则"],["C","知行统一原则"],["D","严格要求与尊重学生相结合原则"]]', '["D"]', '“尽量多地要求、尽可能地尊重”体现严格要求与尊重学生相结合原则。', '["A"]', 0, 0.0, '2026-11-10 11:50:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (426, 16, 3214, 63, 'single', 1.0, '某班班主任在期末给学生写操行评语，对表现突出的学生颁发"文明之星”奖状，对违纪学生给予批评。该班主任采用的德育方法是（　）', '[["A","说服教育法"],["B","榜样示范法"],["C","品德评价法"],["D","情感陶冶法"]]', '["C"]', '表扬与奖励、批评与处分、操行评定均属品德评价法（奖惩法）。', '["A"]', 0, 0.0, '2026-11-10 11:50:25');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (427, 16, 3215, 64, 'single', 1.0, '某校在德育研讨中，有教师提出：“德育的关键在于引导学生运用道德推理处理两难情境，通过提高其道德判断水平来促进品德发展。”这一主张所依据的德育模式是（　）', '[["A","体谅模式"],["B","社会模仿模式"],["C","价值澄清模式"],["D","认知性道德发展模式"]]', '["D"]', '认知性道德发展模式（皮亚杰、科尔伯格）以道德认知发展为基础，借助道德两难问题讨论提高学生的道德判断能力。', '["A"]', 0, 0.0, '2026-11-10 11:50:26');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (428, 16, 3216, 65, 'single', 1.0, '某班班主任李老师凡事亲力亲为，班干部形同虚设，班级活动全由其一手安排。下列做法中，不属于培养和建设班集体一般方法的是（　）', '[["A","确立共同的奋斗目标"],["B","由班主任包办一切班级事务"],["C","选拔和培养学生干部"],["D","开展丰富多彩的集体活动"]]', '["B"]', '培养班集体需确立目标、培养干部、开展活动、形成舆论班风、健全制度，并发挥学生主体作用；由班主任包办一切班级事务不利于班集体形成。', '["A"]', 0, 0.0, '2026-11-10 11:50:26');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (429, 16, 3217, 66, 'single', 1.0, '班主任组织家长会时，下列做法最恰当的是（　）', '[["A","只通报学生成绩排名，便于家长比较"],["B","点名批评成绩落后学生及其家长"],["C","介绍班级情况与教育要求，同时倾听家长意见"],["D","只与优生家长交流，其余家长不必参加"]]', '["C"]', '家长会应介绍班级情况与教育要求，同时倾听家长意见，避免排名与点名批评。', '["A"]', 0, 0.0, '2026-11-10 11:50:27');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (430, 16, 3218, 67, 'single', 1.0, '某校为帮助新入职教师尽快胜任教学，安排骨干教师与其结对，定期听课评课、共同备课、共同打磨教学设计。这种促进教师专业发展的途径属于（　）', '[["A","自我教育"],["B","学历进修"],["C","脱产培训"],["D","师徒结对"]]', '["D"]', '师徒结对（导师制）通过资深教师传帮带，在日常教学实践中促进新教师成长，是校本培训的主要形式之一。', '["A"]', 0, 0.0, '2026-11-10 11:50:27');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (431, 16, 3219, 68, 'single', 1.0, '学生初学某项内容时需要注意努力维持注意，熟练后不需意志努力也能专注。这时的注意属于（　）', '[["A","无意注意"],["B","有意注意"],["C","有意后注意"],["D","转移中的注意"]]', '["C"]', '有意后注意是有目的但不需要意志努力的注意，常见于熟练活动。', '["A"]', 0, 0.0, '2026-11-10 11:50:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (432, 16, 3220, 69, 'single', 1.0, '某校教师何老师在复习指导时，让学生把"及时复习""分散复习""尝试回忆与反复阅读相结合"结合起来。该教师这样做主要是为了（　）', '[["A","增加作业数量"],["B","减少教学时间"],["C","提高记忆效果，克服遗忘"],["D","降低学习难度"]]', '["C"]', '及时复习、分散复习、尝试回忆与反复阅读相结合，都是提高记忆效果、克服遗忘的有效策略。', '["A"]', 0, 0.0, '2026-11-10 11:50:28');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (433, 16, 3221, 70, 'single', 1.0, '学生根据课文描述在头脑中再现"草原"的画面，这属于（　）', '[["A","创造想象"],["B","幻想"],["C","表象记忆"],["D","再造想象"]]', '["D"]', '依据语言描述在头脑中再现相应形象，属再造想象。', '["A"]', 0, 0.0, '2026-11-10 11:50:29');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (434, 16, 3222, 71, 'single', 1.0, '解决问题时，把总目标分解为一系列子目标，通过逐步缩小差距达到总目标。这种策略称为（　）', '[["A","爬山法"],["B","手段一目的分析法"],["C","逆向搜索法"],["D","类比法"]]', '["B"]', '手段一目的分析法：把总目标分解为子目标，逐步缩小当前状态与目标状态的差距。', '["A"]', 0, 0.0, '2026-11-10 11:50:30');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (435, 16, 3223, 72, 'single', 1.0, '学生因考试失败而长期情绪低落、失眠、注意力无法集中，班主任最恰当的做法是（　）', '[["A","劝其\\"想开点”，不必过多关注"],["B","耐心倾听、给予支持，必要时转介学校心理辅导教师"],["C","当众鼓励其\\"下次一定行\\""],["D","直接要求家长带其就医"]]', '["B"]', '班主任应耐心倾听、提供支持，并在必要时转介专业心理辅导。', '["A"]', 0, 0.0, '2026-11-10 11:50:30');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (436, 16, 3224, 73, 'single', 1.0, '意志行动的心理过程一般分为（　）两个阶段。', '[["A","动机斗争与目的确立"],["B","制定计划与检查结果"],["C","尝试错误与顿悟"],["D","采取决定与执行决定"]]', '["D"]', '意志行动分为采取决定（动机斗争、确定目的、选择方法）与执行决定两个阶段。', '["A"]', 0, 0.0, '2026-11-10 11:50:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (437, 16, 3225, 74, 'single', 1.0, '性格的结构特征中，表现为个体对自己、对他人、对集体、对劳动的态度方面的是（　）', '[["A","态度特征"],["B","意志特征"],["C","情绪特征"],["D","理智特征"]]', '["A"]', '性格的态度特征表现为对自己、他人、集体、劳动、学习的态度。', '["A"]', 1, 1.0, '2026-11-10 11:50:31');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (438, 16, 3226, 75, 'single', 1.0, '托尔曼通过白鼠走迷宫实验提出，学习是对情境形成"认知地图”，这一理论被称为（　）', '[["A","试误说"],["B","顿悟说"],["C","观察学习理论"],["D","符号学习理论（认知一目的说）"]]', '["D"]', '托尔曼提出符号学习理论（认知一目的说），认为学习形成“认知地图”。', '["A"]', 0, 0.0, '2026-11-10 11:50:32');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (439, 16, 3227, 76, 'single', 1.0, '某校教师吕老师在学生完成练习后，当天批改并逐一告知结果、提出改进建议。该教师这样做主要满足了学习动机激发中的（　）', '[["A","惩罚与威胁"],["B","增加作业量"],["C","及时反馈与评价"],["D","提高考试难度"]]', '["C"]', '及时告知结果并提出改进建议属于反馈与评价，可让学生看到进步与不足，是激发动机的重要措施。', '["A"]', 0, 0.0, '2026-11-10 11:50:32');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (440, 16, 3228, 77, 'single', 1.0, '为促进迁移而进行的教学，关键在于（　）', '[["A","加大练习量，反复训练同一题型"],["B","精选教材、合理编排内容、教授学习策略"],["C","只讲结论，节省时间"],["D","减少知识间的联系，避免干扰"]]', '["B"]', '促进迁移的教学策略：精选教材、合理编排教学内容、教授学习策略与迁移方法。', '["A"]', 0, 0.0, '2026-11-10 11:50:33');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (441, 16, 3229, 78, 'single', 1.0, '某校体育教师宋老师在指导学生练习广播体操时发现，学生的动作逐渐协调连贯，视觉控制减弱、动觉控制增强。该阶段属于操作技能形成的（　）', '[["A","操作定向"],["B","操作模仿"],["C","操作整合"],["D","操作熟练"]]', '["C"]', '操作整合阶段动觉控制增强、视觉控制减弱，动作趋于协调连贯，多余动作减少。', '["A"]', 0, 0.0, '2026-11-10 11:50:33');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (442, 16, 3230, 79, 'single', 1.0, '某中学将七年级新生按入学成绩分为“实验班”与“普通班”，配备不同师资与教室。依据《中华人民共和国义务教育法》，该校的做法（　）', '[["A","属于学校自主管理范围，合法有效"],["B","只要报县级教育行政部门备案即可实施"],["C","只要家长同意，法律不予禁止"],["D","学校不得分设重点班和非重点班，该校做法违反法律规定"]]', '["D"]', '《义务教育法》第二十二条规定，学校不得分设重点班和非重点班；以入学成绩划分“实验班”“普通班”并配置不同师资与教室，违反该规定。', '["A"]', 0, 0.0, '2026-11-10 11:50:34');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (443, 16, 3231, 80, 'single', 1.0, '当前推进的教育数字化战略，其核心指向是（　）', '[["A","以数字技术赋能教育高质量发展，扩大优质教育资源覆盖面"],["B","以线上教学全面替代课堂教学"],["C","取消教师讲授，全部由学生自学"],["D","用技术设备数量衡量教育现代化水平"]]', '["A"]', '教育数字化以技术赋能教育高质量发展、扩大优质资源覆盖面为核心，不是替代课堂教学。', '["A"]', 1, 1.0, '2026-11-10 11:50:34');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (444, 16, 3232, 81, 'multi', 1.6, '感觉记忆、短时记忆与长时记忆构成三级信息加工系统，下列描述符合该理论的有（　）', '[["A","瞬时记忆（感觉记忆）保持时间极短，容量较大"],["B","短时记忆容量约为7±2个组块"],["C","长时记忆保持时间长久，容量几乎无限"],["D","短时记忆中的信息若不复述，会迅速遗忘"],["E","瞬时记忆中的信息若受到注意可转入短时记忆，未受到注意则迅速消失"]]', '["A","B","C","D","E"]', '记忆按信息加工分为瞬时记忆（容量较大、保持极短，受注意可转入短时记忆，未受注意则迅速消失）、短时记忆（7±2 组块，需复述方能转入长时）、长时记忆（容量近乎无限、保持长久）；五项表述均正确。', '["A"]', 0, 0.0, '2026-11-10 11:50:35');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (445, 16, 3233, 82, 'multi', 1.6, '操作技能与心智技能在形成过程和特点上存在差异，下列判断正确的有（　）', '[["A","心智技能只能通过口头讲授获得，无需练习"],["B","操作技能依赖骨骼肌肉运动，心智技能依赖头脑中的认知活动"],["C","操作技能的形成一般经过操作定向、模仿、整合、熟练等阶段"],["D","心智技能按加里培林观点经历从外部言语到内部言语的阶段"],["E","二者都通过练习形成，都是程序性知识的应用"]]', '["B","C","D","E"]', '操作技能依赖肌肉运动、心智技能依赖认知活动，二者均经练习形成、属程序性知识应用；操作技能经历定向一模仿一整合一熟练，心智技能按加里培林观点经历从外部言语到内部言语阶段。', '["A"]', 0, 0.0, '2026-11-10 11:50:35');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (446, 16, 3234, 83, 'multi', 1.6, '《中华人民共和国教育法》对教育经费投入与办学条件保障作出的规定包括（　）', '[["A","学校可以自行决定扣减教师工资用于基建开支"],["B","国家建立以财政拨款为主、其他多种渠道筹措教育经费为辅的体制"],["C","义务教育阶段不收学费、杂费，国家建立义务教育经费保障机制"],["D","税务机关依法足额征收教育费附加，专项用于教育事业"],["E","国家鼓励境内外社会组织和个人捐资助学"]]', '["B","C","D","E"]', '《教育法》规定国家建立以财政拨款为主、其他多种渠道筹措教育经费为辅的体制；义务教育阶段不收学费杂费、建立经费保障机制；税务机关依法足额征收教育费附加专项用于教育；国家鼓励境内外组织和个人捐资助学。学校擅自扣减教师工资违法。', '["A"]', 0, 0.0, '2026-11-10 11:50:36');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (447, 16, 3235, 84, 'multi', 1.6, '某校拟修订校规校纪中的教育惩戒条款，并就“哪些行为属于惩戒禁区、学生和家长不服时如何救济”征求教师意见。依据《中小学教育惩戒规则（试行）》，下列判断正确的有（　）', '[["A","学校可以对违规学生处以罚款，罚款收入纳入学校公用经费"],["B","教师不得以击打、刺扎等方式直接造成身体痛苦，不得以歧视性、侮辱性的言行侵犯学生人格尊严"],["C","教师不得因个人情绪或者好恶，实施或者选择性实施教育惩戒"],["D","学生或者家长对学校实施的较重教育惩戒、纪律处分不服的，可以依法向学校提起申诉"],["E","学校拟实施较重教育惩戒或者给予纪律处分的，应当听取学生的陈述和申辩"]]', '["B","C","D","E"]', '《中小学教育惩戒规则（试行）》第十二条列举教师实施惩戒的禁止行为：体罚、变相体罚、侮辱歧视、因个人情绪好恶选择性实施惩戒等；第十四条要求学校拟实施较重惩戒或纪律处分时听取学生陈述和申辩；第十七条规定学生及家长不服的可依法申诉。学校无权对违规学生处以罚款。', '["A"]', 0, 0.0, '2026-11-10 11:50:36');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (448, 16, 3236, 85, 'multi', 1.6, '教学过程的基本阶段包括（　）', '[["A","教师备课与编写教案"],["B","激发学习动机"],["C","领会知识"],["D","巩固知识"],["E","检查知识"]]', '["B","C","D","E"]', '教学过程的基本阶段包括：激发学习动机、领会知识（中心环节）、巩固知识、运用知识、检查知识；“教师备课与编写教案”属于教学工作的基本环节，不属于课堂教学“教学过程”的基本阶段。', '["A"]', 0, 0.0, '2026-11-10 11:50:37');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (449, 16, 3237, 86, 'multi', 1.6, '德育过程的基本规律包括（　）', '[["A","学生的知、情、意、行统一发展"],["B","学生思想品德一旦形成便不会倒退或反复"],["C","学生在活动和交往中形成思想品德"],["D","德育过程只能在课堂内完成"],["E","学生思想内部矛盾转化"]]', '["A","C","E"]', '德育规律：知情理意行统一发展、在活动和交往中形成、思想内部矛盾转化，均正确；“一旦形成便不反复”违背长期性与反复性规律；“只能在课堂内完成”亦错。', '["A"]', 0, 0.0, '2026-11-10 11:50:37');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (450, 16, 3238, 87, 'multi', 1.6, '良好的记忆品质包括（　）', '[["A","敏捷性"],["B","持久性"],["C","易变性"],["D","冲动性"],["E","准确性"]]', '["A","B","E"]', '良好记忆品质：敏捷性、持久性、准确性，均正确；“易变性”非记忆品质；“冲动性”亦非记忆品质。', '["A"]', 0, 0.0, '2026-11-10 11:50:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (451, 16, 3239, 88, 'multi', 1.6, '影响遗忘进程的因素主要有（　）', '[["A","学习材料的性质与数量"],["B","学习程度（过度学习的程度）"],["C","识记材料的系列位置（首因效应、近因效应）"],["D","识记者的态度与需要"],["E","识记时的天气状况"]]', '["A","B","C","D"]', '影响遗忘的因素包括材料性质与数量、学习程度、系列位置、识记者态度与需要、识记方法等。', '["A"]', 0, 0.0, '2026-11-10 11:50:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (452, 16, 3240, 89, 'multi', 1.6, '依据《中华人民共和国家庭教育促进法》，未成年人的父母或者其他监护人实施家庭教育时，应当关注的内容包括（　）', '[["A","教育未成年人爱党、爱国、爱人民、爱集体、爱社会主义，培养家国情怀"],["B","只需关注学业成绩，其他方面可暂不涉及"],["C","教育未成年人崇德向善，培养家庭美德与个人品德，增强法治意识"],["D","树立正确劳动观念，培养生活自理能力与吃苦耐劳品质"],["E","家庭教育由学校统一安排，家长无需主动实施"]]', '["A","C","D"]', '《家庭教育促进法》第十六条规定家庭教育应关注家国情怀培养、崇德向善与法治意识、正确成才观与身心健康、劳动观念与生活自理能力等方面；“只需关注学业成绩”“由学校统一安排、家长无需主动实施”均违背父母或其他监护人的家庭教育主体责任。', '["A"]', 0, 0.0, '2026-11-10 11:50:38');
INSERT INTO `answers` (`id`, `attempt_id`, `question_id`, `seq`, `type`, `score`, `stem`, `options`, `answer`, `analysis`, `chosen`, `is_correct`, `earned`, `answered_at`) VALUES (453, 16, 3241, 90, 'multi', 1.6, '某市教研室组织教师集中研读《义务教育课程方案（2022年版）》及各学科课程标准。关于该方案对各学校课程实施、学段衔接与评价改革提出的要求，下列说法正确的有（　）', '[["A","各学科课程标准以核心素养为纲，强化学科实践与综合性学习"],["B","跨学科主题学习由学校自行决定是否开设，方案不作统一要求"],["C","方案要求加强学段衔接，合理设计不同学段的学习内容与要求"],["D","该方案取消了综合实践活动课程，课时全部并入语文、数学、英语等学科"],["E","学校应因地制宜统筹实施综合实践活动、劳动、地方课程与校本课程"]]', '["A","C","E"]', '2022版课程方案要求各学科课程标准以核心素养为纲、强化学科实践与综合性学习，加强学段衔接，学校因地制宜统筹实施综合实践活动、劳动、地方课程与校本课程；跨学科主题学习有明确的课时比例要求，综合实践活动课程亦未被取消。', '["A"]', 0, 0.0, '2026-11-10 11:50:39');
